  // src/script/config/ConfigUtil.ts
  var ConfigUtil = class {
  };
  ConfigUtil.Tables = null;
  var _ConfigLoader = class _ConfigLoader {
    static loadConfigName() {
      _ConfigLoader.jsonFileNames = Tables.getTableNames();
    }
    static loadAllConfig(callback) {
      this.loadConfigName();
      this.loadCfg(callback);
    }
    static loadCfg(callback) {
      let useTestCfg = false;
      let testCfgUrl = "";
      if (DeviceUtils.ins().isDevelop()) {
        const localCfg = DeviceUtils.ins().getQueryVariable("testcfg");
        if (!StringUtils.isNullOrEmpty(localCfg)) {
          useTestCfg = true;
          testCfgUrl = localCfg.startsWith("http") ? localCfg : `${AppConfig.url}/convert`;
        }
      }
      let url = this._configPath;
      if (useTestCfg) {
        url = `${testCfgUrl}/configbin.bin?v=${Date.now()}`;
        console.log("useTestCfg", url);
      }
      Laya.loader.load(url, Laya.Handler.create(this, (res) => {
        if (!res) {
          console.log("loadCfg failed", url);
          Laya.timer.once(500, this, () => {
            this.loadCfg(callback);
          });
        } else {
          let packRes = PackRes.parse(res.data, this._configPath);
          _ConfigLoader.configPackRes = packRes;
          ConfigUtil.Tables = new Tables(this.getFileData);
          callback && callback.runWith(true);
        }
      }), null, Laya.Loader.BUFFER, 0, true);
    }
    static getFileData(fileName) {
      let data = _ConfigLoader.configPackRes.getRes("config/" + fileName);
      if (data instanceof ArrayBuffer) {
        return new ByteBuf(new Uint8Array(data));
      }
      return null;
    }
  };
  _ConfigLoader.jsonFileNames = [];
  _ConfigLoader._configPath = "config/configbin.bin";
  _ConfigLoader.configPackRes = null;
  var ConfigLoader = _ConfigLoader;

