    /*******************************录屏 begin******************************* */
    isRecordeSupported() {
      if (DeviceUtils.ins().compareVersion(this.systemInfo.SDKVersion, "2.26.1") < 0)
        return false;
      if (this.systemInfo.platform == "android" && this.systemInfo.benchmarkLevel < 25) {
        return false;
      }
      if (this.systemInfo.platform == "ios") {
        return false;
      }
      return true;
    }
    /**开始录屏 */
    startRecorder() {
      if (!this.isRecordeSupported()) {
        console.log("不支持录屏");
        return;
      }
      if (this.startRecord == true)
        return;
      const t = wx.getGameRecorder();
      if (t.isFrameSupported()) {
        if (this._init == false) {
          let self = this;
          self._init = true;
          t.on("start", () => {
            console.log("start");
            self.startRecord = true;
          });
          t.on("error", (res) => {
            self.startRecord = false;
            console.log("错误码", res.error.code);
            console.log("错误信息", res.error.message);
          });
          t.on("stop", (res) => {
            self.startRecord = false;
            console.log("视频时长", res.duration);
          });
          t.on("resume", () => {
            console.log("resume");
          });
          t.on("pause", () => {
            console.log("pause");
          });
          t.on("abort", () => {
            console.log("abort");
          });
          t.on("timeUpdate", (res) => {
          });
        }
        t.start({ hookBgm: false });
      }
    }
    /** 暂停录制 */
    recordClip() {
      if (!this.startRecord)
        return;
      const t = wx.getGameRecorder();
      t.pause().catch((res) => {
        console.log("recordClip", res);
      });
    }
    /**恢复录制 */
    resumeRecorder() {
      if (this.startRecord) {
        const t = wx.getGameRecorder();
        t.resume().catch((res) => {
          console.log("resumeRecorder", res);
        });
      } else {
        this.startRecorder();
      }
    }
    /**停止录屏 */
    stopRecorder() {
      if (!this.startRecord)
        return;
      const t = wx.getGameRecorder();
      t.stop().catch((res) => {
        console.log("stopRecorder", res);
      });
    }
    abortRecorder() {
      if (!this.startRecord)
        return;
      const t = wx.getGameRecorder();
      t.abort();
    }
    operateGameRecorderVideo(object) {
    }
    setPreferredFramesPerSecond(fps) {
      this.systemInfo.platform != "windows" && wx.setPreferredFramesPerSecond(fps);
    }
