    /*******************************录屏 end******************************* */
    writeFile(fileName, data, encoding, success, fail) {
      const fs = wx.getFileSystemManager();
      let path = this.makePath(fileName);
      fs.writeFile({
        filePath: path,
        data,
        encoding: encoding ? encoding : "utf8",
        success(res) {
          console.log(res);
          if (success) {
            success(path);
          }
        },
        fail(res) {
          console.error(res);
          if (fail) {
            fail(res);
          }
        }
      });
    }
    readFile(fileName, encoding, position, length, success, fail) {
      const fs = wx.getFileSystemManager();
      fs.readFile({
        filePath: this.makePath(fileName),
        encoding,
        position: 0,
        success(res) {
          if (success) {
            success(res);
          }
        },
        fail(res) {
          console.error(res);
          if (fail) {
            fail(res);
          }
        }
      });
    }
    access(file, success, fail) {
      const fs = wx.getFileSystemManager();
      if (typeof fs.access === "function") {
        let path = this.makePath(file);
        fs.access({
          path,
          success,
          fail
        });
      }
    }
    getFileInfo(fileUrl) {
      return Laya.PAL.fs.readFile(fileUrl);
    }
