  var WebUtil = class {
    /**
     * 上传文件
     * @param fileName 文件名
     * @param fileDir 文件目录{"log":log文件,"battle_record":临时对局文件,"battle_record_forever":对局文件,"file_upload":DIY对局文件,"voice_upload":语音文件}
     * @param data 文件数据
     * @param type 文件类型
     * @param callback 回调函数
     */
    static UploadFile(fileName, fileDir, data, type, callback, notify = false) {
      let xhr = new Laya.HttpRequest();
      xhr.http.timeout = 6e3;
      xhr.http.ontimeout = () => {
      };
      let onEventCall = (data2) => {
        xhr.http.ontimeout = null;
        xhr.off(Laya.Event.COMPLETE, this, onEventCall);
        xhr.off(Laya.Event.ERROR, this, onEventCall);
        if (xhr.http.status == 200) {
          callback == null ? void 0 : callback({ "errcode": 0, "msg": "上传成功", path: fileName });
          if (notify) {
            let url = "https://qyapi.weixin.qq.com/cgi-bin/webhook/send?key=a1d02916-86e1-42ea-af86-926b6f6ef935";
            Reporter.sendMsgToWework(url, "上传文件成功: https://res-app-ball.1cent.xyz/pool2/" + fileDir + "/" + fileName);
          }
        } else {
          callback == null ? void 0 : callback({ "errcode": 1, "msg": "上传失败code:" + xhr.http.status });
        }
      };
      let dirNum = { "log": 1, "battle_record": 2, "battle_record_forever": 3, "voice_upload": 4, "file_upload": 5 };
      if (!dirNum[fileDir]) {
        callback == null ? void 0 : callback({ "errcode": 1, "msg": "上传失败，不能上传到" + fileDir + "目录" });
        return;
      }
      let fileDirIndex = dirNum[fileDir];
      const sign = CryptoJS.MD5(fileDirIndex + fileName + "l5uHRmgx6xCbmk4o0Fzw7zLeF8SvAwWF").toString();
      xhr.once(Laya.Event.COMPLETE, this, onEventCall);
      xhr.once(Laya.Event.ERROR, this, onEventCall);
      xhr.send(this._uploadUrl + "?sign=" + sign + "&fileName=" + fileName + "&channel=" + GamePlatform.channel + "&filePath=" + fileDirIndex, data, "post", type);
    }
  };
  WebUtil._uploadUrl = "https://file.h5ball.1cent.xyz/h5_file_upload/upload_file2.php";

