  var TipsData = class extends BaseClass {
    /**
     * 根据错误id获取错误配置
     * @param id 错误id
     */
    getErrorCfg(id) {
      const cfg = ConfigUtil.Tables.err_code.get(id);
      return cfg;
    }
    /**
     * 根据提示类型获取一条随机提示
     * @param t 类型
     */
    getRandomTipByType(t) {
      let list = ConfigUtil.Tables.tips.getDataList();
      let tips2 = [];
      for (let i in list) {
        if (list[i].type == t) {
          tips2.push(list[i]);
        }
      }
      if (tips2.length > 0) {
        return tips2[Math.floor(Math.random() * tips2.length)];
      }
      return null;
    }
  };

