  // src/script/module/main/ctrl/ItemIconCtrl.ts
  var ItemIconCtrl = class {
    constructor(rootNode, enableTips = true) {
      this.rootNode = rootNode;
      this.enableTips = enableTips;
      this._thingId = 0;
      this.img_icon = ElemFinder.getElement(rootNode, "img_icon");
      this.txt_num = ElemFinder.getElement(rootNode, "txt_num");
      this.img_quality = ElemFinder.getElement(rootNode, "img_quality");
      if (enableTips) {
        UIUtils.addClickListener(rootNode, this, this.onClick);
      }
    }
    /**
     * 设置是否显示背景
     * @param value 
     */
    setBgActive(value) {
      UIUtils.setActive(this.img_quality, value);
    }
    /**
     * 设置是否显示字体
     */
    setNumActive(value) {
      UIUtils.setActive(this.txt_num, value);
    }
    /**
     * 更新物品图标
     * @param thingId 物品id
     * @param thingNum 物品数量 默认 = 0
     * @param thingMax 最大物品数量，如果赋值，数量会展示为0/100的形式
     */
    update(thingId, thingNum = 0, thingMax = 0) {
      this.updateIconAndNum(thingId, thingNum, thingMax);
      this.img_quality.src = "";
      const thingCfg = ThingData.ins().getThingConfig(thingId);
      if (thingCfg) {
        let sprite = `ui_icon_frame${thingCfg.quality}`;
        this.img_quality.src = UIUtils.getImageUrl("itemBg", sprite);
      } else {
        console.error("配置null:" + thingId);
      }
    }
    /**
     * 使用的其他的新的物品品质背景
     * @param thingId 物品id
     * @param thingNum 物品数量 默认 = 0
     * @param thingMax 最大物品数量，如果赋值，数量会展示为0/100的形式
     */
    updateQualityBg(thingId, thingNum = 0, thingMax = 0) {
      this.updateIconAndNum(thingId, thingNum, thingMax);
      const thingCfg = ThingData.ins().getThingConfig(thingId);
      if (thingCfg) {
        let sprite = `ui_bg_djk_${thingCfg.quality}`;
        this.img_quality.src = UIUtils.getImageUrl("itemFrameBg", sprite);
      } else {
        console.error("配置null:" + thingId);
      }
    }
    /**
     * 更新新的物品图标和数量
     * @param thingId 物品id
     * @param thingNum 物品数量 默认 = 0
     * @param thingMax 最大物品数量，如果赋值，数量会展示为0/100的形式
     */
    updateIconAndNum(thingId, thingNum = 0, thingMax = 0) {
      this._thingId = thingId;
      this.img_icon.src = "";
      this.img_icon.src = ThingUtils.getThingIconPath(thingId);
      if (thingMax > 0) {
        this.txt_num.text = `${DataFormatter.formatSpecialNumber(thingNum)}/${DataFormatter.formatSpecialNumber(thingMax)}`;
      } else {
        this.txt_num.text = thingNum > 0 ? DataFormatter.formatSpecialNumber(thingNum).toString() : "";
      }
    }
    /**
     * 更新基于自定义配置的图标
     * @param cfg 
     */
    updateByCustom(cfg) {
      this._custom = cfg;
      this.img_icon.src = "";
      this.img_quality.src = "";
      this.img_icon.src = cfg.icon;
      this.txt_num.text = "";
      let sprite = `ui_icon_ frame${2}`;
      this.img_quality.src = UIUtils.getImageUrl("itemBg", sprite);
    }
    onClick() {
      this.showTips();
    }
    showTips() {
      if (this._custom) {
        TipsManager.ins().showCustomItemTips(this.img_icon, this.img_icon.width / 2, this.img_icon.height / 2, this._custom);
      } else if (this._thingId > 0) {
        TipsManager.ins().showItemTips(this.img_icon, this.img_icon.width / 2, this.img_icon.height / 2, this._thingId);
      }
    }
  };

