  // src/script/module/login/view/UIReconnectView.ts
  var UIReconnectView = class extends UIBaseView {
    get layer() {
      return 5 /* Top */;
    }
    get path() {
      return "ui/prefab/module/login/UIReconnectView.lh";
    }
    onConstruct() {
      this.box = this.elems.getElement("box");
      this.txt_message = this.elems.getElement("txt_message");
      this.view.mouseThrough = false;
      this.btn_ok = this.elems.getUIButton("btn_ok");
      this.addClickListener(this.btn_ok.rootNode, this.onClickOk);
    }
    onOpen(autoConnectSeconds) {
      if (GameConst.IS_NEED_RECONNECT) {
        this.close();
        return;
      }
      this.autoConnectSeconds = autoConnectSeconds;
      asgard.net.NetManager.close(GameConst.appName);
      this.updateView();
      if (autoConnectSeconds > 0) {
        this.onTimer();
        this.addLoopTimer(1e3, this.onTimer);
        this.addOnceTimer(100, this.connect);
      }
    }
    onClose() {
    }
    updateView() {
      const manualReconnect = this.autoConnectSeconds <= 0;
      UIUtils.setActive(this.box, manualReconnect);
      UIUtils.setActive(this.txt_message, !manualReconnect);
    }
    connect() {
      console.info("自动断线重连 剩余" + this.autoConnectSeconds + "s");
      NetService.connet(AppConfig.wsAddress);
    }
    onTimer() {
      this.txt_message.text = "正在重连中(" + this.autoConnectSeconds + "s)...";
      this.autoConnectSeconds--;
      if (this.autoConnectSeconds % 5 == 0) {
        this.connect();
      }
      if (this.autoConnectSeconds < 0) {
        this.removeTimer(this.onTimer);
        this.updateView();
      }
    }
    /**
     * 点击确认
     */
    onClickOk() {
      GamePlatform.getNetworkType().then((res) => {
        if (res.networkType == "none") {
          TipsManager.ins().showMessageTips("请检查网络后再试！");
        } else {
          this.open(30);
        }
      });
    }
  };

