    /**
     * 限制数量
     * @param count 数量
     */
    limitCount(count) {
      if (count <= 0) {
        count = 1;
      }
      if (!this.buyItem.limitTimes) {
        return count;
      }
      const limitTimes = Math.max(1, this.buyItem.limitTimes - this.buyItem.buyTimes);
      if (count > limitTimes) {
        count = limitTimes;
      }
      return count;
    }
