  var RechargeData = class extends BaseDataClass {
    /**
     * 获取金币兑换列表
     * @returns 金币兑换列表
     */
    getShopCoinList() {
      return ConfigUtil.Tables.exchange.getDataList();
    }
    /**
     * 根据兑换类型获取金币兑换列表
     * @param type 兑换类型
     * @returns 对应类型的兑换数据数组
     */
    getShopCoinListByType(type) {
      return ConfigUtil.Tables.exchange.getDataList().filter((item2) => item2.type_exchange === type);
    }
    /**
     * 获取钻石兑换列表
     * @returns 钻石兑换列表
     */
    getShopZSList() {
      let list = ConfigUtil.Tables.charge_new.getDataList().filter((item2) => {
        return item2.type == 1;
      });
      return list;
    }
    /**
     * 获取钻石充值奖励组列表
     * @returns 充值列表
     */
    getShopZSAwardList() {
      let list = ConfigUtil.Tables.charge_new.getDataList();
      let rewardList = [];
      list.forEach((item2) => {
        rewardList.push(item2.award);
      });
      return rewardList;
    }
    /**
     * 获取钻石礼包通过钻石数量
     */
    getShopZSGift(diamondNum) {
      const dataList = ConfigUtil.Tables.charge_new.getDataList();
      if (!dataList || dataList.length === 0) {
        return null;
      }
      let minSatisfiedItem = null;
      let maxSatisfiedItem = null;
      for (const item2 of dataList) {
        if (item2.type != 1) {
          continue;
        }
        const awardNum = item2.award[0].num;
        if (maxSatisfiedItem === null || awardNum > maxSatisfiedItem.award[0].num) {
          maxSatisfiedItem = item2;
        }
        if (awardNum < diamondNum) {
          continue;
        }
        if (minSatisfiedItem === null || awardNum < minSatisfiedItem.award[0].num) {
          minSatisfiedItem = item2;
        }
      }
      if (!minSatisfiedItem) {
        minSatisfiedItem = maxSatisfiedItem;
      }
      return minSatisfiedItem;
    }
    /**
     * 获取充值配置
     * @param id 充值id 
     * @returns 
     */
    getChargeNewCfg(id) {
      return ConfigUtil.Tables.charge_new.get(id);
    }
  };

