  var UIMoonCardView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/mooncard/UIMoonCardView.lh";
    }
    onConstruct() {
      this.list_mooncard = this.elems.getList("list_mooncard");
      this.list_mooncard.itemCtrl = MoonCardListCtrl;
      this.btn_gift = this.elems.getElement("btn_gift");
      this.btn_duigou = ElemFinder.getImage(this.btn_gift, "btn_duigou");
      this.redDot = ElemFinder.getWidget(this.btn_gift, "redDot");
      this.addClickListener(this.btn_gift, this.onClickGift);
    }
    onRegisterEvent() {
      this.registerEvent(21 /* MoonCardChange */, this.updateView);
    }
    onOpen(...args) {
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      this.list_mooncard.array = MoonCardData.ins().getMoonCardList();
      this.refreshBannerDailyGift();
    }
    /** Banner 每日礼：可领高亮；已领完置灰+勾；无在期月卡置灰无勾 */
    refreshBannerDailyGift() {
      if (!this.btn_gift) {
        return;
      }
      const canClaim = !MoonCardUtils.isHasDayFreeReward();
      UIUtils.setActive(this.btn_gift, true);
      if (this.btn_duigou) {
        UIUtils.setActive(this.btn_duigou, !canClaim);
        UIUtils.setActive(this.redDot, canClaim);
      }
      if (canClaim) {
        UIUtils.setNodeFilterColor(this.btn_gift, "#FFFFFF");
      } else {
        UIUtils.setNodeFilterColor(this.btn_gift, "#A0A0A0");
      }
    }
    onClickGift() {
      if (!MoonCardUtils.isHasDayFreeReward()) {
        MoonCardProtoUtils.player_get_day_free_reward_c2s(3);
        console.log("领取第3档的奖励");
        return;
      }
      if (MoonCardUtils.isHasDayFreeReward()) {
        TipsManager.ins().showMessageTips("明日可继续领取");
        return;
      }
    }
  };

