  // src/script/module/dress/utils/DressUtils.ts
  var DressUtils = class _DressUtils {
    /**
     * 获取头像资源路径
     * @param headId 头像id 
     * @param sex 性别
     */
    static getHeadIconPath(headId, sex) {
      if (headId && headId.startsWith("aihead")) {
        return `ui/texture/${headId}`;
      } else if (parseInt(headId) || StringUtils.isNullOrEmpty(headId)) {
        let dressCfg = DressData.ins().getDressCfg(parseInt(headId));
        if (!dressCfg) {
          dressCfg = DressData.ins().getDressCfg(sex == 1 /* MAN */ ? DressConst.defaultHeadIconMale : DressConst.defaultHeadIconFemale);
        }
        let itemCfg = ThingData.ins().getThingConfig(dressCfg.item_id);
        const icon = itemCfg ? itemCfg.icon : `icon_${dressCfg.item_id}`;
        return UIUtils.getImageUrl("headIcon", icon);
      } else {
        return headId;
      }
    }
    /**
     * 获取头像框资源路径
     * @param id id 
     */
    static getHeadFramePath(id) {
      let dressCfg = DressData.ins().getDressCfg(id);
      if (!dressCfg) {
        dressCfg = DressData.ins().getDressCfg(DressConst.defaultHeadFrame);
      }
      const itemCfg = ThingData.ins().getThingConfig(dressCfg.item_id);
      const icon = itemCfg ? itemCfg.icon : `icon_${dressCfg.item_id}`;
      return UIUtils.getImageUrl("headFrame", icon);
    }
    /**
     * 获取聊天气泡资源路径
     * @param id id 
     */
    static getChatBubblePath(id) {
      let dressCfg = DressData.ins().getDressCfg(id);
      if (!dressCfg) {
        dressCfg = DressData.ins().getDressCfg(DressConst.defaultChatBubble);
      }
      const itemCfg = ThingData.ins().getThingConfig(dressCfg.item_id);
      const icon = itemCfg ? itemCfg.icon : `icon_${dressCfg.item_id}`;
      return UIUtils.getTextureUrl("chatBubble", icon);
    }
    /**
     * 获取聊天称号资源路径
     * @param id id 
     */
    static getTitlePath(id) {
      let dressCfg = DressData.ins().getTitleCfg(id);
      if (!dressCfg) {
        dressCfg = DressData.ins().getTitleCfg(DressConst.defaultTitle);
      }
      const itemCfg = ThingData.ins().getThingConfig(dressCfg.id);
      const icon = itemCfg ? itemCfg.icon : `icon_${dressCfg.id}`;
      if (icon == "0") {
        return "";
      }
      return UIUtils.getTextureUrl("itemIcon", icon);
    }
    /**
     * 获取处理后的称号名称
     * @param titleId 称号ID
     * @param titleData 称号额外数据
     * @param isSelf 是否查看自己
     * @returns 处理后的称号名称
     */
    static getProcessedTitleName(titleId, titleData = null, isSelf = true) {
      const titleCfg = DressData.ins().getTitleCfg(titleId);
      if (!titleCfg) {
        return "";
      }
      let titleName = LangData.ins().getLang(titleCfg.title_name);
      if (titleName.includes("[{0}]")) {
        let playerName = "";
        if (isSelf) {
          playerName = DressData.ins().usingTitleExtra || "";
        } else {
          playerName = titleData || "";
        }
        if (!playerName) {
          playerName = "***";
        }
        titleName = titleName.replace("[{0}]", playerName);
      }
      return titleName;
    }
    /**
     * 对数据进行排序
     * 默认规则是 1.拥有 2 order 3 item id
     * @param list 数据列表
     */
    static defaultSortDressList(list) {
      list.sort((a, b) => {
        const aActive = ThingUtils.isThingExpired(a.item_id) ? 0 : 1;
        const bActive = ThingUtils.isThingExpired(b.item_id) ? 0 : 1;
        if (aActive != bActive) {
          return bActive - aActive;
        }
        if (a.order != b.order) {
          return a.order - b.order;
        }
        return a.item_id - b.item_id;
      });
    }
    /**
     * 对称号数据进行排序
     * 排序规则：默认称号 > 已拥有或者已经领取的称号 > 任务称号待领取 > ID
     * @param list 数据列表
     */
    static defaultSortTitleList(list) {
      list.sort((a, b) => {
        if (a.id === DressConst.defaultTitle)
          return -1;
        if (b.id === DressConst.defaultTitle)
          return 1;
        const aHas = _DressUtils.isTitleOwned(a);
        const bHas = _DressUtils.isTitleOwned(b);
        const aCanClaim = _DressUtils.isTitleCanClaim(a);
        const bCanClaim = _DressUtils.isTitleCanClaim(b);
        if (aHas && !bHas)
          return -1;
        if (!aHas && bHas)
          return 1;
        if (aHas && bHas) {
          if (aCanClaim && !bCanClaim)
            return 1;
          if (!aCanClaim && bCanClaim)
            return -1;
        }
        return a.id - b.id;
      });
    }
    /**
     * 判断称号是否已拥有（包括背包下发和任务领取的）
     */
    static isTitleOwned(title2) {
      const task2 = TaskData.ins().getTasksByType(4 /* TITLE_TASK */);
      const taskId = task2.find((item2) => item2.id == title2.title_taskid);
      if (taskId) {
        const taskStatus = TaskData.ins().getTaskStatus(taskId.id);
        return taskStatus == 2 || taskStatus == 3;
      } else {
        return !ThingUtils.isThingExpired(title2.id);
      }
    }
    /**
     * 判断称号是否是任务称号待领取（任务状态为2）
     */
    static isTitleCanClaim(title2) {
      const task2 = TaskData.ins().getTasksByType(4 /* TITLE_TASK */);
      const taskId = task2.find((item2) => item2.id == title2.title_taskid);
      if (taskId) {
        const taskStatus = TaskData.ins().getTaskStatus(taskId.id);
        return taskStatus == 2;
      }
      return false;
    }
  };

