  // src/script/module/chat/data/ChatData.ts
  var ChatData = class extends BaseDataClass {
    constructor() {
      super(...arguments);
      this._worldChatCDEndAt = 0;
      this.ChatNewCountDic = /* @__PURE__ */ new Map();
      /**屏蔽消息的玩家id数组 */
      this.DisMsgIds = [];
      this._worldInviteCDEndAt = 0;
      this._lobbyMsg = null;
      this._speakerMsg = null;
      /**
       * 分频道消息缓存
       */
      this._chatMsgCache = {};
      /**
       * 私聊消息缓存
       */
      this._privateChatMsgCache = {};
      this._contactList = [];
      this._strangerContactList = [];
      /**
       * 新消息列表(包括俱乐部和联系人)
       */
      this._newMessages = /* @__PURE__ */ new Map();
      /**
       * 俱乐部新消息数量（俱乐部新消息改用_newMessages统一存储，便于打开消息时定位聊天位置。getNewMessageNum获取俱乐部新消息数量）
       */
      //public clubNewMessageNum = 0;
      /**
       * 喇叭消息
       */
      this.speakerWorldMsgData = null;
      this._worldRoomMsg = [];
    }
    /**
     * 世界聊天冷却目标时间
     */
    get worldChatCDEndAt() {
      return this._worldChatCDEndAt;
    }
    /**
     * 世界聊天邀请消息目标时间
     */
    get worldInviteCDEndAt() {
      return this._worldInviteCDEndAt;
    }
    /**
     * 用于在大厅显示的消息
     */
    get lobbyMsg() {
      return this._lobbyMsg;
    }
    /**
     * 喇叭消息
     */
    get speakerMsg() {
      return this._speakerMsg;
    }
    /**
     * 联系人列表
     */
    get contactList() {
      return this._contactList;
    }
    /**
     * 陌生人列表
     */
    get strangerContactList() {
      return this._strangerContactList;
    }
    get newMessages() {
      return this._newMessages;
    }
    /**
     * 房间消息
     */
    get worldRoomMsg() {
      return this._worldRoomMsg;
    }
    /**
     * 根据类型获取表情组
     * @param type
     * @returns 
     */
    getEmoList() {
      let arr = [];
      let res = ConfigUtil.Tables.chat_expression.getDataList();
      for (let i in res) {
        if (res[i].type_cost === 0 || res[i].type_cost === 3 || res[i].type_cost === 6) {
          arr.push(res[i]);
        } else if (res[i].type_cost === 5) {
          if (!ThingUtils.isThingExpired(res[i].expression_id)) {
            arr.push(res[i]);
          }
        }
      }
      return arr;
    }
    /**
     * 添加到消息缓存
     * @param msg 消息
     */
    addNewMsg(msg) {
      if (msg.type == cmd.CHAT_TYPE.SYSTEM || msg.type == cmd.CHAT_TYPE.TIME || msg.type == cmd.CHAT_TYPE.AUDIO) {
      } else {
        if (msg.type === cmd.CHAT_TYPE.LOUDSPEAKER) {
          this._speakerMsg = msg;
        } else {
          if (!this._lobbyMsg || msg.time > this._lobbyMsg.time) {
            this._lobbyMsg = msg;
          }
        }
      }
      if (msg.totype == cmd.CHAT_TO_TYPE.CTT_PLAYER) {
        let keyId = msg.toid === PlayerData.ins().playerId ? msg.fromid : msg.toid;
        let arr = this._privateChatMsgCache[keyId];
        if (!arr) {
          this._privateChatMsgCache[keyId] = arr = [];
        }
        arr.push(msg);
        if (arr.length > ChatConst.MAX_CHAT_CACHE_LEN) {
          arr.splice(0, 1);
        }
      } else {
        let arr = this._chatMsgCache[msg.totype];
        if (!arr) {
          this._chatMsgCache[msg.totype] = arr = [];
        }
        arr.push(msg);
        if (arr.length > ChatConst.MAX_CHAT_CACHE_LEN) {
          arr.splice(0, 1);
        }
      }
    }
    /**
     * 将历史消息添加到消息缓存
     * 注意，历史消息是倒着进入列表
     */
    addMsgRecordList(totype, toid, msgList) {
      if (totype == cmd.CHAT_TO_TYPE.CTT_PLAYER) {
        let arr = this._privateChatMsgCache[toid];
        if (!arr) {
          this._privateChatMsgCache[toid] = arr = [];
        }
        for (let msg of msgList) {
          arr.unshift(msg);
        }
      } else {
        let arr = this._chatMsgCache[totype];
        if (!arr) {
          this._chatMsgCache[totype] = arr = [];
        }
        for (let msg of msgList) {
          arr.unshift(msg);
        }
      }
    }
    /**
     * 根据频道获取聊天缓存
     * @param totype 频道
     * @returns 
     */
    getChatMsgList(totype) {
      return this._chatMsgCache[totype];
    }
    /**
     * 获取私聊缓存
     * @param totype 频道
     * @returns 
     */
    getPrivateChatMsgList(playerId) {
      return this._privateChatMsgCache[playerId];
    }
    /**
     * 初始化
     */
    initAfterLogin() {
      this._chatMsgCache = {};
      this._privateChatMsgCache = {};
      this._newMessages.clear();
      {
        const contacts = PlayerLocalStorageManager.ins().getJson("chat", "contacts");
        if (contacts) {
          this._contactList = contacts;
        }
      }
      {
        const contacts = PlayerLocalStorageManager.ins().getJson("chat", "s_contacts");
        if (contacts) {
          this._strangerContactList = contacts;
        }
      }
    }
    /**
     * 保存联系人
     */
    saveContact() {
      PlayerLocalStorageManager.ins().saveString("chat", "contacts", JSON.stringify(this._contactList));
    }
    /**
     * 添加联系人
     */
    addContact(userid) {
      if (userid <= 0 || this._contactList.indexOf(userid) > -1) {
        return false;
      }
      this._contactList.unshift(userid);
      this.saveContact();
      return true;
    }
    /**
     * 删除联系人
     */
    removeContact(userid) {
      const index = this._contactList.indexOf(userid);
      if (index == -1) {
        return;
      }
      this._contactList.splice(index, 1);
      this.saveContact();
    }
    /**
     * 保存陌生人
     */
    saveStrangerContact() {
      PlayerLocalStorageManager.ins().saveString("chat", "s_contacts", JSON.stringify(this._strangerContactList));
    }
    /**
     * 添加陌生人
     */
    addStrangerContact(userid) {
      if (userid <= 0 || this._strangerContactList.indexOf(userid) > -1) {
        return false;
      }
      this._strangerContactList.unshift(userid);
      this.saveStrangerContact();
      return true;
    }
    /**
     * 删除陌生人
     */
    removeStrangerContact(userid) {
      const index = this._strangerContactList.indexOf(userid);
      if (index == -1) {
        return;
      }
      this._strangerContactList.splice(index, 1);
      this.saveStrangerContact();
    }
    /**
     * 更新联系人类型
     * @param userid 玩家id
     * @param follow 是否关注
     */
    updateContactType(userid, follow) {
      if (follow) {
        const index = this._strangerContactList.indexOf(userid);
        if (index > -1) {
          this._strangerContactList.splice(index, 1);
          this.saveStrangerContact();
          this.addContact(userid);
        }
      } else {
        const index = this._contactList.indexOf(userid);
        if (index > -1) {
          this._contactList.splice(index, 1);
          this.saveContact();
          this.addStrangerContact(userid);
        }
      }
    }
    /**
     * 添加玩家新消息数量
     * @param userid 玩家id
     * @param num 消息
     */
    addNewMessageNum(userid, newnum) {
      let num = 0;
      if (this._newMessages.has(userid)) {
        num = this._newMessages.get(userid);
        this._newMessages.set(userid, num + newnum);
      } else {
        this._newMessages.set(userid, newnum);
      }
    }
    /**
     * 获取新消息数量
     * @param userid 玩家id
     * @returns 
     */
    getNewMessageNum(userid) {
      return this._newMessages.get(userid) || 0;
    }
    /**
     * 清楚新消息
     * @param userid 玩家id
     * @returns 
     */
    deleteNewMessage(userid) {
      return this._newMessages.delete(userid);
    }
    /**
     * 获取聊天cd
     */
    getChatCD() {
      const baseTime = CommonData.ins().getCommonCfg(ChatConst.CHAT_CD_ID).int_value;
      const privTime = SubscribeUtils.getPrivilegeValue(6 /* speak_interval */);
      if (privTime > 0) {
        return Math.min(baseTime, privTime);
      }
      return baseTime;
    }
    /**
     * 获取邀请cd
     * @returns 
     */
    getInviteCD() {
      const baseTime = CommonData.ins().getCommonCfg(ChatConst.INVITE_CD_ID).int_value;
      return baseTime;
    }
    /**
     * 开始聊天冷却cd
     */
    startWorldChatCD() {
      this._worldChatCDEndAt = TimeData.ins().serverTimeS + this.getChatCD();
    }
    /**
     * 开始邀请冷却cd
     */
    startWorldInviteCD() {
      this._worldInviteCDEndAt = TimeData.ins().serverTimeS + this.getInviteCD();
    }
    /**
     * 获取本地系统提示文本
     * @param type 消息类型
     * @returns 
     */
    getSystemTipMessage(type) {
      let context = "";
      let tipType = 3;
      if (type == cmd.CHAT_TO_TYPE.CTT_WORLD) {
        tipType = 3;
      } else {
        tipType = 6;
      }
      const tipCfg = TipsData.ins().getRandomTipByType(tipType);
      if (tipCfg) {
        context = LangData.ins().getLang(tipCfg.text);
      } else {
        context = "系统提示: 请警惕任何代充送钻的行为，遇到恶意消息，请\n长按消息举报交由客服处理";
      }
      let msg = new cmd.chat_msg();
      msg.context = context;
      msg.type = cmd.CHAT_TYPE.SYSTEM;
      msg.toid = 0;
      msg.totype = type;
      return msg;
    }
    /**
     * 添加新的房间消息
     * @param msg 
     */
    addWorldRoom(msg) {
      for (let i = 0; i < this._worldRoomMsg.length; i++) {
        let roomId = parseInt(msg.extra_param[0]);
        if (roomId === parseInt(this._worldRoomMsg[i].extra_param[0])) {
          this._worldRoomMsg.splice(i, 1);
          break;
        }
      }
      if (this._worldRoomMsg.length >= 50) {
        this._worldRoomMsg.shift();
      }
      this._worldRoomMsg.push(msg);
    }
  };

