  // src/script/utils/ModelUtils.ts
  var ModelUtils = class {
    /**
     * 遍历节点查找子对象
     * @param parent 要查找的目标节点
     * @param name 子节点名称
     * @returns 找到的节点对象，如果未找到则返回null
     */
    static findNode(parent, name) {
      if (parent == null) {
        return null;
      }
      for (let index = 0; index < parent.numChildren; index++) {
        const element = parent.getChildAt(index);
        if (element.name == name) {
          return element;
        }
        if (element.numChildren > 0) {
          let n = this.findNode(element, name);
          if (n) {
            return n;
          }
        }
      }
      return null;
    }
  };

