  var GuideGameData = class extends BaseClass {
    constructor() {
      super(...arguments);
      this._levelId = 1001;
      //某一个关卡配置  进入对局
      this.CurrConfig = null;
    }
    clear() {
      this.CurrConfig = null;
    }
    setCurrentConfig() {
      this.CurrConfig = ConfigUtil.Tables.pveConfig.get(this._levelId);
    }
    /**
       * 统一从关卡配置中计算目标球列表：
       * - 当 goalBall 为 1：返回 [1..7] 与 ballPos 中的摆放球取交集（若未配置 ballPos，则返回 [1..7]）
       * - 当 goalBall 为 2：返回 [9..15] 与摆放球取交集
       * - 当 goalBall 为 8：若摆放中包含 8 则返回 [8]，否则 [8]
       * - 当 goalBall 为其他正数：返回 [goalBall]
       * - 其他情况：兜底为 [1..7] 与摆放球取交集
       */
    getTargetBallsFromConfig(config) {
      if (!config)
        return [];
      const placedIds = [];
      const ballPosStr = config.ballPos;
      if (ballPosStr && ballPosStr.length > 0) {
        const parts = ballPosStr.split(";");
        for (const part of parts) {
          const trimmed = part.trim();
          if (!trimmed)
            continue;
          const colonIndex = trimmed.indexOf(":");
          if (colonIndex > 0) {
            const idPart = trimmed.substring(0, colonIndex);
            const id = Number(idPart);
            if (!Number.isNaN(id) && id !== 0) {
              placedIds.push(id);
            }
          }
        }
      }
      let targets = [];
      if (config.goalBall === 1) {
        const small = [1, 2, 3, 4, 5, 6, 7];
        targets = placedIds.length > 0 ? small.filter((id) => placedIds.indexOf(id) !== -1) : small;
      } else if (config.goalBall === 2) {
        const big = [9, 10, 11, 12, 13, 14, 15];
        targets = placedIds.length > 0 ? big.filter((id) => placedIds.indexOf(id) !== -1) : big;
      } else if (config.goalBall === 8) {
        targets = placedIds.length > 0 ? placedIds.filter((id) => id === 8) : [8];
      } else if (config.goalBall > 0) {
        targets = [config.goalBall];
      } else {
        const small = [1, 2, 3, 4, 5, 6, 7];
        targets = placedIds.length > 0 ? small.filter((id) => placedIds.indexOf(id) !== -1) : small;
      }
      return targets.filter((id) => id > 0);
    }
  };
  window["GuideGameData"] = GuideGameData;

