  function GetFoulMsg(foul) {
    const cfg = ConfigUtil.Tables.broadcast_2.get(foul);
    if (!cfg) {
      return "未配置" + foul;
    }
    return LangData.ins().getLang(cfg.broadcast_name);
  }

