  var LoginConnetServerHelper = class extends BaseClass {
    constructor() {
      super(...arguments);
      this.loginBasePath = " https://jztq-h5.1cent.xyz/";
      /**登录过期时间 */
      this.expire_time = 0;
    }
    init() {
      this.loginUrl = `${this.loginBasePath}${GamePlatform.loginUrl}`;
    }
    connetServer() {
      LoadingUtils.SetLoadingProgressTxt(5 /* PLATFORM_LOGIN */);
      if (DeviceUtils.ins().isMiniGame) {
        this._connetServerMiniGame();
      } else {
        this._connetSercerDefault();
      }
    }
    /**小游戏渠道 连接游戏服*/
    _connetServerMiniGame() {
      GamePlatform.login().then((res) => {
        this._loginHttpWx4399();
      }).catch((err) => {
        console.error("登录失败", err);
      });
    }
    /**sdk登录成功后，调用http登录*/
    _loginHttpWx4399() {
      let sdkInfo = GamePlatform.sdkInfo;
      if (!sdkInfo) {
        console.error("sdkInfo为空");
        return;
      }
      let ext = typeof sdkInfo.sdkLoginExt === "string" ? sdkInfo.sdkLoginExt : JSON.stringify(sdkInfo.sdkLoginExt);
      let url = this.loginUrl + `?name=${encodeURIComponent(sdkInfo.sdkLoginName)}&uid=${encodeURIComponent(sdkInfo.sdkLoginUid)}&ext=${encodeURIComponent(ext)}&channel=${LoginData.ins().channel}&version=${AppConfig.version}`;
      console.log("登录请求", url);
      LoadingUtils.SetLoadingProgressTxt(6 /* LOGIN_SERVER */);
      ResLoader.beginHttpRequest(url, (error, res) => {
        if (error) {
          console.error("登录失败", error);
          return;
        }
        console.log("登录成功", res);
        let data = JSON.parse(res);
        if (data.errcode == 0) {
          try {
            GamePlatform.sdkInfo.sdkLoginUid = data.extra.content.uid;
            GamePlatform.sdkInfo.sdkLoginName = data.extra.content.name;
            GamePlatform.sdkLoginExtServer = JSON.stringify(data.extra);
            GamePlatform.DoFNSDKLoginFinishRecord();
          } catch (e) {
            console.error("minigame sdk info error " + e);
          }
          if (!data.msg) {
            console.error("登录返回数据异常：缺少 msg 字段", data);
          }
          this.handleHttpLoginSucc(data);
          GamePlatform.DoFNSDKLog(5, {});
        } else {
          console.error("登录失败", data);
        }
      });
    }
    /**默认渠道 连接游戏服*/
    _connetSercerDefault() {
      if (DeviceUtils.ins().isDevelop()) {
        const ws = DeviceUtils.ins().getQueryVariable("ws") || Laya.LocalStorage.getItem("ws");
        if (!StringUtils.isNullOrEmpty(ws)) {
          AppConfig.wsAddress = ws;
        }
      }
      this.handleWsAddress();
    }
    /**http登录成功后通用处理 */
    handleHttpLoginSucc(data) {
      this.handleHttpLoginData(data);
      AppConfig.wsAddress = data.address;
      this.handleWsAddress();
    }
    /**登录http成功后对data处理 */
    handleHttpLoginData(data) {
      data.msg && (PlayerData.ins().token = JSON.stringify(data.msg));
      if (data.msg && data.msg.expire_time) {
        this.expire_time = data.msg.expire_time;
      }
      data.msg && data.msg.uid && (PlayerData.ins().openId = data.msg.uid);
      data.userInfo && (this.userInfo = data.userInfo);
    }
    /**设置wsAdress */
    handleWsAddress() {
      LoadingUtils.SetLoadingProgressTxt(7 /* CONNECT_SERVER */);
      NetService.connet(AppConfig.wsAddress);
    }
    /**登录游戏服 toc协议 */
    loginToc() {
      if (DeviceUtils.ins().isMiniGame) {
        let msg = new cmd.account_checkid_login_tos();
        msg.machine_info = GamePlatform.getMachineInfo();
        msg.checkkey = PlayerData.ins().token;
        msg.version = AppConfig.version;
        msg.channel_id = LoginData.ins().channel;
        msg.uid = PlayerData.ins().openId;
        NetService.send(msg);
        return;
      }
      if (!AppConfig.isBanShuEvn()) {
        let msg = new cmd.client_login_tos();
        console.log("client_connect_toc", DeviceUtils.ins().isDevelop(), DeviceUtils.ins().getQueryVariable("name"));
        let varName = DeviceUtils.ins().isDevelop() && DeviceUtils.ins().getQueryVariable("name");
        if (varName) {
          varName = decodeURIComponent(varName);
        }
        let name = varName || Laya.LocalStorage.getItem("name") || Date.now().toString();
        console.log("name", name, Date.now().toString());
        msg.account = name ? name : Date.now().toString();
        msg.agent_id = 2;
        NetService.send(msg);
        Laya.LocalStorage.setItem("name", name);
        return;
      }
    }
  };

