  // src/script/module/poolGame/component/BallInHand.ts
  var BallInHand = class extends GameComponent {
    constructor() {
      super(...arguments);
      this._ignoreFouls = false;
      /**
       * 自动取出母球
       */
      this.autoBallinHand = true;
      this.canMoveAnyBall = false;
      this._distance = Laya.Point.create();
    }
    get startPos() {
      return this.game.table.CueInitPos;
    }
    get movedBall() {
      return this._movedBall;
    }
    set movedBall(value) {
      this._movedBall = value;
    }
    get ballInHand() {
      return this._ballInHand;
    }
    set ballInHand(value) {
      this._ballInHand = value;
    }
    set ignoreFouls(value) {
      this._ignoreFouls = value;
    }
    IsCanMoveBall(ballId) {
      let canMove = this.canMoveAnyBall || ballId == this.game.GetActiveBall().id;
      return canMove;
    }
    CanMoveBall(ballId, pos, checkPocketVal = false) {
      if (!this.IsCanMoveBall(ballId)) {
        return false;
      }
      const canMove = this.game.table.CanMoveBall(ballId, pos, checkPocketVal);
      return canMove;
    }
    MoveBall(ballId, coord) {
      this.game.MoveBall(ballId, coord);
    }
    GetValidMovePosition(pos) {
      return this.game.table.GetValidMovePosition(pos, this.canMoveAnyBall);
    }
    OnShotBegin() {
      this._movedBall = false;
    }
    OnShotAlmostEnd(shotResult) {
      if (this.autoBallinHand && shotResult.pottedBalls.length > 0) {
        let cue3 = this.game.GetActiveBall();
        for (let index = 0; index < shotResult.pottedBalls.length; index++) {
          const element = shotResult.pottedBalls[index];
          if (element.id == cue3.id) {
            this.SetBallInHand();
            break;
          }
        }
      }
    }
    OnShotEnd(shotResult) {
      if (!this._ignoreFouls) {
        this.ballInHand = shotResult.foul != 0 /* NONE */;
      }
    }
    OverrideBallInHand(enable) {
      this.ballInHand = enable;
    }
    SetBallInHand() {
      let cue3 = this.game.GetActiveBall();
      if (cue3.pocketId == 0 /* None */) {
        return;
      }
      cue3.Reset();
      let pos = this.startPos.clone();
      while (!this.CanMoveBall(cue3.id, pos)) {
        pos.z += 0.1;
      }
      cue3.SetPosition(pos, true);
      cue3.active = true;
      this.game.OnActiveBallSink(cue3.id);
    }
    OnReconnect() {
      let base_data = PoolGameManager.ins().gameRoomData.gameData.base_data;
      if (base_data.white_free && base_data.cur_play === this.game.localPlayer.SeatId) {
        this.ballInHand = true;
      }
      let needResetCueBall = false;
      if (base_data.last_one_hit && base_data.last_one_hit.potted_balls) {
        for (let index = 0; index < base_data.last_one_hit.potted_balls.length; index++) {
          const element = base_data.last_one_hit.potted_balls[index];
          if (!element.id) {
            needResetCueBall = true;
            break;
          }
        }
      }
      if (needResetCueBall || base_data.white_free || base_data.step == 0 && (!base_data.last_one_hit || base_data.last_one_hit.frames.length <= 0)) {
        let cue3 = this.game.GetActiveBall();
        cue3.Reset();
        if (base_data.white_ball_status && base_data.white_ball_status.x && base_data.white_ball_status.y) {
          cue3.SetPosition(new Laya.Vector3(
            PoolGameUtils.ConverToClient(base_data.white_ball_status.x),
            this.startPos.y,
            PoolGameUtils.ConverToClient(base_data.white_ball_status.y)
          ), true);
        } else {
          let pos = this.startPos.clone();
          while (!this.CanMoveBall(cue3.id, pos)) {
            pos.z += 0.1;
          }
          cue3.SetPosition(pos, true);
        }
        cue3.active = true;
        this.game.OnActiveBallSink(cue3.id);
      }
    }
    Destroy() {
      super.Destroy();
      this._ballInHand = null;
      this._distance.recover();
      this._distance = null;
    }
  };

