  // src/script/module/poolGame/component/shotTimer/ShotTimer.ts
  var ShotTimer = class extends GameComponent {
    constructor() {
      super(...arguments);
      this._timeUp = false;
    }
    get timeRemaining() {
      return this._timer;
    }
    set timeRemaining(value) {
      this._timer = value;
    }
    get turnDuration() {
      return this.TurnLengthForPlayer(this.game.player.Id, null);
    }
    get percentRemaining() {
      return this._timer / this.turnDuration;
    }
    get paused() {
      return this.game.shotState == 1 /* IN_PROGRESS */ || this.game.shotState == 3 /* TIME_UP */ || this.game.shotState == -1 /* NULL */ || this.game.shotState == 4 /* PLAYING_HIT_RESULT */;
    }
    OnShotBegin() {
      this.timeRemaining = this.turnDuration;
      this._timeUp = false;
    }
    OnShotEnd(result) {
    }
    TurnLengthForPlayer(playerId, turnNumber) {
      let num2 = 30;
      if (turnNumber != null) {
        if (turnNumber === 0) {
          num2 += 10;
        }
      }
      return num2;
    }
    OnTimeUp() {
      this._timeUp = true;
      this.game.shotResult.shotStatus += ">OnTimeUp";
      this.event("TimeUpEvent");
    }
    OnUpdate(deltaTime) {
      if (!this.paused && !this._timeUp) {
        this._timer -= deltaTime * 1e-3;
        if (this._timer <= 0) {
          this.OnTimeUp();
        }
      }
    }
    AddTimeUpEvent(caller, listener) {
      this.on("TimeUpEvent", caller, listener);
    }
  };

