  // src/script/module/poolGame/component/targetBall/TargetBallGame.ts
  var TargetBallGame = class extends BaseTargetBallGame {
    constructor() {
      super(...arguments);
      /**
       * 启用后可以击打任意球 默认 = false
       */
      this.freeBallMode = false;
      /**
       * 启用后每回合只能操作1次 默认 = false
       */
      this.forceChangeTurn = false;
      //目标球map（key：玩家方位id）
      this._targetBalls = /* @__PURE__ */ new Map();
      this._sunkTargetBall = false;
      this._toRemove = [];
      this._cueCollisionMap = /* @__PURE__ */ new Map();
    }
    get SuitAssigned() {
      return true;
    }
    OnInit() {
      super.OnInit();
      this._breakIdentifier = this.game.GetComponent(FirstShotBreak);
    }
    IsValidBall(ball) {
      if (ball == 0) {
        return false;
      }
      return this.IsValidBallBySeatId(this.game.player.SeatId, ball);
    }
    //通过服务器座位号，获取一方的目标球
    getTargetBallsBySeatId(seatId) {
      let gameRoom = PoolGameManager.ins().gameRoomData;
      let sideId = gameRoom.GetPlayerSideIdBySeat(seatId);
      return this._targetBalls.get(sideId);
    }
    //通过服务器方位号，获取一方的目标球
    getTargetBallsBySideId(sideId) {
      return this._targetBalls.get(sideId);
    }
    /**
     * 设置目标球
     * @param seatId 
     * @param targetBalls 
     * @returns 
     */
    setTargetBallsBySeatId(seatId, targetBalls) {
      let gameRoom = PoolGameManager.ins().gameRoomData;
      let sideId = gameRoom.GetPlayerSideIdBySeat(seatId);
      return this._targetBalls.set(sideId, Array.from(targetBalls));
    }
    IsValidBallBySeatId(seatId, ball) {
      if (this.freeBallMode) {
        return true;
      }
      let array = this.getTargetBallsBySeatId(seatId);
      if (array) {
        return array.indexOf(ball) >= 0;
      }
      return false;
    }
    //根据服务器座位号找出目标球
    TargetBalls(SeatId) {
      let balls = this.getTargetBallsBySeatId(SeatId);
      let temp = [];
      for (let index = 0; index < balls.length; index++) {
        const element = balls[index];
        temp.push(element);
      }
      return temp;
    }
    OnStart() {
      this._targetBalls.clear();
      let playes = this.game.players;
      for (let index = 0, imax = playes.length; index < imax; index++) {
        const element = playes[index];
        if (this._targetBalls.has(element.sideId) == false) {
          this._targetBalls.set(element.sideId, new Array());
        }
      }
    }
    OnReconnect() {
      this._sunkTargetBall = false;
      this._targetBalls.clear();
      this._toRemove = [];
      let playes = this.game.players;
      for (let index = 0, imax = playes.length; index < imax; index++) {
        const element = playes[index];
        if (this._targetBalls.has(element.sideId) == false) {
          this._targetBalls.set(element.sideId, new Array());
        }
      }
    }
    OnCollision(collision) {
      if (collision.other.type == 2 /* Ball */) {
      } else if (collision.other.type == 1 /* Pocket */) {
        if (this.IsValidBall(collision.ball.number)) {
          this._sunkTargetBall = true;
        } else if (this._breakIdentifier.isBreak && collision.ball.number == 8 /* EIGHT */) {
          this._sunkTargetBall = true;
        }
        let callPotNum = CallPotData.ins().callPotNum + 1;
        if ((PoolGameManager.ins().gameRoomData.callPocketAll || PoolGameManager.ins().gameRoomData.callPocketBlack) && (callPotNum > 0 && collision.other.number !== callPotNum)) {
          this._sunkTargetBall = false;
        }
        this._toRemove.push(collision.ball.number);
      }
    }
    OnShotBegin() {
      this._sunkTargetBall = false;
      this._toRemove = [];
      this._cueCollisionMap.clear();
    }
    OnShotAlmostEnd(shotResult) {
      if (this.forceChangeTurn) {
        this.game.ContinueTurnSide();
      } else {
        if (this._sunkTargetBall && shotResult.foul == 0 /* NONE */) {
          let gameRoom = PoolGameManager.ins().gameRoomData;
          if (gameRoom.isTeamGame == false) {
            this.game.ContinueTurn();
            this.game.ContinueTurnSide();
          } else {
            this.game.ContinueTurnSide();
          }
        }
      }
      this._sunkTargetBall = false;
    }
    OnShotEnd(shotResult) {
      for (let v of this._targetBalls.values()) {
        let value = v;
        for (let j = 0; j < this._toRemove.length; j++) {
          let index = value.indexOf(this._toRemove[j]);
          if (index != -1) {
            value.splice(index, 1);
          }
        }
      }
      this._toRemove = [];
    }
    Destroy() {
      super.Destroy();
      this._breakIdentifier = null;
      this._targetBalls.clear();
      this._targetBalls = null;
      this._toRemove = null;
    }
  };

  // src/script/module/poolGame/utils/PoolGamePathUtils.ts
