    ReconnectShotBegin(turnNumber, currSeatId) {
      this.turnNumber = turnNumber;
      for (let index = 0; index < this._players.length; index++) {
        const element = this._players[index];
        if (element.SeatId == currSeatId) {
          this._player = element;
          break;
        }
      }
      this._shotResult = new ShotResult(this._player.SeatId, turnNumber, false);
      this._physicShotResult = new ShotResult(this._player.SeatId, turnNumber, true);
      if (this.players.length > 1) {
        this._shotResult.turnChange = true;
        this._physicShotResult.turnChange = true;
      }
      this.power = 0;
      this.spin = new Vector2(0, 0);
      this._shotState = 0 /* AIMING */;
      let isGameOver = this._shotResult.gameOver;
      if (!isGameOver) {
        this._shotResult.shotStatus += ">OnShotBegin";
        for (let j = 0; j < this._components.length; j++) {
          this._components[j].OnShotBegin();
        }
      }
      console.warn("重连 回合 z " + this._activeBall.position.z);
      console.warn("重连 回合" + this.turnNumber + " seat " + this._player.SeatId + " " + this._player.nick);
    }
