  // src/script/module/rule/utils/RuleTextUtils.ts
  var RuleTextUtils = class {
    /**
     * 将规则说明中的图片路径转换为UI图片路径
     * @param text 原始规则说明文本
     * @returns 转换后的文本
     */
    static convertImagePaths(text) {
      if (!text) {
        return "";
      }
      let convertedText = text;
      convertedText = convertedText.replace(/\/n/g, "\n");
      const imgRegex = /<img[^>]*src=["']([^"']+)["'][^>]*>/gi;
      convertedText = convertedText.replace(imgRegex, (match, src) => {
        const cleanSrc = this.processImageSrc(src);
        const uiImagePath = UIUtils.getImageUrl("rule", cleanSrc);
        return `<img src="${uiImagePath}"align="left">`;
      });
      return convertedText;
    }
    /**
     * 处理图片路径，提取纯文件名
     * @param src 原始图片路径
     * @returns 处理后的文件名（不含扩展名）
     */
    static processImageSrc(src) {
      let cleanSrc = src;
      if (cleanSrc.endsWith(".png")) {
        cleanSrc = cleanSrc.slice(0, -4);
      }
      if (cleanSrc.includes("ui/image/rule/")) {
        cleanSrc = cleanSrc.split("ui/image/rule/")[1];
      }
      if (cleanSrc.includes("ui/image/")) {
        cleanSrc = cleanSrc.split("ui/image/")[1];
      }
      if (cleanSrc.includes("rule/")) {
        cleanSrc = cleanSrc.split("rule/")[1];
      }
      cleanSrc = cleanSrc.replace(/\s+/g, "_");
      return cleanSrc;
    }
  };

