    Init() {
      this.game.Init(this);
      this.game.cameraCom.OnStart();
      this._timer = this._game.GetComponent(ShotTimer);
      UIManager.ins().openFormWithCallback(UIPoolGameView, (poolGameView) => {
        this._gameView = poolGameView;
        this._gameView.SetAdapterNodes(!PoolConst.IsHorizontal);
        UIManager.ins().openFormWithCallback(this.guiClass, (subView) => {
          this._subView = subView;
          subView.view.mouseThrough = true;
          this._gameView.setSubView(this._subView);
          if (!PoolConst.IsHorizontal) {
            this._gameView.playElementAnim(false);
          }
          this._subView.onInit();
          this._view.Init(this, this._gameView);
          this.OnGameInitialized();
        }, this, poolGameView);
      }, this);
    }
    //检查是否可以拖动拉杆(八球定袋玩法里要先定袋才可拖动的)
    CheckCanDragCuePower() {
      return true;
    }
    /**
     * @description: 0场景加载资源初始化完毕
     * @return {*}
     */
    OnGameInitialized() {
      this.initTable(this.game.table);
      if (this.game.table.inited) {
        this.view.InitVisualBalls();
      }
      let players = this._game.players;
      console.log("  OnGameInitialized  players  ", players);
      for (let index = 0; index < players.length; index++) {
        const element = players[index];
        this._view.SetCue(element.CueId, element.SeatId);
      }
    }
    /**
     * @description: 1播放手推球动画
     * @return {*}
     */
    PlaySetBallAnim() {
      if (this._gameRoom.rackerAnim) {
        console.log("PlaySetBallAnim");
        this.game.PlaySetBallAnim(Laya.Handler.create(this, this.OnReady), Laya.Handler.create(this, this.UpdateBallPos, null, false));
        this._view.OnPlaySetBallAnim();
      } else {
        this.UpdateBallPos();
        this.OnReady();
      }
      this.game.table.physics._testHandler = Laya.Handler.create(this, this.UpdateBallPos);
    }
    /**
     * @description: 刷新表现球位置
     * @return {*}
     */
    UpdateBallPos() {
      let balls = this._game.table.Balls;
      for (let index = 0; index < balls.length; index++) {
        const element = balls[index];
        this.view.UpdateBall(element.id, element.position, element.rotation);
      }
    }
    ResetAllBallPos() {
      let balls = this._game.table.Balls;
      for (let index = 0; index < balls.length; index++) {
        const element = balls[index];
        if (element.active) {
          this.view.UpdateBall(element.id, element.position, element.rotation);
        } else {
          this.view.SetBallSunk(element.id);
        }
      }
    }
    /**球准备完毕 开始对局 */
    OnReady() {
      if (this._destroyed) {
        SFLog.error("对局已经销毁");
        return;
      }
      if (this.IsMyTurn() && !this.gameRoom.recoveredGame) {
        SetUpData.ins().isShakable && GamePlatform.vibrateLong();
      }
      this.game.Start(this._gameRoom.startSeatId);
      this.view.OnReadyToPlay();
    }
