    /**
     * 拉杆开始  点击力度
     */
    OnPowerDragStart() {
      this._startPowerTime = Laya.timer.currTimer;
    }
    /**
     * 拉杆结束
     */
    OnPowerRelease() {
      if (this.IsMyTurn() && this.game.shotState == 0 /* AIMING */ && this.game.power > 0) {
        let time = this._timer ? this._timer.timeRemaining : 0;
        this._game.Shoot(null, time);
      }
    }
    /**
     * 拉杆过程更新力度
     * @param power 力度 
     */
    OnPowerUpdate(power) {
      if (this.IsMyTurn() && this.game.shotState == 0 /* AIMING */) {
        this._game.power = power;
      }
    }
    OnDrag(coord) {
      if (this.IsMyTurn()) {
        if (this._draggingBall) {
          if (!Game.instance.cameraCom.is3Dview) {
            this._pos_move = PoolGameUtils.TwoD2ThreeD(coord.x, coord.y);
          } else {
            Laya.Vector2.TEMP.setValue(coord.x, coord.y);
            let ray = new Laya.Ray(Laya.Vector3.ZERO.clone(), Laya.Vector3.ForwardLH.clone());
            this.game.table.camera.viewportPointToRay(Laya.Vector2.TEMP, ray);
            let hitInfo = PoolGameUtils.rayIntersectsBound(ray, PoolGameUtils.tableObjPanel.getComponent(Laya.MeshFilter).sharedMesh.bounds, PoolGameUtils.tableObjPanel.transform.worldMatrix);
            if (hitInfo.hit) {
              this._pos_move = hitInfo.point;
            }
          }
          this._pos_move.y = this.game.table.CueInitPos.y;
          if (this._ballhandComponent.CanMoveBall(this._currentBallInHand, this._pos_move, this._ballhandComponent.canMoveAnyBall)) {
            if (this._ballhandComponent.canMoveAnyBall) {
              const pocket = this.game.table.IsInPocketArea(this._pos_move);
              if (this._curDragPocket != pocket) {
                this._curDragPocket = pocket;
                this.onDragPocketChange(pocket);
              }
            }
            this._ballhandComponent.MoveBall(this._currentBallInHand, this._pos_move);
            this.view.ShowBallInHand(this._currentBallInHand, true);
          } else {
            this.view.ShowDisableMove();
          }
        } else {
        }
      } else {
        let p = coord;
        if (this._ballhandComponent.CanMoveBall(this._currentBallInHand, p)) {
          this._ballhandComponent.MoveBall(this._currentBallInHand, p);
          this.view.ShowBallInHand(this._currentBallInHand, false);
        } else {
          this.view.ShowDisableMove();
        }
      }
    }
    OnDragStart(startPosition, ballId) {
      if (this._game.started) {
        if (this.IsMyTurn()) {
          if (ballId != null && this.IsCanDragBall(ballId) && (this.game.shotState == 0 /* AIMING */ || this.game.shotState == 2 /* CALLING_POCKE */)) {
            this._draggingBall = true;
            this._curDragPocket = null;
            this.ShowCue(false);
            if (!this.view.showBreakArea) {
              this.view.showBreakArea = this._breakComponent.isBreak;
            }
            this._currentBallInHand = ballId;
            this._game.StartDrag();
          }
        } else {
          this._draggingBall = true;
          this._currentBallInHand = ballId;
          this.ShowCue(false);
          this._game.StartDrag();
          if (!this.view.showBreakArea) {
            this.view.showBreakArea = this._breakComponent.isBreak;
          }
        }
      }
    }
    OnDragEnd() {
      if (this._draggingBall) {
        this._draggingBall = false;
        this._curDragPocket = null;
        this.onDragPocketChange(null);
        let ball = this.game.table.Balls[this._currentBallInHand];
        if (ball) {
          let removeBall = false;
          if (ball.id != 0 /* CUE */ && this._ballhandComponent.canMoveAnyBall && this.game.table.IsInPocketArea(ball.position)) {
            removeBall = true;
          }
          let pos = this.game.table.GetValidMovePosition(ball.position);
          this._ballhandComponent.MoveBall(this._currentBallInHand, pos);
          if (!this._ballhandComponent.canMoveAnyBall) {
            this.view.ShowBallInHand(this._currentBallInHand, true, pos);
          } else {
            this.view.HideBallInHandView();
          }
          this.view.OnDragEnd(this._currentBallInHand);
          if (removeBall) {
            ball.active = false;
            ball.pocketId = 5 /* BOTTOM_CENTER */;
            this.game.AddPottedBalls(ball);
            this.view.SetBallSunk(ball.id);
            if (this.game.GetPottedBalls().length >= this.game.table.Balls.length - 1) {
              this.game.EndGame();
              return;
            }
          }
        }
        this.CleanUpDraggingBall();
        this._game.DragEnd();
      }
      if (this.game.shotState == 0 /* AIMING */) {
        this.ShowCue(true);
      }
    }
    OnSelectTargetBall(ballid) {
      this.game.OnSelecttBall(ballid);
    }
    CleanUpDraggingBall() {
      this.view.showBreakArea = false;
      this._ballhandComponent.movedBall = true;
      this._currentBallInHand = 0 /* CUE */;
    }
    //是否是我在击球
    IsMyTurn() {
      return PoolGameUtils.isWatch ? false : this._game.IsCurrentPlayer(this._localPlayerId);
    }
    IsRoomOwner() {
      return PoolGameUtils.isWatch ? false : this.gameRoom.Host.Id == this._localPlayerId;
    }
    IsGameOver() {
      return this.game.isGameOver;
    }
    Update(deltaTime) {
      if (this._game.started && !this._game.paused) {
        this.UpdateView(deltaTime);
        this._game.Update(deltaTime);
        this._game.ExecEvents();
        this._game.table.onUpdate(deltaTime);
      }
    }
    UpdateView(deltaTime) {
      if (!this.game.isGameOver) {
        if (this._timer) {
          this.view.UpdateViewTimer(this.game.player.SeatId, this._timer, this.IsMyTurn());
        }
        if (this._view.isShowCue && this.game.shotState == 0 /* AIMING */) {
          this._view.UpdateCuePos();
          this.UpdateGuide(false);
        }
      }
    }
    onShapeCast(collision) {
      if (collision) {
        let cueBall = this._game.GetActiveBall();
        let p = cueBall.position;
        this._view.UpdateAndDrawGuide(this.game.aim, p, collision);
      }
    }
    laterCallShapeCast() {
      if (this._destroyed) {
        return;
      }
      let cueBall = this._game.GetActiveBall();
      let aim = this.game.aim;
      this.game.table.physics.ShapeCast(cueBall.id, aim);
    }
    UpdateGuide(forceUpdate) {
      var _a;
      let p = (_a = this._game.GetActiveBall()) == null ? void 0 : _a.position;
      if (!p) {
        return;
      }
      let aim = this.game.aim;
      if (forceUpdate || this._view.isShowCue && (Math.abs(this._lastFrameAim.x - aim.x) > 1e-3 || Math.abs(this._lastFrameAim.z - aim.z) > 1e-3 || Math.abs(this._lastFrameBallPosition.x - p.x) > 1e-3 || Math.abs(this._lastFrameBallPosition.z - p.z) > 1e-3)) {
        this.laterCallShapeCast();
        this._lastFrameAim.x = aim.x;
        this._lastFrameAim.y = aim.y;
        this._lastFrameAim.z = aim.z;
        this._lastFrameBallPosition.x = p.x;
        this._lastFrameBallPosition.z = p.z;
      }
      if (this._view.isShowCue) {
        this._view.UpdateArrow();
      }
    }
    ResetGame() {
      this.game.Reset();
      this._view.Reset();
      this._draggingBall = false;
      this._currentBallInHand = 0 /* CUE */;
      this._lastFrameAim = new Laya.Vector3(0, 0, 0);
      this._lastFrameBallPosition = new Laya.Vector3(0, 0, 0);
    }
