    /**
     * @description: 开始击球 处理显示
     * @param {Shot} shot
     * @return {*}
     */
    OnShotTaken(shot) {
      if (this._offlineShotStatus) {
        this._offlineShotStatus.available = true;
        this._offlineShotStatus.balls = [];
        for (let i = 0; i < this.game.table.Balls.length; i++) {
          let ball = this.game.table.Balls[i];
          let state = {
            ballId: ball.id,
            positon: ball.position.clone(),
            active: ball.active,
            pocketId: ball.pocketId
          };
          this._offlineShotStatus.balls.push(state);
        }
        this.onSaveOfflineShot(this._offlineShotStatus);
      }
      this._view.OnShot(shot);
    }
    _backOfflineShot(curShot) {
      const balls = this.game.GetBalls();
      for (let i = 0; i < balls.length; i++) {
        let ball = balls[i];
        ball.Reset();
        ball.SetPosition(curShot.balls[i].positon, true);
        ball.rotation = BallInfo.ballNormalRot;
        ball.active = curShot.balls[i].active;
        ball.pocketId = curShot.balls[i].pocketId;
        if (ball.pocketId > 0) {
          this.game.AddPottedBalls(ball);
        } else {
          this.game.RemovePottedBalls(ball.id);
        }
        if (ball.active) {
          this.view.ResetBall(ball.id, true);
          this.view.UpdateBall(ball.id, ball.position, ball.rotation);
        } else {
          this.view.ResetBall(ball.id, false);
        }
      }
      curShot.available = false;
      this.ShowCue(true);
      this.onBackOfflineShot(curShot);
    }
    /**
     * 离线模式回退一杆数据
     */
    BackOfflineShot() {
      if (!this.isSupportBackOfflineShot) {
        return;
      }
      this.game.ResetComponents();
      const curShot = this._offlineShotStatus;
      this._backOfflineShot(curShot);
      this.AnimateNextTurn();
      this.game.ShowTurn(this.game.turnNumber - 1, this.game.localPlayer.SeatId);
    }
    RestartByOfflineShot() {
      if (!this._firstOfflineShotStatus) {
        return;
      }
      this.game.ResetComponents();
      const curShot = this._firstOfflineShotStatus;
      this._backOfflineShot(curShot);
      this.AnimateNextTurn();
      this.game.ShowTurn(1, this.game.localPlayer.SeatId);
    }
