    onUseCueEvent(cueId) {
      let players = this._game.players;
      for (let index = 0; index < players.length; index++) {
        const element = players[index];
        if (element.Id == this._localPlayerId) {
          element.CueId = cueId;
          this._view.SetCue(cueId, element.SeatId);
          if (this.game.player.SeatId === element.SeatId && this.game.shotState != 1 /* IN_PROGRESS */) {
            this._view.ShowCue(true);
          }
        }
      }
    }
    _g_change_cue_syn_s2c(toc) {
      let players = this._game.players;
      for (let index = 0; index < players.length; index++) {
        const element = players[index];
        if (element.Id == toc.userid) {
          element.CueId = toc.cueid;
          this._view.SetCue(toc.cueid, element.SeatId);
          if (this.game.player.SeatId === element.SeatId) {
            this._view.ShowCue(true);
          }
        }
      }
    }
    // private onUseItemEvent(toc: cmd.player_set_using_item_toc): void {
    //     this.onOtherUserItem(this._localPlayerId, toc.id, toc.type);
