    onOtherUserItem(playerid, id, type) {
    }
    //同步球
    SynBallsPos(lastFrame) {
      let balls = this.game.table.Balls;
      for (let index = 0; index < lastFrame.balls.length; index++) {
        const local = balls[index];
        const element = lastFrame.balls[index];
        if (!element.id) {
          element.id = 0 /* CUE */;
        }
        if (element.pocketId && element.pocketId != 0 /* None */) {
          local.active = false;
          local.pocketId = element.pocketId;
          this.game.AddPottedBalls(local);
          this.view.SetBallSunk(element.id);
        } else {
          if (!this.useCustomBallStatus()) {
            local.Reset();
            const isActive = true;
            local.active = isActive;
            var p = local.position;
            PoolGameUtils.GetPos(element, PoolConst.BallPosY, p);
            local.SetPosition(p, isActive);
            this.game.RemovePottedBalls(element.id);
            this.view.ResetBall(element.id, isActive);
            this.view.SetPositionByFrame(element.id, element, isActive);
          }
        }
      }
      if (this.useCustomBallStatus()) {
        this.onSynBallsPos();
      }
    }
    /**
     * 默认情况下，会使用frame数据同步球状态，但是部分球会变动的玩法需要实现一次主动同步确保球的状态正确
     */
    onSynBallsPos() {
    }
