  // src/script/module/poolGame/component/ai/AIPlayer.ts
  var AIPlayer = class extends GameComponent {
    constructor(seatId, table, physics, timer, shotAssit, gameView, recoder) {
      super();
      /**白球自由球移动动画位置 */
      this._tweenPos = new Laya.Vector3(0, 0, 0);
      /**瞄准的目标点 */
      this._fromAim = new Laya.Vector3(0, 0, 0);
      this._toAim = new Laya.Vector3(0, 0, 0);
      /**自由球后要击打的球 */
      this._freeToHitBallId = 0 /* CUE */;
      this._tempVec3 = new Laya.Vector3(0, 0, 0);
      this.enableFreeWhiteBall = true;
      this.OnDragStartEvent = "OnDragStartEvent";
      this.OnDragEvent = "DragEvent";
      this.OnDragEndEvent = "DragEndEvent";
      this._recoder = recoder;
      this._seatId = seatId;
      this._table = table;
      this._physics = physics;
      this._timer = timer;
      this._shotAssit = shotAssit;
      this._gameView = gameView;
    }
    set ballhand(v) {
      this._ballhand = v;
    }
    get _cueController() {
      if (!this.__cueController) {
        this.__cueController = this._gameView.CueController;
      }
      return this.__cueController;
    }
    AddDragStartEvent(caller, func) {
      this.on(this.OnDragStartEvent, caller, func);
    }
    AddDragEvent(caller, func) {
      this.on(this.OnDragEvent, caller, func);
    }
    AddDragEndEvent(caller, func) {
      this.on(this.OnDragEndEvent, caller, func);
    }
    /**
     * 初始化ai
     * @param breakComponent 
     * @param suitedGame 
     */
    init(breakComponent, suitedGame) {
      this._breakComponent = breakComponent;
      this._suitedGame = suitedGame;
    }
    OnShotBegin() {
      if (PoolGameUtils.isWatch) {
        return;
      }
      if (this.game.player.SeatId == this._seatId) {
        if (!this.game.reconnectPlayFrame) {
          if (!this._cueController) {
            SFLog.error("ai击球 获取 cuecontroller 异常");
            return;
          }
          this._takeTurn();
        }
      } else {
        Laya.timer.clearAll(this);
      }
    }
    _takeTurn() {
      if (this._breakComponent.isBreak) {
        let dir = new Laya.Vector3(-1, 0, 0);
        const collisionMask = this._physics.shapCastCollisionGroup;
        let cuePos = this.game.GetActiveBall().position;
        this._physics.RayCast(cuePos, dir, Laya.Handler.create(this, this._onRayCast), Laya.Physics3DUtils.COLLISIONFILTERGROUP_DEFAULTFILTER, collisionMask);
      } else if (this._ballhand.ballInHand && this.enableFreeWhiteBall) {
        this._freeToHitBallId = 0 /* CUE */;
        let balls = [];
        for (let i = 1; i < this._table.Balls.length; i++) {
          let ball = this._table.Balls[i];
          if (ball.active && this._shotAssit.IsTargetBall(this._seatId, ball)) {
            balls.push(ball.id);
          }
        }
        this._physics.FindBestShotPosition(balls, Laya.Handler.create(this, this._autoMoveWhiteBall));
      } else {
        Laya.timer.loop(100, this, this._checkCameraStop);
      }
    }
    _checkCameraStop() {
      if (Game.instance.cameraCom.is3Dview && Game.instance.cameraCom.isTransitioning) {
        return;
      }
      Laya.timer.clear(this, this._checkCameraStop);
      this._shotAssit.DoGetDirectHitBall(this._seatId, Laya.Handler.create(this, this._onGetDirectHitBallFrom));
    }
    _onRayCast(ret) {
      if (!ret || !ret.cast) {
        return;
      }
      Laya.Vector3.TEMP.setValue(ret.point.x, ret.point.y, ret.point.z);
      this.game.cameraCom.AimTo(Laya.Vector3.TEMP, true, false);
      this._recoder.AddAimAction(Laya.Vector3.TEMP, this._timer.timeRemaining);
      Laya.timer.once(2e3, this, this._doShot);
    }
    _onGetDirectHitBallFrom(pos) {
      this._fromAim.setValue(pos.x, pos.y, pos.z);
      this.game.cameraCom.AimTo(this._fromAim, true, false);
      this._shotAssit.CheckCanPot(true, null, Laya.Handler.create(this, this._onGetDirectHitBall));
    }
    _onGetDirectHitBall(pos) {
      this._toAim.setValue(pos.x, pos.y, pos.z);
      Laya.timer.once(1e3, this, () => {
        Laya.timer.frameLoop(1, this, this._aiAutoAdjustCue);
      });
    }
    _aiAutoAdjustCue() {
      let aim = new Laya.Vector3(0, 0, 0);
      Laya.Vector3.lerp(this._fromAim, this._toAim, Laya.timer.delta * 1e-3, aim);
      this._fromAim = aim;
      let dir = new Laya.Vector3(0, 0, 0);
      let ball = this.game.GetActiveBall();
      Laya.Vector3.subtract(aim, ball.position, dir);
      Laya.Vector3.normalize(dir, dir);
      const collisionMask = this._physics.shapCastCollisionGroup;
      let cuePos = this.game.GetActiveBall().position;
      this._physics.RayCast(cuePos, dir, Laya.Handler.create(this, this._onRayCast2), Laya.Physics3DUtils.COLLISIONFILTERGROUP_DEFAULTFILTER, collisionMask);
    }
    _onRayCast2(ret) {
      if (!ret || !ret.cast) {
        return;
      }
      this.game.cameraCom.AimTo(ret.point, true, false);
      this._recoder.AddAimAction(ret.point, this._timer.timeRemaining);
      if (Math.abs(this._toAim.x - this._fromAim.x) < 0.05 && Math.abs(this._toAim.z - this._fromAim.z) < 0.05) {
        Laya.timer.clear(this, this._aiAutoAdjustCue);
        Laya.timer.once(Math.random() * 1500, this, () => {
          this.game.cameraCom.AimTo(this._toAim, true, false);
          this._doShot();
        });
      }
    }
    _getOffsetPos(value) {
      return PoolConst.AddOffsetXZ + (value - PoolConst.AddOffsetXZ) / 2;
    }
    _autoMoveWhiteBall(data) {
      let pos = data.pos;
      let ballId = data.ballId;
      this._tempVec3.setValue(pos.x, pos.y, pos.z);
      this._freeToHitBallId = ballId;
      let desPos = MathUtil.getTempVector3();
      desPos.setValue(pos.x, pos.y, pos.z);
      const whiteBall = this.game.GetActiveBall();
      const desPos1 = desPos.clone();
      desPos1.x = this._getOffsetPos(desPos1.x);
      whiteBall.position.cloneTo(this._tweenPos);
      let currPos = this._tweenPos;
      let delay = 2e3;
      Laya.timer.once(delay, this, () => {
        this.event(this.OnDragStartEvent, [whiteBall.position, whiteBall.id]);
        Laya.Tween.create(this._tweenPos).to("x", desPos1.x).to("z", desPos1.z).duration(500).ease(Laya.Ease.linearIn).onUpdate(() => {
          this.event(this.OnDragEvent, [this._tweenPos]);
        }).then(() => {
          this._sendWhitePos(this._tweenPos, 1);
          console.log("移动结束1");
          const desPos2 = this._tweenPos.clone();
          if (Math.random() < 0.5) {
            desPos2.z = this._getOffsetPos(desPos2.z);
            var canMove = this._table.CanMoveBall(0 /* CUE */, desPos2);
            if (!canMove) {
              this._showCue();
              Laya.timer.once(500, this, this._moveWhiteBallPos3, [this._tweenPos, desPos]);
            } else {
              Laya.Tween.create(this._tweenPos).to("x", desPos2.x).to("z", desPos2.z).duration(500).ease(Laya.Ease.linearOut).onUpdate(() => {
                this.event(this.OnDragEvent, [this._tweenPos]);
              }).then(() => {
                this._moveWhiteBallPos3(this._tweenPos, desPos);
              });
            }
          } else {
            this._showCue();
            Laya.timer.once(500, this, this._moveWhiteBallPos3, [desPos2, desPos]);
          }
        });
      });
    }
    _moveWhiteBallPos3(pos, desPos) {
      this._sendWhitePos(pos, 1);
      const desPos3 = pos.clone();
      if (Math.random() < 0.5) {
        desPos3.x = this._getOffsetPos(desPos3.x);
        var canMove = this._table.CanMoveBall(0 /* CUE */, desPos3);
        if (!canMove) {
          this._showCue();
          Laya.timer.once(1e3, this, this._moveWhiteBallPos4, [pos, desPos]);
        } else {
          this.event(this.OnDragStartEvent, [pos, 0 /* CUE */]);
          Laya.Tween.create(pos).to("x", desPos3.x).to("z", desPos3.z).duration(500).ease(Laya.Ease.linearOut).onUpdate(() => {
            this.event(this.OnDragEvent, [pos]);
          }).then(() => {
            this._moveWhiteBallPos4(pos, desPos);
          });
        }
      } else {
        this._showCue();
        Laya.timer.once(1e3, this, this._moveWhiteBallPos4, [desPos3, desPos]);
      }
    }
    _moveWhiteBallPos4(pos, desPos) {
      this._sendWhitePos(pos, 1);
      const desPos4 = pos.clone();
      if (Math.random() < 0.5) {
        desPos4.z = this._getOffsetPos(desPos4.z);
        var collides = this._table.CanMoveBall(0 /* CUE */, desPos4);
        if (collides) {
          this._showCue();
          Laya.timer.once(1e3, this, this._moveWhiteBallEnd, [pos, desPos]);
        } else {
          this.event(this.OnDragStartEvent, [pos, 0 /* CUE */]);
          Laya.Tween.create(pos).to("x", desPos4.x).to("z", desPos4.z).duration(400).ease(Laya.Ease.linearOut).onUpdate(() => {
            this.event(this.OnDragEvent, [pos]);
          }).then(() => {
            this._moveWhiteBallEnd(pos, desPos);
          });
        }
      } else {
        this._showCue();
        Laya.timer.once(1e3, this, this._moveWhiteBallEnd, [pos, desPos]);
      }
    }
    _moveWhiteBallEnd(pos, desPos) {
      this.event(this.OnDragStartEvent, [pos, 0 /* CUE */]);
      Laya.Tween.create(pos).to("x", desPos.x).to("z", desPos.z).duration(400).ease(Laya.Ease.linearOut).onUpdate(() => {
        this.event(this.OnDragEvent, [pos]);
      }).then(() => {
        this._moveWhiteBallComplate(desPos);
      });
    }
    _moveWhiteBallComplate(desPos) {
      this._sendWhitePos(desPos, 0);
      SFLog.log("AI 移动结束", desPos);
      this._showCue();
      this._shotAssit.CheckCanPot(false, this._freeToHitBallId != 0 /* CUE */ ? this._freeToHitBallId : null, Laya.Handler.create(this, this._onGetDirectHitBall), true);
    }
    _showCue() {
      this.event(this.OnDragEndEvent);
    }
    _sendWhitePos(pos, type) {
      PoolGameProtoUtils.g_white_pos_syn_c2s(pos, type);
    }
    _doShot() {
      if (!this.game)
        return;
      let player = this.game.GetPlayerBySeat(this._seatId);
      let max = PoolGameExtraDataUtils.getCueMaxForce(player.CueId);
      let force = 0;
      if (this._breakComponent.isBreak) {
        force = max;
      } else {
        force = (0.6 + Math.random() * 0.2) * max;
      }
      let time = 0;
      let totalTime = Math.random() * 800 + 500;
      this._table.GetBallById(0 /* CUE */).active = true;
      Laya.timer.frameLoop(1, this, () => {
        time += Laya.timer.delta;
        let f = Math.round(time / totalTime * force);
        if (f >= force) {
          this.game.power = force;
          Laya.timer.clearAll(this);
          this.game.Shoot(null, this._timer.timeRemaining);
        } else {
          this.game.power = f;
        }
      });
    }
    OnShotEnd(shotResult) {
      Laya.timer.clearAll(this);
      let tweens = Laya.Tween.getTweens(this._tweenPos);
      tweens.forEach((tween) => tween.kill());
    }
    OnReset() {
      Laya.timer.clearAll(this);
      let tweens = Laya.Tween.getTweens(this._tweenPos);
      tweens.forEach((tween) => tween.kill());
    }
    Destroy() {
      super.Destroy();
      Laya.timer.clearAll(this);
      let tweens = Laya.Tween.getTweens(this._tweenPos);
      tweens.forEach((tween) => tween.kill());
      this._table = null;
      this._physics = null;
      this._breakComponent = null;
      this._ballhand = null;
      this._timer = null;
      this._suitedGame = null;
      this._shotAssit = null;
      this._fromAim = null;
      this._toAim = null;
    }
  };

