  // src/script/module/poolGameAdv/data/PoolGameAdvData.ts
  var PoolGameAdvData = class extends BaseDataClass {
    /**
     * 退出玩法后，清理数据
     */
    reset() {
      this.advResultInfo = null;
    }
    /**
     * 获取教学章节配置
     * @returns 
     */
    getTeachSection(id) {
      return ConfigUtil.Tables.teach_section.get(id);
    }
    /**
     * 获取教学章节配置
     * @returns 
     */
    getTeachSections() {
      return ConfigUtil.Tables.teach_section.getDataList();
    }
    /**
     * 获取教学点配置
     * @param id id
     * @returns 
     */
    getTeachPointCfg(id) {
      return ConfigUtil.Tables.teach_point.get(id);
    }
    /**
     * 获取教学点等级配置
     * @param id id
     * @returns 
     */
    getTeachLevelCfg(id) {
      return ConfigUtil.Tables.teach_level.get(id);
    }
    /**
     * 获取下一关教学点等级配置
     * @param id id
     * @returns 
     */
    getNextTeachLevelCfg(id) {
      return ConfigUtil.Tables.teach_level.getDataList().find((e) => e.level > id);
    }
    /**
     * 当前完成的章节
     * @returns 
     */
    getSectionPass() {
      return this.getNowTeachProgress().section - 1;
    }
    /**
     * 获取教学进度，level表示可进行（未解锁）
     * @returns 
     */
    getNowTeachProgress() {
      const result = { section: 0, point: 0, level: 0 };
      const sections = this.getTeachSections();
      for (const sectionCfg of sections) {
        result.section = sectionCfg.id;
        for (const pointId of sectionCfg.point_list) {
          result.point = pointId;
          const pointCfg = this.getTeachPointCfg(pointId);
          for (const levelId of pointCfg.level_list) {
            result.level = levelId;
            if (!this.sectionInfo || this.sectionInfo.secid_list.indexOf(levelId) == -1) {
              return result;
            }
          }
        }
      }
      result.section++;
      result.point++;
      result.level++;
      return result;
    }
    /**
     * 获取教学点的完成数量
     * @param id 教学点配置id
     */
    getTeachPointCompleteNum(id) {
      const cfg = this.getTeachPointCfg(id);
      if (!this.sectionInfo) {
        return 0;
      }
      let num = 0;
      for (let levelId of cfg.level_list) {
        if (this.sectionInfo.secid_list.indexOf(levelId) != -1) {
          num++;
        }
      }
      return num;
    }
    /**
     * 章节奖励是否已获取
     * @param section 章节id
     */
    isSectionRewardGot(section) {
      if (!this.sectionInfo) {
        return false;
      }
      return this.sectionInfo.get_list.indexOf(section) > -1;
    }
    /**
     * 获取关卡挑战限次
     * @param level 关卡id
     * @returns 
     */
    getLimitTimes(level2) {
      var _a, _b;
      if (!this.sectionInfo) {
        return 0;
      }
      const cnt = (_b = (_a = this.sectionInfo.tran_cnt.find((e) => e.id == level2)) == null ? void 0 : _a.num) != null ? _b : 0;
      return cnt;
    }
    /**
     * 关卡挑战限次 +1
     * @param level 关卡id
     * @returns 
     */
    addLimitTimes(level2, num) {
      if (!this.sectionInfo) {
        return 0;
      }
      const e = this.sectionInfo.tran_cnt.find((e2) => e2.id == level2);
      if (e) {
        e.num += num;
      } else {
        this.sectionInfo.tran_cnt.push({
          id: level2,
          num
        });
      }
    }
  };

