  // src/script/module/poolGameAdv/PoolGameAdvManager.ts
  var PoolGameAdvManager = class extends BaseClass {
    /**
     * 请求开始高手进阶挑战
     * @param level 关卡等级
     */
    startAdvBattle(level2) {
      if (!PoolGameAdvUtils.checkCanStartTeachLevel(level2)) {
        TipsManager.ins().showMessageTips("学习需要循序渐进，请先完成前面的教学！");
        return;
      }
      const levelCfg = PoolGameAdvData.ins().getTeachLevelCfg(level2);
      if (!levelCfg) {
        TipsManager.ins().showMessageTips("已完成教学！");
        return;
      }
      const cnt = PoolGameAdvData.ins().getLimitTimes(level2);
      if (levelCfg.limit > 0 && cnt >= levelCfg.limit) {
        TipsManager.ins().showMessageBox({
          callback_cancel: () => {
            ShopManager.ins().showNoDiamondTips(levelCfg.fee, () => {
              PoolGameAdvProtoUtils.game_get_master_make_up_exam_c2s(levelCfg.level, 2);
            });
          },
          callback_ok: () => {
            if (PoolGameAdvData.ins().sectionInfo.rest_make_up > 0) {
              let jsoninfo = { "video_id": PoolGameAdvConst.ADV_RESET_AD, "type": 1, "level": levelCfg.level };
              AdManager.ins().showAd({
                ad_id: PoolGameAdvConst.ADV_RESET_AD,
                ext: JSON.stringify(jsoninfo)
              });
            } else {
              TipsManager.ins().showMessageTips("次数不足");
            }
          },
          title_cancel: `${ThingUtils.getThingHtmlIconPath(1 /* DIAMOND */, 48, 48)}${levelCfg.fee}`,
          title_ok: `${UIUtils.getHtmlPath(UIUtils.getImageUrl("media", "ui_qd_sp"))}补充`,
          desc_ok: `今日剩余:${PoolGameAdvData.ins().sectionInfo.rest_make_up}次`,
          content: `每日考试机会已用完，补充考试次数${levelCfg.limit}次吗？`
        });
        return;
      }
      CueTrialManager.ins().openTrialView(7 /* Advance */, false, () => {
        PoolGameAdvProtoUtils.game_master_start_c2s(level2);
      });
    }
    /**
     * 退出对局
     */
    quitBattle() {
      PoolGameAdvData.ins().reset();
      PoolGameRoomData.ins().resetRoom();
      asgard.stage.StageManager.enterStage(GameConst.appName, 2 /* STAGE_LOBBY */);
      GameNavigator.ins().gotoWithClose(102001 /* Advance */);
    }
  };

