      let remainScore = Math.max(0, totalScore);
      const levelList = this.getRankRowsForGradingScore();
      if (levelList.length <= 0) {
        return null;
      }
      for (const config of levelList) {
        if (this.isKingRank(config.rank_id)) {
          return this.createDisplayInfo(config, remainScore, totalScore);
        }
        const levelScore = Math.max(0, config.score);
        if (levelScore <= 0 || remainScore < levelScore) {
          return this.createDisplayInfo(config, remainScore, totalScore);
        }
        remainScore -= levelScore;
      }
      return this.createDisplayInfo(levelList[levelList.length - 1], remainScore, totalScore);
