    /*
    /**
     * 绑定排行榜滚动事件
     */
    bindRankListScroll() {
      const scroller = this.list_rewards.rootNode.scroller;
      if (!scroller.owner) {
        return;
      }
      scroller.owner.off(Laya.UIEvent.Scroll, this, this.onRankListScroll);
      scroller.owner.on(Laya.UIEvent.Scroll, this, this.onRankListScroll);
    }
    /**
     * 滑到底部附近时拉取下一页，与 Data 中分页缓存拼接
     */
    onRankListScroll() {
      const data = SeasonLevelData.ins();
      if (!data.canLoadMoreRankList()) {
        return;
      }
      const root = this.list_rewards.rootNode;
      const sp = root.scroller;
      if (!sp) {
        return;
      }
      const viewH = sp.viewHeight;
      const contentH = sp.contentHeight;
      const computedMaxPosY = Math.max(0, contentH - viewH);
      let nearBottom = false;
      if (typeof sp.isBottomMost === "boolean") {
        nearBottom = !!sp.isBottomMost;
      } else if (sp.posY) {
        nearBottom = sp.posY >= computedMaxPosY - 80;
      }
      if (!nearBottom) {
        return;
      }
      data.beginRankListRequest();
      SeasonLevelProtoUtils.grading_rank_get_tos(data.rankListLoadedPage + 1);
    }
