      freeI.push(0);
      freeI.push(1);
      freeI.push(1);
      freeI.push(2);
      freeI.push(2);
      freeI.push(3);
      freeI.push(3);
      freeI.push(3);
      freeI.push(3);
      freeI.push(4);
      freeI.push(4);
      freeI.push(4);
      freeI.push(4);
      freeI.push(4);
      freeI.push(2);
      let freeJ = [];
      freeJ.push(0);
      freeJ.push(0);
      freeJ.push(1);
      freeJ.push(0);
      freeJ.push(2);
      freeJ.push(0);
      freeJ.push(1);
      freeJ.push(2);
      freeJ.push(3);
      freeJ.push(1);
      freeJ.push(2);
      freeJ.push(3);
