  // src/script/module/poolGame/gameplay/eightBall/component/rules/EightBallGameRules.ts
  var EightBallGameRules = class extends EightBallGameRulesPhysics {
    constructor() {
      super(...arguments);
      this._isPhysic = false;
    }
    /**处理进球类型 */
    _setPottedBallType(foul) {
      EightBallScoreData.ins().copyLastHitData(this.game.player.SeatId);
      let num = 0;
      if (!foul && this.shotResult.pottedBalls.length > 0) {
        let balls = this.shotResult.pottedBalls;
        for (let i = 0; i < balls.length; i++) {
          if (!this.isValidBallOnSettle || this._validator.IsValidBall(balls[i].id)) {
            let type_list = this._getTypeList(balls[i]);
            this.shotResult.type_list.push(...type_list);
            for (let i2 = 0; i2 < type_list.length; i2++) {
              let id = type_list[i2];
              if (this.game.shotResult.turnNumber == 0 && id > 1 && id <= 6) {
                continue;
              }
              NotificationHUD.ins().AddImageTips(type_list[i2]);
            }
            num++;
          }
        }
        if (num >= 4) {
          NotificationHUD.ins().AddImageTips(9 /* EFFECT_9 */);
        } else if (num >= 3) {
          NotificationHUD.ins().AddImageTips(8 /* EFFECT_8 */);
        } else if (num >= 2) {
          NotificationHUD.ins().AddImageTips(7 /* EFFECT_7 */);
        }
      }
    }
    /**处理母球进袋 */
    _setCuePotted() {
      super._setCuePotted();
      NotificationHUD.ins().AddImageTips(28 /* EFFECT_28 */);
    }
  };

