  var ScoreRateTip = class {
    init(rootNode) {
      this.box_scoreRateItems = ElemFinder.getElement(rootNode, "box_scoreRateItems");
      this.img_scoreRateBg = ElemFinder.getElement(rootNode, "img_scoreRateBg");
      const view = UIManager.ins().getForm(UIPoolGameEightView);
      this.box_scoreRateItem = view.box_scoreRateItem;
      this.box_scoreRateItem.visible = false;
    }
    updateUI(seatId) {
      let arr = EightBallScoreData.ins().getPlayerScoreRates(seatId);
      let len = this.box_scoreRateItems.numChildren;
      for (let index = 0; index < len; index++) {
        const element = this.box_scoreRateItems.getChildAt(index);
        element.visible = false;
      }
      for (let index = 0; index < arr.length; index++) {
        const element = arr[index];
        let item2 = null;
        if (index < len) {
          item2 = this.box_scoreRateItems.getChildAt(index);
        } else {
          item2 = UIUtils.instantiateUINode(this.box_scoreRateItem);
          this.box_scoreRateItems.addChild(item2);
        }
        item2.visible = true;
        let txt_scoreRateItemName = ElemFinder.getText(item2, "txt_scoreRateItemName");
        let box_scoreRateItemValue = ElemFinder.getText(item2, "box_scoreRateItemValue");
        if (element.effectId == -1) {
          txt_scoreRateItemName.text = "基础倍率";
          box_scoreRateItemValue.text = "1";
        } else {
          let cfg = ConfigUtil.Tables.pot_feedback.get(element.effectId);
          let nameStr = LangData.ins().getLang(cfg.name_pot);
          if (!element.isLinkShot) {
            nameStr = nameStr + `(${element.num})`;
          }
          txt_scoreRateItemName.text = nameStr;
          let valueStr = "";
          if (element.rate[0] == 1) {
            valueStr = "+" + (element.rate[1] * element.num / 100).toFixed(2);
          }
          box_scoreRateItemValue.text = valueStr;
        }
      }
      this.img_scoreRateBg.height = 60 + arr.length * this.box_scoreRateItem.height;
    }
  };

  // src/script/module/poolGame/gameplay/eightBall/application/Local_EightGameApplication.ts
  var Local_EightGameApplication = class extends PoolApplication {
    getGUIView() {
      return UIPoolGameEightView;
    }
    initGameRules() {
      return new EightBallGameRules();
    }
    initFirstShotBreak() {
      return new FirstShotBreakEight();
    }
    initTargetBallGame() {
      return new EightBallGame();
    }
    initTable(table) {
      let setBallAnim = table.scene.getChildByName("SetBallsAni");
      const racker = new StandardRacker(setBallAnim);
      const balls = [];
      for (let index = 0; index < 16; index++) {
        const ball = new BallInfo(index, table.physics, true);
        ball.active = true;
        balls.push(ball);
      }
      table.init(PoolConst.WhiteBallInitPos, racker, balls);
    }
    OnGameInitialized() {
      super.OnGameInitialized();
      this.gameRoom.rackerAnim = false;
      this.game.table.Rack(0);
      this.PlaySetBallAnim();
    }
    OnShotComplete(shotResult) {
      super.OnShotComplete(shotResult);
      if (!shotResult.turnChangeSide) {
        if (this.suitedGame && this.suitedGame instanceof EightBallGame && this.suitedGame.SuitAssigned) {
          if (shotResult.shotLink > 1) {
            if (shotResult.shotLink <= 7) {
              NotificationHUD.ins().AddImageTips(8 /* EFFECT_8 */ + shotResult.shotLink);
            } else {
              NotificationHUD.ins().AddImageTips(17 /* EFFECT_17 */);
            }
          }
        }
      }
      if (!this.game.isGameOver) {
        if (this.suitedGame && this.suitedGame instanceof EightBallGame && this.suitedGame.SuitAssigned) {
          this.view.AssignSuits(null);
        }
      }
      if (shotResult.foul != 6 /* SCRATCH */) {
        this._ballhandComponent.OverrideBallInHand(true);
        let cue3 = this.game.GetActiveBall();
        this.game.OnActiveBallSink(cue3.id);
      }
      Laya.timer.once(0, this, this.StartTurn, [this.game.shotResult]);
    }
    OnTurnChange() {
      if (this.IsMyTurn()) {
        SetUpData.ins().isShakable && GamePlatform.vibrateLong();
        SoundManager.ins().playSound(SoundID.YOUR_TURN);
      }
    }
    LeaveScene() {
      asgard.stage.StageManager.enterStage(GameConst.appName, 2 /* STAGE_LOBBY */);
    }
    OnGameEnd(winners) {
      TipsManager.ins().showMessageBox({
        content: "你的技术如此精湛！\n赶紧去真人匹配碾压对手吧！",
        title: "提  示",
        title_ok: "结束训练",
        title_cancel: "真人匹配",
        visible_x: false,
        maskInteract: false,
        callback_ok: () => {
          this.LeaveScene();
        },
        callback_cancel: () => {
          this.LeaveScene();
          UIManager.ins().openForm(UIGamePlaySelView, 1 /* EightBall */);
        }
      });
    }
    Restart() {
      TipsManager.ins().showMessageBox({
        content: "是否确定重玩？",
        callback_ok: () => {
          asgard.stage.StageManager.enterStage(GameConst.appName, 4 /* STAGE_POOLGAME */);
        }
      });
    }
  };

  // src/script/module/poolGameRoom/view/result/UIGameResultSmallView.ts
  var UIGameResultSmallView = class extends UIBaseView {
    updateView() {
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/poolGameRoom/result/UIGameResultSmallView.lh";
    }
    onConstruct() {
      this.img_result_success = this.elems.getElement("img_result_success");
      this.img_result_fail = this.elems.getElement("img_result_fail");
    }
    onRegisterEvent() {
    }
    onOpen(data) {
      this.data = data;
      const selfSeatInfo = PoolGameRoomData.ins().selfSeatInfo;
      const otherSeatInfo = PoolGameRoomData.ins().otherSeatInfo;
      const win = data.winnerid == PlayerData.ins().playerId;
      UIUtils.setActive(this.img_result_success, win);
      UIUtils.setActive(this.img_result_fail, !win);
      SoundManager.ins().playSound(win ? SoundID.SFX_WIN : SoundID.SFX_LOSE);
      this.setPlayerUI(this.elems.getElement("player1"), selfSeatInfo, data.win_coin);
      this.setPlayerUI(this.elems.getElement("player2"), otherSeatInfo, -data.win_coin);
      Laya.timer.once(3e3, this, this.close);
    }
    setPlayerUI(node, info, coin) {
      let txt_playerName = ElemFinder.getText(node, "txt_playerName");
      let txt_coin = ElemFinder.getText(node, "txt_coin");
      txt_playerName.text = info.nick;
      let color = "#D61818";
      if (coin < 0) {
        color = "#0BEF28";
      }
      let coinValue = coin;
      let formattedText = "";
      if (coinValue < 0) {
        formattedText = "-" + DataFormatter.formatSpecialNumber(Math.abs(coinValue));
      } else {
        formattedText = "+" + DataFormatter.formatSpecialNumber(coinValue);
      }
      txt_coin.text = formattedText;
      txt_coin.color = color;
    }
    onClose() {
      asgard.stage.StageManager.enterStage(GameConst.appName, 5 /* STAGE_RESULT */);
    }
  };

