    CanMoveBall(ballId, pos, checkPocketVal = false) {
      let temp = Laya.Vector3.TEMP;
      temp.setValue(pos.x, pos.y, pos.z);
      this.GetValidMovePosition(temp, checkPocketVal);
      let canMove = true;
      let distance = Laya.Point.TEMP;
      distance.setTo(temp.x, temp.z);
      let balls = this.Balls;
      let l = this.physics.BallRadius * 2;
      for (let i = 0; i < balls.length; i++) {
        const ball = balls[i];
        if (ball.id != ballId && ball.active && distance.distance(ball.position.x, ball.position.z) < l) {
          canMove = false;
          break;
        }
      }
      return canMove;
    }
    /**
     * 判断一个点是否在袋子里
     * @param pos 
     * @returns 
     */
    IsInPocketArea(pos) {
      for (const pocket of this._pots) {
        if (pocket.type === "corner") {
          if (pocket.edge === "left" && pocket.side === "top") {
            if (pos.x > pocket.position.x - pocket.radius && pos.z > pocket.position.z - pocket.radius) {
              return pocket;
            }
          } else if (pocket.edge === "right" && pocket.side === "top") {
            if (pos.x < pocket.position.x + pocket.radius && pos.z > pocket.position.z - pocket.radius) {
              return pocket;
            }
          } else if (pocket.edge === "left" && pocket.side === "bottom") {
            if (pos.x > pocket.position.x - pocket.radius && pos.z < pocket.position.z + pocket.radius) {
              return pocket;
            }
          } else if (pocket.edge === "right" && pocket.side === "bottom") {
            if (pos.x < pocket.position.x + pocket.radius && pos.z < pocket.position.z + pocket.radius) {
              return pocket;
            }
          }
        }
        if (pocket.type === "middle") {
          const inWidth = Math.abs(pos.x - pocket.position.x) <= pocket.radius;
          if (pocket.side === "top" && (pos.z > pocket.position.z - pocket.radius && inWidth)) {
            return pocket;
          }
          if (pocket.side === "bottom" && (pos.z < pocket.position.z + pocket.radius && inWidth)) {
            return pocket;
          }
        }
      }
      return null;
    }
    /**
     * 限制一个点在袋子里
     * @param pos 限制的点
     * @returns 
     */
    ConstrainToPocket(pos) {
      const pocket = this.IsInPocketArea(pos);
      if (pocket) {
        if (pocket.type === "corner") {
          let constrainedX = pos.x;
          let constrainedZ = pos.z;
          if (pocket.edge === "left" && pos.x > pocket.position.x + pocket.radius) {
            constrainedX = pocket.position.x + pocket.radius;
          } else if (pocket.edge === "right" && pos.x < pocket.position.x - pocket.radius) {
            constrainedX = pocket.position.x - pocket.radius;
          }
          if (pocket.side === "top" && pos.z > pocket.position.z + pocket.radius) {
            constrainedZ = pocket.position.z + pocket.radius;
          } else if (pocket.side === "bottom" && pos.z < pocket.position.z - pocket.radius) {
            constrainedZ = pocket.position.z - pocket.radius;
          }
          if (Math.sqrt(
            Math.pow(constrainedX - pocket.position.x, 2) + Math.pow(constrainedZ - pocket.position.z, 2)
          ) <= pocket.radius - PoolConst.BallRadius) {
            pos.x = constrainedX;
            pos.z = constrainedZ;
            return;
          }
          const angle = Math.atan2(
            constrainedZ - pocket.position.z,
            constrainedX - pocket.position.x
          );
          pos.x = pocket.position.x + Math.cos(angle) * (pocket.radius - PoolConst.BallRadius), pos.z = pocket.position.z + Math.sin(angle) * (pocket.radius - PoolConst.BallRadius);
          return;
        } else {
          pos.x = Math.max(
            pocket.position.x - (pocket.radius - PoolConst.BallRadius),
            Math.min(pocket.position.x + (pocket.radius - PoolConst.BallRadius), pos.x)
          ), pos.z = pocket.side === "top" ? Math.min(pocket.position.z + (pocket.radius - PoolConst.BallRadius), pos.z) : Math.max(pocket.position.z - (pocket.radius - PoolConst.BallRadius), pos.z);
          return;
        }
      }
    }
    GetValidMovePosition(pos, checkPocketVal = false) {
      let isInPoscket = false;
      if (checkPocketVal && this.IsInPocketArea(pos)) {
        isInPoscket = true;
        this.ConstrainToPocket(pos);
      }
      if (!isInPoscket) {
        if (pos.x > PoolConst.tableLeftX - PoolConst.BallRadius) {
          pos.x = PoolConst.tableLeftX - PoolConst.BallRadius;
        } else if (pos.x < PoolConst.tableRightX + PoolConst.BallRadius) {
          pos.x = PoolConst.tableRightX + PoolConst.BallRadius;
        }
        if (pos.z < PoolConst.tableBottomZ + PoolConst.BallRadius) {
          pos.z = PoolConst.tableBottomZ + PoolConst.BallRadius;
        } else if (pos.z > PoolConst.tableTopZ - PoolConst.BallRadius) {
          pos.z = PoolConst.tableTopZ - PoolConst.BallRadius;
        }
      }
      return pos;
    }
