      if (potRadius > 0) {
        PoolConst.potBallDistance = (potRadius + PoolConst.BallRadius) * 1.2;
      }
      this._physicsBalls = [];
      this._updateBalls = [];
      this._shapCastCollisionGroup = Laya.Physics3DUtils.COLLISIONFILTERGROUP_ALLFILTER ^ Laya.Physics3DUtils.COLLISIONFILTERGROUP_CUSTOMFILTER1 ^ Laya.Physics3DUtils.COLLISIONFILTERGROUP_CUSTOMFILTER2;
      this._initWorker(ruleset);
