  // src/script/module/poolGame/gameplay/multiXL/application/MultiXLCirclesCtrl.ts
  var MultiXLCirclesCtrl = class {
    constructor() {
      /**
       * 光圈-暗
       */
      this._circle_dark_Arr = [];
      /**
       * 光圈-暗 文本
       */
      this._circle_dark_text_Arr = [];
      /**
       * 光圈-亮
       */
      this._circle_light_Arr = [];
      /**
       * 光圈-亮 文本
       */
      this._circle_light_text_Arr = [];
    }
    init(game) {
      this.game = game;
      const num = 7;
      for (let i = 0; i < num; i++) {
        const textRenderer = new Sprite3DRenderer(this.game.table.scene);
        const renderer = new Sprite3DRenderer(this.game.table.scene);
        textRenderer.setScale(0.5);
        textRenderer.setRotation(MathUtil.getTempVector3(180, 0, 90));
        renderer.setRotation(MathUtil.getTempVector3(90, 270, 0));
        renderer.setActive(false);
        renderer.load("u3d/Assets/prefab/effect/PVPmatch_bleed_multiple_random.lh", () => {
          const defaultTxt = renderer.model.getChildByName("PVPmatch_bleed_multiple_wh");
          defaultTxt.getComponent(Laya.MeshRenderer).enabled = false;
          textRenderer.setParent(defaultTxt);
        });
        this._circle_dark_Arr[i] = renderer;
        this._circle_dark_text_Arr[i] = textRenderer;
      }
      for (let i = 0; i < num; i++) {
        const textRenderer = new Sprite3DRenderer(this.game.table.scene);
        const renderer = new Sprite3DRenderer(this.game.table.scene);
        textRenderer.setScale(0.5);
        textRenderer.setRotation(MathUtil.getTempVector3(180, 0, 90));
        renderer.setRotation(MathUtil.getTempVector3(90, 270, 0));
        renderer.setActive(false);
        renderer.load("u3d/Assets/prefab/effect/PVPmatch_bleed_multiple.lh", () => {
          textRenderer.setParent(renderer.model);
          const defaultTxt = renderer.model.getChildByName("PVPmatch_bleed_multiple_sz");
          defaultTxt.getComponent(Laya.MeshRenderer).enabled = false;
          textRenderer.setParent(defaultTxt);
        });
        this._circle_light_Arr[i] = renderer;
        this._circle_light_text_Arr[i] = textRenderer;
      }
      this.updateCircleAndRates();
    }
    /**
     * 更新光圈和倍率
     * @param isSetRates 
     */
    updateCircleAndRates() {
      for (let i = 0; i < this._circle_dark_Arr.length; i++) {
        this._circle_dark_Arr[i].setActive(false);
        this._circle_light_Arr[i].setActive(false);
        this._circle_dark_text_Arr[i].load("poolAssets/multiXL/prefab/df_w.lh");
      }
      this.checkRandomRate();
      const bloodInfo = this.game.gameRoomData.gameData.blood;
      for (let i = 0; i < bloodInfo.poker_circle.length; i++) {
        const circleInfo = bloodInfo.poker_circle[i];
        let circle_dark = this._circle_dark_Arr[i];
        let circle_light = this._circle_light_Arr[i];
        if (circle_light) {
          circle_light.setScale(circleInfo.scale);
          circle_light.setPosition(MathUtil.getTempVector3(
            circleInfo.x,
            PoolConst.PanelPosY,
            circleInfo.y - 0.01
          ));
          circle_dark.setScale(circleInfo.scale);
          circle_dark.setPosition(MathUtil.getTempVector3(
            circleInfo.x,
            PoolConst.PanelPosY,
            circleInfo.y - 0.01
          ));
          this.setCircleStatus(i, circleInfo.is_pass, circleInfo.mul, false);
        }
      }
      if (bloodInfo.x_poker_circle.length > 0) {
        this.updateCircleMul(bloodInfo.x_poker_circle);
      }
    }
    /**
     * 更新光圈数组的倍率
     * @param mulArr 
     */
    updateCircleMul(mulArr) {
      const bloodInfo = this.game.gameRoomData.gameData.blood;
      if (bloodInfo.poker_circle && mulArr) {
        for (let index = 0; index < bloodInfo.poker_circle.length; index++) {
          let element = bloodInfo.poker_circle[index];
          if (element.id === index + 1) {
            element.mul = mulArr[index];
            this.setCircleStatus(index, element.is_pass, mulArr[index], true);
          }
        }
      }
    }
    /**
     * 根据牌组更新倍率
     */
    updateCircleByPoker() {
      const bloodInfo = this.game.gameRoomData.gameData.blood;
      let poker_group = bloodInfo.poker_group;
      for (let index = 0; index < poker_group.length; index++) {
        let circle = poker_group[index];
        if (poker_group[index]) {
          this.setCircleMulById(circle.key, circle.value);
        }
      }
    }
    /**
     * 设置光圈倍率
     * @param id id
     * @param mul 倍率
     * @returns 
     */
    setCircleMulById(id, mul) {
      const circles = this.game.gameRoomData.gameData.blood.poker_circle;
      if (circles) {
        for (let index = 0; index < circles.length; index++) {
          const element = circles[index];
          if (element.id == id) {
            this.setCircleStatus(index, true, mul, true);
            break;
          }
        }
      }
    }
    /**
     * 设置光圈亮起状态
     * @param index 
     * @param isLight
     * @param mul 
     * @param isPlaySound 
     * @returns 
     */
    setCircleStatus(index, isLight, mul, isPlaySound) {
      if (this._circle_dark_Arr[index] == null)
        return;
      const circle_dark = this._circle_dark_Arr[index];
      const circle_light = this._circle_light_Arr[index];
      circle_dark.setActive(!isLight);
      circle_light.setActive(isLight);
      mul = mul != null ? mul : 0;
      this._circle_light_text_Arr[index].load(`poolAssets/multiXL/prefab/df_${mul}.lh`);
      if (isLight) {
        if (mul > 0) {
          if (isPlaySound) {
            SoundManager.ins().playSound(SoundID.XL_MULTI);
          }
        }
      }
    }
    /**
     * 根据光圈id将圈激活
     * @param circleId 圈id
     */
    setCircleLightUpById(circleId) {
      const circles = this.game.gameRoomData.gameData.blood.poker_circle;
      if (circles) {
        for (let index = 0; index < circles.length; index++) {
          const element = circles[index];
          if (element.id == circleId) {
            this.setCircleStatus(index, true, element.mul, true);
            break;
          }
        }
      }
    }
    /**
     * 获取圈位置
     * @param circleId 圈id
     * @returns 
     */
    getCirclePos(circleId) {
      const circles = this.game.gameRoomData.gameData.blood.poker_circle;
      if (circles) {
        for (let index = 0; index < circles.length; index++) {
          const element = circles[index];
          if (element.id == circleId) {
            return this._circle_dark_Arr[index].position;
          }
        }
      }
      return Laya.Vector3.ZERO;
    }
    /**
     * 检测是否碰到圈
     * @returns 
     */
    checkRandomRate() {
      let blood = this.game.gameRoomData.gameData.blood;
      let circles = blood.poker_circle;
      if (!circles)
        return;
      let bloodCircleMulIds = this.game.app.gameRules.bloodCircleMulIds;
      for (let k = 0; k < circles.length; k++) {
        let circle = circles[k];
        if (bloodCircleMulIds.indexOf(circle.id) > -1) {
          continue;
        }
        let balls = this.game.GetBalls();
        for (let i = 0; i < balls.length; i++) {
          let ball = balls[i];
          if (!ball.active || ball.pocketId != 0 /* None */)
            continue;
          const visualBall = this.game.app.view.GetVisualBallById(ball.id);
          if (!visualBall) {
            continue;
          }
          let dis = Laya.Vector3.distance(visualBall.position, MathUtil.getTempVector3(circle.x, PoolConst.BallPosY, circle.y));
          if (dis < circle.scale / 2 + PoolConst.BallRadius) {
            circle.is_pass = true;
            if (bloodCircleMulIds.indexOf(circle.id) == -1) {
              bloodCircleMulIds.push(circle.id);
              this.setCircleLightUpById(circle.id);
            }
          }
        }
      }
    }
  };

