        const newPrefab = UIUtils.instantiateUINode(prefab);
        view.effectPlayer.tableRoot.addChild(newPrefab);
        const ctrl = new XLTableHoleCtrl(newPrefab);
        ctrl.setActive(false);
        ctrl.bindPot(i);
        this.holeList.push(ctrl);
