  var _XLTableHoleEffect = class _XLTableHoleEffect {
    constructor(rootNode) {
      this.rootNode = rootNode;
      this.root = ElemFinder.getElement(rootNode, "root");
      this.txt_red = ElemFinder.getElement(rootNode, "root/txt_red");
      this.txt_yellow = ElemFinder.getElement(rootNode, "root/txt_yellow");
      this.img_tech = ElemFinder.getElement(rootNode, "root/img_tech");
      this.model_effect = new Sprite3DRenderer(Game.instance.table.scene);
      this.model_effect.load("u3d/Assets/prefab/effect/PVPmatch_multiple_trail_red.lh");
      this.model_effect.setActive(false);
      this.follower = rootNode.addComponent(Sprite3DFollower);
      this.follower.camera = Game.instance.table.camera;
    }
    /**
     * 获取特效位置 用于tween动画
     */
    get effectPosition() {
      return this.model_effect.position;
    }
    /**
     * 设置特效位置 用于tween动画
     */
    set effectPosition(value) {
      this.model_effect.setPosition(value);
    }
    /**
     * 创建一个洞口特效
     * @returns 
     */
    static create() {
      if (!this._pool) {
        this._pool = new ObjectPool(
          () => {
            const prefab = UIManager.ins().getForm(UIPoolGameMultiXLView).item_tableTextFly;
            return new _XLTableHoleEffect(UIUtils.instantiateUINode(prefab));
          }
        );
      }
      const effect2 = this._pool.getObject();
      this.activeEffects.push(effect2);
      return effect2;
    }
    static destroyPool() {
      if (this._pool) {
        this._pool.clear();
      }
    }
    /**
     * 重置洞口状态
     */
    destroy() {
      const index = _XLTableHoleEffect.activeEffects.indexOf(this);
      if (index == -1) {
        return;
      }
      Laya.Tween.killAll(this);
      Laya.Tween.killAll(this.root);
      this.model_effect.setActive(false);
      this.rootNode.removeSelf();
      _XLTableHoleEffect.activeEffects.splice(index, 1);
      _XLTableHoleEffect._pool.recycleObject(this);
    }
    /**
     * 播放倍率动画
     */
    playEffect(holeCtrl, rate, pos, hasTechBall) {
      const isYellowColor = rate > 0;
      if (isYellowColor) {
        this.txt_yellow.text = rate.toString();
      } else {
        this.txt_red.text = rate.toString();
      }
      UIUtils.setActive(this.img_tech, false);
      UIUtils.setActive(this.txt_red, !isYellowColor);
      UIUtils.setActive(this.txt_yellow, isYellowColor);
      const effectRoot = UIManager.ins().getForm(UIPoolGameMultiXLView).view;
      effectRoot.addChild(this.rootNode);
      UIUtils.setActive(this.rootNode, true);
      if (holeCtrl) {
        this.follower.setTargetPos(holeCtrl.potPos);
      } else {
        this.follower.setTargetPos(pos);
      }
      Laya.Tween.to(this.root, { y: -30 }, 1e3, null, Laya.Handler.create(this, () => {
        if (holeCtrl) {
          holeCtrl.setActive(true);
        }
        UIUtils.setActive(this.rootNode, false);
        const effectPlayer = Game.instance.app.subView.effectPlayer;
        effectPlayer.updateSeatPlayer();
        const pokerArea = effectPlayer.pokerArea;
        const targetPos = PoolGameUtils.TwoD2ThreeD(pokerArea.x, pokerArea.y, pokerArea);
        this.root.pos(0, 0);
        this.trail(pos, targetPos, () => {
          effectPlayer.playCoinRateEffect(rate, 0 /* BallRate */);
          if (hasTechBall) {
            UIUtils.setActive(this.rootNode, true);
            UIUtils.setActive(this.img_tech, true);
            Laya.Tween.to(this.root, { y: -30 }, 1e3, null, Laya.Handler.create(this, () => {
              UIUtils.setActive(this.rootNode, false);
              this.destroy();
            }));
          } else {
            this.destroy();
          }
        });
      }));
    }
    /**拖尾 */
    trail(from, to, callback = null) {
      this.model_effect.setActive(true);
      this.model_effect.setPosition(MathUtil.getTempVector3(from.x, 0.2, from.z));
      this.model_effect.setScale(3);
      SoundManager.ins().playSound(SoundID.XL_RATE_FLY);
      Laya.Tween.to(this, {
        effectPosition: to
      }, 400, null, Laya.Handler.create(this, () => {
        this.model_effect.setActive(false);
        if (callback != null) {
          callback();
        }
      }));
    }
  };
  /**
   * 当前激活的特效列表
   */
  _XLTableHoleEffect.activeEffects = [];
  var XLTableHoleEffect = _XLTableHoleEffect;

