      const all_ball_num = blood.all_ball_num;
      for (let index = 0; index < all_ball_num + 1; index++) {
        const ball = new BallInfo(index, table.physics, false);
        balls.push(ball);
      }
      table.init(PoolConst.WhiteBallInitPos, racker, balls);
      const multi_user_ball_info = blood.multi_user_ball_info;
      for (const ballInfo of multi_user_ball_info) {
        if (ballInfo.ball_id == null)
          ballInfo.ball_id = 0;
        const ball = this._app.game.table.GetBallById(ballInfo.id - 1);
        if (ball) {
          if (ballInfo.ball_id) {
            ball.SetShowId(ballInfo.ball_id);
          }
        }
      }
      this._circlesCtrl.init(this._app.game);
      this._tableCtrl.init(this._app.game);
      this._app.gameRoom.rackerAnim = false;
      this.subView.updatePlayerCoins();
      this.subView.updateLeftBalls();
      this.subView.updateDoubleInfo();
      this.subView.updateStartBrokenInfo();
      this.subView.updatePlayerRates();
      this._app.suitedGame.freeBallMode = true;
      this._app.suitedGame.forceChangeTurn = true;
      this._app.ballhandComponent.ignoreFouls = true;
