  // src/script/module/poolGame/gameplay/nineBall/application/Net_NineGameApplication.ts
  var Net_NineGameApplication = class extends NetPoolApplication {
    /**
     * 对局界面
     */
    get subView() {
      return super.subView;
    }
    getGUIView() {
      return UIPoolGameNineView;
    }
    initGameRulesPhysics() {
      const rule2 = new EightBallGameRulesPhysics();
      rule2.isValidBallOnSettle = false;
      return rule2;
    }
    initFirstShotBreakPhysics() {
      return new FirstShotBreakNinePhysics();
    }
    initGameRules() {
      const rule2 = new EightBallGameRules();
      rule2.isValidBallOnSettle = false;
      return rule2;
    }
    initFirstShotBreak() {
      return new FirstShotBreakNine();
    }
    initTargetBallGame() {
      return new NineBallGame();
    }
    initTable(table) {
      this._otherQuitMsg = `对手已退出,是否打完本杆?`;
      let setBallAnim = table.scene.getChildByName("SetBallsAni");
      const racker = new NineRacker(setBallAnim);
      const balls = [];
      for (let index = 0; index < 10; index++) {
        const ball = new BallInfo(index, table.physics, true);
        balls.push(ball);
      }
      table.init(PoolConst.WhiteBallInitPos, racker, balls);
    }
    onGameStart() {
      super.onGameStart();
      this._suitedGame.targetId = this.game.gameRoomData.gameData.nine.goal_numbers;
      this.view.AssignSuits(null);
    }
    OnShotComplete(shotResult) {
      super.OnShotComplete(shotResult);
      if (!shotResult.turnChangeSide) {
        if (shotResult.shotLink > 1) {
          if (shotResult.shotLink <= 7) {
            NotificationHUD.ins().AddImageTips(8 /* EFFECT_8 */ + shotResult.shotLink);
          } else {
            NotificationHUD.ins().AddImageTips(17 /* EFFECT_17 */);
          }
        }
      }
      if (shotResult.foul == 0 /* NONE */ && this.game.GetPlayer(this.localPlayerId).sideId === this.gameRoom.GetPlayerSideIdBySeat(shotResult.seatId)) {
        let pottedBalls = shotResult.pottedBalls;
        let array = [];
        for (let i = 0; i < pottedBalls.length; i++) {
          let id = pottedBalls[i].id;
          array.push(id);
        }
        if (array.length > 0) {
          if (array.indexOf(9 /* NINE */) == -1) {
            NotificationHUD.ins().showNewMessage(2 /* HITINCON */, [array]);
          }
        } else {
          NotificationHUD.ins().showNewMessage(3 /* TURNOPPO */);
        }
      }
      if (this.game && !this.game.isGameOver) {
        this.view.AssignSuits(null);
      }
    }
    _doChangePlayerTurn(toc) {
      this._suitedGame.targetId = toc.goal_numbers;
      super._doChangePlayerTurn(toc);
      this.view.AssignSuits(null);
    }
    LeaveScene() {
      if (this.checkIsWatchLeaveScene()) {
        return;
      }
      TipsManager.ins().showMessageBox({
        content: "现在退出游戏将罚4倍门票，是否继续退出？",
        callback_ok: () => {
          PoolGameProtoUtils.g_quit_room_req_c2s();
        }
      });
    }
  };

