  var UIGamePveCommonResultView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/poolGamePve/Result/UIGamePveCommonResultView.lh";
    }
    onConstruct() {
      this.img_result_success = this.elems.getElement("img_result_success");
      this.img_result_fail = this.elems.getElement("img_result_fail");
      this.btn_back = this.elems.getElement("btn_back");
      this.btn_next = this.elems.getElement("btn_next");
      this.addClickListener(this.btn_back, this.onClickBack);
      this.addClickListener(this.btn_next, this.onClickNext);
      this.txt_result = this.elems.getElement("txt_result");
      this.txt_next = this.elems.getElement("txt_next");
      this.pveStarList = this.elems.getList("pveStarList");
      this.pveStarList.itemCtrl = PveStarItemCtrl;
      this.txt_condition_1 = this.elems.getElement("txt_condition_1");
      this.txt_condition_2 = this.elems.getElement("txt_condition_2");
      this.txt_condition_3 = this.elems.getElement("txt_condition_3");
    }
    onOpen(...args) {
      if (args.length > 0 && Array.isArray(args[0])) {
        const params = args[0];
        this.data = params[0];
        if (params.length > 1) {
          this.currentLevelCfg = params[1];
          console.log("this.currentLevelCfg", this.currentLevelCfg);
          this.nextLevelCfg = this.getNextLevelConfig(this.currentLevelCfg);
        }
      }
      this.updateView();
      const win = this.data.win;
      SoundManager.ins().playSound(win ? SoundID.SFX_WIN : SoundID.SFX_LOSE);
    }
    onClose() {
      let cfg = AdData.ins().getAdPointCfg(13 /* GAMROVER_RUSLT */);
      if (!cfg) {
        console.error("banner广告 ad_point 配置不存在", 13 /* GAMROVER_RUSLT */);
        return;
      }
      let type = ConfigUtil.Tables.comm_config.get(108).int_value;
      let time = ConfigUtil.Tables.comm_config.get(105).int_value;
      AdManager.ins().hideBannerAd(cfg.ad_id, type, time);
    }
    updateView() {
      const win = this.data.win;
      UIUtils.setActive(this.img_result_success, win);
      UIUtils.setActive(this.img_result_fail, !win);
      UIUtils.setActive(this.btn_next, win ? this.nextLevelCfg != null : true);
      if (win) {
        this.txt_next.text = "下一关";
        this.txt_result.visible = false;
        this.txt_condition_1.visible = true;
        this.txt_condition_2.visible = true;
        this.txt_condition_3.visible = true;
        this.pveStarList.setActive(true);
      } else {
        this.txt_next.text = "重新挑战";
        this.txt_result.visible = true;
        this.txt_condition_1.visible = false;
        this.txt_condition_2.visible = false;
        this.txt_condition_3.visible = false;
        this.pveStarList.setActive(false);
      }
      let starBools;
      if (Array.isArray(this.data.star) && this.data.star.length === 3) {
        starBools = this.data.star.map((star) => star === 1);
      } else {
        starBools = [false, false, false];
      }
      this.pveStarList.array = starBools;
      if (this.currentLevelCfg) {
        const sectionId = Math.floor(this.currentLevelCfg.order_id / 1e3);
        PveData.ins().renderConditionsWithIcons(
          this.txt_condition_1,
          this.txt_condition_2,
          this.txt_condition_3,
          sectionId,
          this.currentLevelCfg.order_id,
          this.currentLevelCfg
        );
      }
      let cfg = AdData.ins().getAdPointCfg(13 /* GAMROVER_RUSLT */);
      if (!cfg) {
        console.error("banner广告 ad_point 配置不存在", 13 /* GAMROVER_RUSLT */);
      }
      let adUnitId = cfg.ad_id;
      let type = ConfigUtil.Tables.comm_config.get(105).int_value;
      AdManager.ins().showBannerAd(
        0,
        Laya.Stage.ALIGN_BOTTOM,
        Laya.Stage.ALIGN_CENTER,
        adUnitId,
        type
      );
    }
    onClickNext() {
      const win = this.data && this.data.win;
      if (win) {
        if (this.nextLevelCfg) {
          const nextOrderId = this.nextLevelCfg.order_id;
          const sectionId = Math.floor(nextOrderId / 1e3);
          PveData.ins().selectedLevelOrderId = nextOrderId;
          PveData.ins().selectedSectionId = sectionId;
          PveManager.ins().startLevelWithPowerCheck(sectionId, nextOrderId);
        }
      } else {
        let currentOrderId = null;
        if (this.currentLevelCfg) {
          currentOrderId = this.currentLevelCfg.order_id;
        } else if (this.data && this.data.order_id) {
          currentOrderId = this.data.order_id;
        }
        if (currentOrderId != null) {
          const sectionId = Math.floor(currentOrderId / 1e3);
          PveData.ins().selectedLevelOrderId = currentOrderId;
          PveManager.ins().challengeLevel(sectionId);
        }
      }
    }
    onClickBack() {
      asgard.stage.StageManager.enterStage(GameConst.appName, 2 /* STAGE_LOBBY */);
      UIManager.ins().closeLayerForms(2 /* Second */);
      UIManager.ins().openForm(UIGamePveView);
    }
    /**
     * 获取下一关配置
     */
    getNextLevelConfig(config) {
      if (!config || config.order_id == null) {
        return null;
      }
      const currentOrderId = config.order_id;
      const currentSectionId = Math.floor(currentOrderId / 1e3);
      const currentLevelIndex = currentOrderId % 1e3;
      const levelInfos = PveUtils.getLevelInfosBySectionId(currentSectionId);
      const nextLevelIndex = currentLevelIndex + 1;
      const nextLevel = levelInfos.find((level2) => level2.order_id === currentSectionId * 1e3 + nextLevelIndex);
      if (nextLevel) {
        return nextLevel;
      }
      const nextSectionId = currentSectionId + 1;
      const nextSectionLevels = PveUtils.getLevelInfosBySectionId(nextSectionId);
      if (nextSectionLevels.length > 0) {
        return nextSectionLevels[0];
      }
      return null;
    }
  };

