  // src/script/module/pve/PveManager.ts
  var PveManager = class extends BaseClass {
    /**
     * 检查每杆是否可以使用道具
     * @returns 是否可以使用道具
     */
    canUseItemThisShot() {
      if (PveData.ins().itemUsedInCurrentShot) {
        TipsManager.ins().showMessageTips("每杆仅可使用一次道具");
        return false;
      }
      return true;
    }
    /**
     * 标记每杆已使用过道具
     */
    markItemUsedThisShot() {
      PveData.ins().itemUsedInCurrentShot = true;
    }
    /**
     * 分发PVE道具效果
     * @param itemId 道具ID
     */
    dispatchPveItemEffect(itemId) {
      if (itemId === 600012) {
        EventEngine.dispatchEvent(37 /* GamePveChange */, [{ type: "freeBallOnce" }]);
      } else if (itemId === 600011) {
        EventEngine.dispatchEvent(37 /* GamePveChange */, [{ type: "superAim" }]);
      } else if (itemId === 600014) {
        EventEngine.dispatchEvent(37 /* GamePveChange */, [{ type: "rotateOnce" }]);
      }
    }
    /**
     * 根据章节解析用于展示/挑战的目标关卡
     * 优先使用当前选中关卡，否则回退到服务器已开放的最新关卡，再兜底到章节第一关
     */
    resolveLevelOrderIdForSection(sectionId) {
      const openedOrderIds = PveData.ins().getOpenLevelOrderIds(sectionId) || [];
      let fallbackFirstOrderId = 0;
      if (openedOrderIds.length === 0) {
        const levelInfos = PveUtils.getLevelInfosBySectionId(sectionId);
        if (Array.isArray(levelInfos) && levelInfos.length > 0) {
          fallbackFirstOrderId = levelInfos.reduce(
            (min, cfg) => Math.min(min, Number(cfg.order_id)),
            Number(levelInfos[0].order_id)
          );
        }
      }
      const latestUnlockedOrderId = openedOrderIds.length > 0 ? openedOrderIds.reduce((max, cur) => Math.max(max, cur), openedOrderIds[0]) : fallbackFirstOrderId;
      const selectedOrderId = PveData.ins().selectedLevelOrderId;
      const selectedBelongsToSection = Math.floor(selectedOrderId / 1e3) === sectionId;
      return selectedOrderId > 0 && selectedBelongsToSection ? selectedOrderId : latestUnlockedOrderId;
    }
    /**
     * 购买使用道具
     * @param itemId 道具ID
     * @param itemNum 道具数量
     */
    buyUseItem(itemId, itemNum = 1) {
      if (!this.canUseItemThisShot()) {
        return;
      }
      TipsManager.ins().showMessageBox({
        title: "提示",
        content: "使用道具需要消耗1个道具,是否确定使用？",
        title_ok: "确定",
        callback_ok: () => {
          if (!this.canUseItemThisShot()) {
            return;
          }
          if (ThingUtils.isEnough(itemId, itemNum)) {
            ThingProtoUtils.player_use_item_req_tos(itemId, itemNum);
            this.markItemUsedThisShot();
            this.dispatchPveItemEffect(itemId);
            UIManager.ins().closeForm(UIPvePointGetView);
          } else {
            const shopItem = ShopData.ins().getShopItemByItemId(itemId);
            if (shopItem) {
              ShopManager.ins().buyShopItem(shopItem.id);
            }
          }
        }
      });
    }
    /**
     * 免费广告使用道具
     * 根据当前状态自动选择使用方式：免费使用 
     * @param itemId 道具ID
     * @param itemNum 道具数量
     */
    smartUseItem(itemId, itemNum = 1) {
      if (!this.canUseItemThisShot()) {
        return;
      }
      if (PveUtils.canUseItemWithAd(itemId)) {
        TipsManager.ins().showMessageBox({
          title: "提示",
          content: "看广告可获得1次免费使用次数",
          title_ok: "确定",
          callback_ok: () => {
            if (!this.canUseItemThisShot()) {
              return;
            }
            let jsoninfo = { "video_id": PlayerConst.USE_TOOLPVE_AD, "item_id": itemId, "item_num": itemNum };
            AdManager.ins().showAd({
              ad_id: PlayerConst.USE_TOOLPVE_AD,
              ext: JSON.stringify(jsoninfo),
              callback_succ_look: () => {
                if (!this.canUseItemThisShot()) {
                  return;
                }
                this.markItemUsedThisShot();
                this.dispatchPveItemEffect(itemId);
                UIManager.ins().closeForm(UIPvePointGetView);
                TipsManager.ins().showMessageTips("使用成功");
              }
            });
          }
        });
      }
    }
    /**
     * 显示PVE结算界面（统一入口）
     */
    showPveResultPanel(toc, currentConfig, currentSection) {
      const isFirstWin = PveUtils.isFirstTimeWin(toc, currentConfig);
      console.log(`是否首次通关: ${isFirstWin}`);
      if (isFirstWin) {
        console.log("显示首胜结算界面");
        UIManager.ins().openForm(UIGamePveFirstResultView, [toc, currentConfig, currentSection]);
      } else {
        console.log("显示通用结算界面");
        UIManager.ins().openForm(UIGamePveCommonResultView, [toc, currentConfig, currentSection]);
      }
    }
    /**
     * 挑战关卡
     * 如果选中了特定关卡就进入选中的关卡，否则进入最新已解锁关卡（以服务器回包为准）
     * @param sectionId 章节ID
     * @param useCurrentLevel 是否使用当前正在游戏的关卡（用于重玩）
     */
    challengeLevel(sectionId, useCurrentLevel = false) {
      var _a;
      const sectionData = PveUtils.getPveSectionData();
      let targetSectionId = sectionId || PveData.ins().getActiveSectionId();
      const section = sectionData.find((item2) => item2.id === targetSectionId);
      if (!section) {
        TipsManager.ins().showMessageTips("未解锁章节");
        return;
      }
      const totalStarsAll = PveUtils.calculateAllstarCount();
      const requiredStars = Number((_a = section == null ? void 0 : section.count_star) != null ? _a : 0);
      const sectionUnlockedByStars = totalStarsAll >= requiredStars;
      if (!sectionUnlockedByStars) {
        TipsManager.ins().showMessageTips("未解锁章节");
        return;
      }
      let targetLevelOrderId;
      if (useCurrentLevel && PveData.ins().CurrConfig) {
        targetLevelOrderId = PveData.ins().CurrConfig.order_id;
        console.log("PVE重玩: 使用当前关卡:", targetLevelOrderId);
      } else {
        targetLevelOrderId = this.resolveLevelOrderIdForSection(targetSectionId);
      }
      PveData.ins().setSelection(targetSectionId, targetLevelOrderId);
      this.startLevelWithPowerCheck(targetSectionId, targetLevelOrderId);
    }
    /**
     * 退出对局
     */
    quitBattle() {
      PveData.ins().clearCurrentBattle();
      PoolGameRoomData.ins().resetRoom();
      asgard.stage.StageManager.enterStage(GameConst.appName, 2 /* STAGE_LOBBY */);
    }
    /**
     * 获取章节奖励状态（阈值、已领、当前星数）
     */
    getSectionRewardState(sectionId) {
      const thresholds = PveUtils.getStar1BySectionId(sectionId) || [];
      const claimedTypes = PveData.ins().getClaimedSectionRewardTypes(sectionId);
      const currentStars = PveUtils.calculateSectionStarCount(sectionId);
      return { thresholds, claimedTypes, currentStars };
    }
    /**
     * 重新挑战当前关卡
     */
    restartCurrentLevel() {
      const sectionId = PveData.ins().getActiveSectionId();
      this.challengeLevel(sectionId);
    }
    /**
     * 检查并重新开始游戏
     */
    checkAndRestartGame() {
      const levelInfo = PveData.ins().consumePendingRestartLevel();
      if (!levelInfo)
        return;
      Laya.timer.frameOnce(1, this, () => {
        PveProtoUtils.game_pve_start_c2s(levelInfo.section, levelInfo.level);
      });
    }
    /**
     * 是否体力充足（含无限体力）
     */
    hasEnoughPower() {
      if (PveUtils.isBuyPower())
        return true;
      const info = PveData.ins().powerInfo || {};
      const cur = Number(info.bdpower || 0);
      return cur > 0;
    }
    /**
     * 统一入口：体力校验后开始关卡，不足则弹出加体力并记录待开关卡
     */
    startLevelWithPowerCheck(sectionId, levelOrderId) {
      if (this.hasEnoughPower()) {
        PveData.ins().HeartNum = 3;
        PveData.ins().itemUsedInCurrentShot = false;
        EventEngine.dispatchEvent(37 /* GamePveChange */, [PveData.ins().HeartNum]);
        PveProtoUtils.game_pve_start_c2s(sectionId, levelOrderId);
        return;
      }
      PveData.ins().markPowerInsufficient(sectionId, levelOrderId);
      UIManager.ins().openForm(UIAddPowerView);
      TipsManager.ins().showMessageTips("体力不足");
    }
  };

