  // src/script/module/poolGame/gameplay/pve/component/rules/PveEightBallGameRules.ts
  var PveEightBallGameRules = class extends EightBallGameRules {
    constructor() {
      super(...arguments);
      /**
       * 规则检测
       */
      this._checker = new PveRuleChecker();
      /**
       * 全局进球
       */
      this._totalBallin = [];
      /**
       * 全局移动
       */
      this._ballMoved = [];
      /**
       * 是否完成
       */
      this.isFinished = false;
      /**
       * 当前连杆数
       */
      this._currentSeqCount = 0;
    }
    /**
     * 击球开始前保存状态
     */
    OnShotBegin() {
      super.OnShotBegin();
    }
    /**
     * 球结算 - 继承八球规则的犯规和结算逻辑，但添加PVE星级判定
     */
    OnBallsSettle() {
      super.OnBallsSettle();
      if (this.game.isGameOver) {
        this.isFinished = true;
        return;
      }
      const curRoundBallin = this.shotResult.pottedBalls;
      this._checker.recordSeatPotted(this.shotResult.seatId, curRoundBallin);
      for (const ball of curRoundBallin) {
        if (this._totalBallin.indexOf(ball) == -1) {
          this._totalBallin.push(ball);
        }
      }
      for (const ballId of this.GetMovedBalls()) {
        if (this._ballMoved.indexOf(ballId) == -1) {
          this._ballMoved.push(ballId);
        }
      }
      this._checker.maxBallIn = Math.max(this._checker.maxBallIn, curRoundBallin.length);
      this._checker.ballIn = this._totalBallin;
      this._checker.ballMoved = this._ballMoved;
      if (curRoundBallin.length === 0) {
        this._checker.isOneStroke = false;
      }
      if (this.shotResult.seatId === 1) {
        if (this.shotResult.foul != 0 /* NONE */ || curRoundBallin.length === 0) {
          this._currentSeqCount = 0;
        } else {
          this._currentSeqCount++;
        }
        this._checker.maxSeqCount = Math.max(this._checker.maxSeqCount, this._currentSeqCount);
        this.updatePveTaskStatus();
      }
      if (curRoundBallin.find((ball) => ball.id === 8)) {
        const currentPlayerSeatId = this.shotResult.seatId;
        const eightBallGame = this.game.GetComponent(EightBallGame);
        if (!eightBallGame || !eightBallGame.SuitAssigned) {
          console.log("PVE-八球: 八球游戏未分球，无法判断黑八合法性");
          return;
        }
        if (currentPlayerSeatId === 2) {
          const aiTargetBalls = eightBallGame.TargetBalls(2);
          const aiSuitBalls = aiTargetBalls.filter((id) => id !== 8);
          const aiAllSuitPotted = aiSuitBalls.every(
            (id) => this._totalBallin.find((ball) => ball.id === id)
          );
          if (aiAllSuitPotted) {
            const playerTargetBalls = eightBallGame.TargetBalls(1);
            const playerSuitBalls = playerTargetBalls.filter((id) => id !== 8);
            const playerRemainingBalls = playerSuitBalls.filter(
              (id) => this.game.table.Balls[id] && this.game.table.Balls[id].active
            );
            const netWin = playerRemainingBalls.length;
            this._checker.setNetWinBalls(netWin);
            this.finishPveGame(false, 0);
            return;
          } else {
            this._checker.setNetWinBalls(0);
            this.finishPveGame(true, 1);
            return;
          }
        } else if (currentPlayerSeatId === 1) {
          const playerTargetBalls = eightBallGame.TargetBalls(1);
          const playerSuitBalls = playerTargetBalls.filter((id) => id !== 8);
          const playerAllSuitPotted = playerSuitBalls.every(
            (id) => this._totalBallin.find((ball) => ball.id === id)
          );
          if (playerAllSuitPotted) {
            const aiTargetBalls = eightBallGame.TargetBalls(2);
            const aiSuitBalls = aiTargetBalls.filter((id) => id !== 8);
            const aiRemainingBalls = aiSuitBalls.filter(
              (id) => this.game.table.Balls[id] && this.game.table.Balls[id].active
            );
            const netWin = aiRemainingBalls.length;
            this._checker.setNetWinBalls(netWin);
            this.finishPveGame(true, 1);
            return;
          } else {
            this._checker.setNetWinBalls(0);
            this.finishPveGame(false, 0);
            return;
          }
        }
      }
      this.updatePveTaskStatus();
    }
    /**
     * PVE游戏结算
     */
    finishPveGame(success, stars = 0) {
      this.isFinished = true;
      console.log(`PVE-八球游戏结束: 成功=${success}, 星数=${stars}`);
      const cfg = PveData.ins().CurrConfig;
      let flag2 = false;
      let flag3 = false;
      if (cfg) {
        const cond2 = this._checker.buildConditionString(cfg, 2);
        const cond3 = this._checker.buildConditionString(cfg, 3);
        if (cond2)
          flag2 = this._checker.checkSingleCondition(cond2);
        if (cond3)
          flag3 = this._checker.checkSingleCondition(cond3);
      }
      PveData.ins().lastStarFlags = [!!success, !!flag2, !!flag3];
      if (success) {
        this.game.Win(this.game.localPlayer);
      } else {
        this.game.Lose(this.game.localPlayer);
      }
      Laya.timer.once(1e3, this, () => {
        const currentLevelId = PveData.ins().selectedLevelOrderId;
        if (currentLevelId) {
          const flags = PveData.ins().lastStarFlags || [!!success, false, false];
          const payload = [Number(!!flags[0]), Number(!!flags[1]), Number(!!flags[2])];
          PveProtoUtils.game_pve_end_c2s(success, payload);
        }
      });
    }
    /**
     * 更新PVE任务状态并通知UI
     */
    updatePveTaskStatus() {
      const config = PveData.ins().CurrConfig;
      if (!config)
        return;
      let task1Completed = false;
      let progressCount = 0;
      let totalCount = 0;
      const eightBallGame = this.game.GetComponent(EightBallGame);
      if (eightBallGame && eightBallGame.SuitAssigned) {
        const playerTargetBalls = eightBallGame.TargetBalls(1);
        const playerSuitBalls = playerTargetBalls.filter((id) => id !== 8);
        const eightDone = !!this._totalBallin.find((e) => e.id === 8);
        let suitPotted = 0;
        for (const id of playerSuitBalls) {
          if (this._totalBallin.find((e) => e.id == id)) {
            suitPotted++;
          }
        }
        progressCount = suitPotted + (eightDone ? 1 : 0);
        totalCount = playerSuitBalls.length + 1;
        const nonEightAllDone = suitPotted >= playerSuitBalls.length;
        task1Completed = nonEightAllDone && eightDone;
        console.log("PVE-八球: 玩家目标球:", playerTargetBalls, "花色球:", playerSuitBalls, "已进花色球数:", suitPotted, "黑八完成:", eightDone);
        if (nonEightAllDone && !eightDone) {
          const aiTargetBalls = eightBallGame.TargetBalls(2);
          const aiSuitBalls = aiTargetBalls.filter((id) => id !== 8);
          const aiRemainingBalls = aiSuitBalls.filter(
            (id) => this.game.table.Balls[id] && this.game.table.Balls[id].active
          );
          const netWin = aiRemainingBalls.length;
          this._checker.setNetWinBalls(netWin);
          console.log("PVE-八球: 实时更新净胜球:", netWin, "AI剩余花色球:", aiRemainingBalls);
        }
      }
      const task2Completed = this._checker.checkSingleCondition(this._checker.buildConditionString(config, 2));
      const task3Completed = this._checker.checkSingleCondition(this._checker.buildConditionString(config, 3));
      EventEngine.dispatchEvent(38 /* GamePveStarChange */, [{
        task1Completed,
        task2Completed,
        task3Completed
      }]);
    }
  };

