  // src/script/module/poolGame/gameplay/guide/component/rules/GuideGameRules.ts
  var GuideGameRules = class extends EightBallGameRulesPhysics {
    constructor() {
      super(...arguments);
      this._isPhysic = false;
      /*
      * 全局进球 
      */
      this._totalBallin = [];
      /*
      * 是否完成 
      */
      this.isFinished = false;
    }
    /**
     * 击球开始前保存状态
     */
    OnShotBegin() {
      super.OnShotBegin();
    }
    OnBallsSettle() {
      super.OnBallsSettle();
      const curRoundBallin = this.shotResult.pottedBalls;
      for (const ball of this.shotResult.pottedBalls) {
        if (this._totalBallin.indexOf(ball) == -1) {
          this._totalBallin.push(ball);
        }
      }
      const currentConfig = GuideGameData.ins().CurrConfig;
      if (!currentConfig) {
        console.error("guide配置未找到");
        this.finishGame(false);
        return;
      }
      const thisTurnPottedEight = this.shotResult.pottedBalls.some((b) => b.id === 8);
      const targetBalls = this.getTargetBallsFromConfig(currentConfig);
      const isSuitGoal = currentConfig.goalBall === 1 || currentConfig.goalBall === 2;
      if (isSuitGoal) {
        if (thisTurnPottedEight) {
          const nonEightAllDone = this.isAllNonEightTargetsCompleted(currentConfig);
          if (nonEightAllDone) {
            this.finishGame(true, 0);
          }
          return;
        }
      }
      let targetBallCount = 0;
      for (const ballId of targetBalls) {
        if (curRoundBallin.find((e) => e.id == ballId)) {
          targetBallCount++;
        }
      }
      if (targetBallCount == 0) {
        return;
      }
      if (this._totalBallin.length >= targetBalls.length) {
        if (!isSuitGoal) {
          this.finishGame(true, 0);
        } else {
          const targetGame = this.game.GetComponent(TargetBallGame);
          if (targetGame) {
            targetGame.setTargetBallsBySeatId(this.game.player.SeatId, [8]);
          }
        }
      }
    }
    /**
     * 是否除黑八外的目标球都已进洞
     */
    isAllNonEightTargetsCompleted(cfg) {
      const targetBalls = this.getTargetBallsFromConfig(cfg);
      for (const ballId of targetBalls) {
        if (ballId === 8)
          continue;
        if (!this._totalBallin.find((e) => e.id == ballId)) {
          return false;
        }
      }
      return true;
    }
    /**
     * 从配置中获取已经分球的目标球列表
     */
    getTargetBallsFromConfig(config) {
      return GuideGameData.ins().getTargetBallsFromConfig(config);
    }
    /**
     * 结束游戏
     * @param success 是否成功 
     * @param stars 获得星数
     */
    finishGame(success, stars = 0) {
      this.isFinished = true;
      console.log(`引导模式游戏结束: 成功=${success}, 星数=${stars}`);
      this.game.EndGame();
    }
  };

