    /**充值 */
    recharge(msg, money) {
      if (!AppConfig.enable_report)
        return;
      let m = PlayerData.ins();
      if (DeviceUtils.ins().isWxGame || DeviceUtils.ins().isOppoGame || DeviceUtils.ins().isFastGame) {
        this._ta.track("recharge", {
          "user_id": m.playerId,
          "account_id": m.playerId,
          "device_id": m.playerId,
          "channel": this.getChannel(),
          "server_id": 1,
          "vip_level": PlayerData.ins().vip,
          "level": PlayerData.ins().level,
          "money": money,
          "game_order_id": msg.order_id,
          "SDK_order_id": msg.order_id,
          "pay_order_id": "0000000000",
          "money_type": "CNY",
          "payway": 1,
          "is_success": 1,
          "openid": m.openId
        }, /* @__PURE__ */ new Date(), (res) => {
          if (res.code == 0) {
            this._ta.userSet({ "lastrecharge_time": /* @__PURE__ */ new Date(), "lastrecharge_money": money });
            this._ta.userAdd({ "totalrecharge_money": money, "totalrecharge_times": 1 });
          }
        });
      }
      if (DeviceUtils.ins().isWxGame) {
        if (m.ksChannel) {
          let param = `?callback=${m.callback}&event_type=${3}&event_time=${Date.now()}&purchase_amount=${money}`;
          this._httpReq(this._kuaishouUrl + param, "get", "json").then((d) => {
            console.warn(d);
          });
        }
        if (m.ttChanel) {
          let time = TimeData.ins().serverTimeS;
          let nonce = Math.floor(Math.random() * 10);
          let strList = [this._ttToken, time, nonce];
          strList.sort();
          let buffer = "";
          strList.forEach((str) => {
            buffer += str;
          });
          let sign = CryptoJS.SHA1(buffer);
          let data = {
            "clue_token": m.ttCall,
            // 用户跳转小程序时携带的clue_token参数
            "union_id": ``,
            // 微信union_id
            "open_id": m.openId,
            // 微信open_id，必须回传
            "event_type": "2",
            // 事件类型，string格式
            "props": {
              "pay_amount": money * 100
              // 当event_type为2，使用付费类出价产品时需上报，单位为分，格式int
            }
          };
          let param = `?timestamp=${time}&nonce=${nonce}&signature=${sign}`;
          this._httpReq(this._ttUrl + param, "post", "json", data);
        }
        this.wxGameTraceData("PURCHASE", money * 100);
      }
    }
    //微信小游戏上报广告归因数据
    wxGameTraceData(action_type, action_paramValue = 0) {
      let m = PlayerData.ins();
      if (!AppConfig.enable_report)
        return;
      let query = platform.getLaunchOptionsSync().query;
      if (query && query[`weixinadinfo`] && query[`weixinadinfo`] !== `` && query[`gdt_vid`]) {
        m.txChanel = true;
        m.txClickId = query[`gdt_vid`];
      }
      if (m.txChanel) {
        let appId = GameConst.appName === `ball_master` ? `wx11182ab1e7061f5e` : `wxe6cb33a08cba9a28`;
        let data = {
          "actions": [{
            "outer_action_id": m.txClickId,
            "action_time": Math.floor(TimeData.ins().serverTime / 1e3),
            "user_id": {
              "wechat_openid": m.openId,
              "wechat_app_id": appId
            },
            "action_type": action_type,
            "trace": {
              "click_id": m.txClickId
            },
            "action_param": {
              "value": action_paramValue
            }
          }]
        };
        console.log("wxGameTraceData===", this._txUrl, JSON.stringify(data));
        this._httpReq(this._txUrl, "post", "json", data).then((retData) => {
          if (retData) {
            console.log("httpRequest COMPLETE===", JSON.stringify(retData));
          }
        }, (data1) => {
          console.log("httpRequest error===");
          if (data1) {
            console.log("httpRequest error===", JSON.stringify(data1));
          }
        });
      }
    }
