    /**自定义事件上报 */
    sendEvent(eventId, eventDes) {
      let deviceType = "none";
      this._device = platform.getMachineInfo().machine_name;
      deviceType = platform.getMachineInfo().phone_type;
      let openid = PlayerData.ins().openId;
      if (openid == "") {
        openid = platform.getStorageSync("openId");
        if (openid == "") {
          eventId = "new_" + eventId;
        }
      }
      let level2 = PlayerData.ins().level;
      let uid = PlayerData.ins().playerId;
      let param = `?channel=${this.channel}&gameId=${GameConst.appName}&env=${openid}&device=${this._device}&ip=${this._networkType}&deviceType=${deviceType}`;
      param += `&event=${eventId}&des=${eventDes}&client_version=${AppConfig.getFullVersion()}&playerId=${uid}&subChannel=${level2}&extra=${AppConfig.getFullVersion()}`;
      this._httpReq(this._recodeUrl + param, "get", "json");
    }
