    IsPay() {
      if (DeviceUtils.ins().isWxGame || DeviceUtils.ins().isQQGame || DeviceUtils.ins().isKSGame || DeviceUtils.ins().isAliPayGame) {
        let sysInfo = platform.getSystemInfoSync();
        if (sysInfo && sysInfo.platform == "windows" || Laya.Browser.onAndroid) {
          return false;
        } else if (Laya.Browser.onIOS) {
          return AppConfig.is_sandbox || PlayerData.ins().level < ConfigUtil.Tables.comm_config.get(102).int_value;
        }
      } else if (DeviceUtils.ins().isTTGame) {
        if (DeviceUtils.ins().isNovelapp || Laya.Browser.onIOS) {
          return AppConfig.is_sandbox || PlayerData.ins().level < ConfigUtil.Tables.comm_config.get(102).int_value;
        }
        return false;
      } else {
        return false;
      }
    }
