  // src/script/utils/CommonFun.ts
  var CommonFun = class {
    // 获取物品的名字
    static GetItemName(itemId) {
      var itemCfg = ThingData.ins().getThingConfig(itemId);
      if (!itemCfg) {
        return "未知道具";
      }
      if (itemCfg.maintype === 4 /* prop */) {
        if (itemCfg.usetype === 2 /* combined */) {
          const cfg = ThingData.ins().getThingSynthesisCfg(itemId);
          if (cfg && cfg.length > 0) {
            return `${this.GetItemName(cfg[0].com_id)}碎片`;
          }
        }
      }
      return LangData.ins().getLang(itemCfg.name);
    }
    // 获取物品的描述
    static GetItemdes(itemId) {
      var itemCfg = ThingData.ins().getThingConfig(itemId);
      let strArr = itemCfg.field.split(",");
      let day = "";
      if (strArr.length >= 2) {
        var time = parseInt(strArr[1]);
        day = "(0天)";
        if (itemCfg.tag === 19) {
          day = "(试用" + time + "局)";
        } else if (time >= 24) {
          day = "(" + Math.floor(time / 24) + "天)";
        } else {
          day = "(" + time + "小时)";
        }
      }
      let template = LangData.ins().getLang(itemCfg.name);
      let quality = ThingUtils.getQualityStr(itemCfg.quality);
      if (itemCfg) {
        if (itemCfg.maintype === 1 /* cue */) {
          if (itemCfg.secondtype === 0 /* time_limit */ || itemCfg.secondtype === 1 /* charge */ || itemCfg.secondtype === 3 /* trial */) {
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), quality);
          }
        } else if (itemCfg.maintype === 2 /* clothes */) {
          if (itemCfg.secondtype === 2 /* experience */ || itemCfg.secondtype === 1 /* charge */ || itemCfg.secondtype === 3 /* trial */) {
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), day, template);
          }
        } else if (itemCfg.maintype === 3 /* table */) {
          if (itemCfg.secondtype === 1 /* charge */) {
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), day, template);
          }
        } else if (itemCfg.maintype === 4 /* prop */) {
          if (itemCfg.secondtype === 1 /* charge */) {
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), day, quality, template);
          } else if (itemCfg.secondtype === 2 /* experience */) {
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), day, template);
          }
          if (itemCfg.usetype === 2 /* combined */) {
            const combinationCfg = ThingData.ins().getThingSynthesisCfg(itemCfg.id);
            let name = "";
            if (combinationCfg && combinationCfg.length > 0) {
              name = `${this.GetItemName(combinationCfg[0].com_id)}`;
            }
            return StringUtils.format(LangData.ins().getLang(itemCfg.des), name);
          }
        }
        return LangData.ins().getLang(itemCfg.des);
      } else {
        return "";
      }
    }
  };

