  var BagItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.txt_name = ElemFinder.getText(rootNode, "txt_name");
      this.txt_num = ElemFinder.getElement(rootNode, "txt_num");
      this.img_item = ElemFinder.getLoader(rootNode, "img_item");
      this.btn_bug = ElemFinder.getElement(rootNode, "btn_buy");
      UIUtils.addClickListener(this.btn_bug, this, this.onClickBug);
      this.txt_title = ElemFinder.getElement(this.btn_bug, "txt_title");
    }
    update(data, index, ...args) {
      this.data = data;
      const itemId = data.config.id;
      const thingCfg = ThingData.ins().getThingConfig(itemId);
      this.txt_name.text = CommonFun.GetItemName(thingCfg.id);
      this.img_item.src = ThingUtils.getThingIconPath(itemId);
      this.txt_num.text = `×${data.num}`;
      if (thingCfg.usetype) {
        const firstType = thingCfg.usetype;
        const secondId = thingCfg.use_to;
        switch (firstType) {
          case 1:
            this.txt_title.text = LangData.ins().getLang(1004);
            break;
          case 2:
            const cfg = ThingData.ins().getThingSynthesisCfg(itemId);
            if (cfg && cfg.length > 0) {
              const synthesisItemId = cfg[0].com_id;
              if (ThingUtils.isSynthesizeItemOwned(synthesisItemId)) {
                this.txt_title.text = LangData.ins().getLang(1069);
              } else {
                this.txt_title.text = LangData.ins().getLang(1009);
              }
            } else {
              console.error("没有找到合成配置  ", itemId);
            }
            break;
          case 3:
            this.txt_title.text = LangData.ins().getLang(1068);
            break;
          case 4:
            this.txt_title.text = "自动使用";
            break;
          default:
            this.txt_title.text = "";
            break;
        }
      } else {
        this.txt_title.text = "";
      }
    }
    onClickBug() {
      if (!this.data.config.usetype) {
        return;
      }
      const firstType = this.data.config.usetype;
      const secondId = this.data.config.use_to;
      switch (firstType) {
        case 1:
          if (this.data.id === 600010 /* CHANGE_NICK_CARD */) {
            PlayerManager.ins().updateNick();
            return;
          }
          if (this.data.id === 600009 /* CHANGE_SEX_CARD */) {
            PlayerManager.ins().changeSex();
            return;
          }
          if (this.data.num > 1) {
            UIManager.ins().openForm(UIBagUseItemView, this.data.id);
          } else {
            ThingProtoUtils.player_use_item_req_tos(this.data.id, this.data.num);
          }
          break;
        case 2:
          UIManager.ins().openForm(UIBagAddView, this.data.id);
          break;
        case 3:
          if (secondId == 3) {
            UIManager.ins().openForm(UIMainView);
          } else {
            GameNavigator.ins().gotoWithClose(secondId);
          }
          break;
        case 4:
          console.log("自动使用道具:", this.data.id);
          break;
        default:
          console.log("未知的usetype:", this.data.config.usetype);
          break;
      }
    }
  };

