  // src/script/module/club/ClubRedDot.ts
  var ClubRedDot = class extends RedDotBase {
    constructor() {
      super(100302 /* club */);
      this.setConnectedEvents(11 /* ClubChange */);
    }
    doCheck() {
      if (ClubData.ins().clubId == 0 || !ClubData.ins().clubInfo) {
        return 0;
      }
      const clubApplyList = ClubData.ins().clubApplyList;
      if (clubApplyList) {
        this.hasNewApply = ClubData.ins().clubMemberConfig.change_limit == 1 && clubApplyList.length > 0;
      }
      this.hasTaskReward = false;
      if (ClubData.ins().clubInfo.clock_in_tag == 0) {
        this.hasTaskReward = true;
      }
      if (!this.hasTaskReward) {
        const clubTaskInfo = ClubData.ins().clubTaskInfo;
        if (clubTaskInfo) {
          for (let i = 0, len = clubTaskInfo.rewards_club_list.length; i < len; i++) {
            const rewardInfo = clubTaskInfo.rewards_club_list[i];
            if (rewardInfo.state == 2) {
              this.hasTaskReward = true;
              break;
            }
          }
          if (!this.hasTaskReward) {
            for (let i = 0, len = clubTaskInfo.rewards_personal_list.length; i < len; i++) {
              const rewardInfo = clubTaskInfo.rewards_personal_list[i];
              if (rewardInfo.state == 2) {
                this.hasTaskReward = true;
                break;
              }
            }
          }
        }
      }
      return this.hasNewApply || this.hasTaskReward ? 1 : 0;
    }
  };

