  // src/script/module/poolGameAdv/PoolGameAdvRedDot.ts
  var PoolGameAdvRedDot = class extends RedDotBase {
    constructor() {
      super(102001 /* Advance */);
      this.setConnectedEvents(14 /* GameAdvChange */);
    }
    doCheck() {
      const progress = PoolGameAdvData.ins().getNowTeachProgress();
      const sections = PoolGameAdvData.ins().getTeachSections();
      let rewardNum = 0;
      for (const section of sections) {
        const rewardGot = PoolGameAdvData.ins().isSectionRewardGot(section.id);
        const hasReward = !rewardGot && progress.section > section.id;
        if (hasReward) {
          rewardNum++;
        }
      }
      return rewardNum;
    }
  };

