  // src/script/module/shop/data/ExchangeShopData.ts
  var ExchangeShopItem = class {
    constructor() {
      /**
       * 已购买次数
       */
      this.buyTimes = 0;
    }
  };
  var ExchangeShopData = class extends BaseDataClass {
    constructor() {
      super(...arguments);
      this._items = [];
      this._buyTimesMap = {};
      /** 今日已领取免费兑换的商品序号 */
      this._freeUsedIdSet = /* @__PURE__ */ new Set();
    }
    onReady() {
      this._items = [];
      this._buyTimesMap = {};
      this._freeUsedIdSet = /* @__PURE__ */ new Set();
      const list = ConfigUtil.Tables.exchange_shop.getDataList();
      for (const cfg of list) {
        const item2 = new ExchangeShopItem();
        item2.id = cfg.id;
        item2.config = cfg;
        item2.buyTimes = 0;
        this._items.push(item2);
      }
    }
    /**
     * 同步商城已购列表（兑换商品序号与商城商品id共用 buyed_list）
     */
    setBuyedList(buyedList) {
      this._buyTimesMap = {};
      if (buyedList) {
        for (const pair of buyedList) {
          this._buyTimesMap[pair.id] = pair.num;
        }
      }
      for (const item2 of this._items) {
        item2.buyTimes = this._buyTimesMap[item2.config.id] || 0;
      }
    }
    /**
     * 同步每日免费已兑换列表
     */
    setFreeUsedList(idList) {
      this._freeUsedIdSet = new Set(idList || []);
    }
    /**
     * 同步兑换商品列表数据（包含购买次数）
     */
    setExchangeList(exchangeList) {
      if (!exchangeList)
        return;
      for (const exchange2 of exchangeList) {
        const item2 = this.getItemById(exchange2.id);
        if (item2) {
          item2.buyTimes = exchange2.count || 0;
        }
      }
    }
    /**
     * 是否今日免费已使用
     */
    isFreeUsed(id) {
      return this._freeUsedIdSet.has(id);
    }
    /**
     * 标记免费兑换已使用（购买成功后立即调用）
     */
    markFreeUsed(id) {
      this._freeUsedIdSet.add(id);
    }
    /**
     * 是否可享每日首次免费
     */
    canFreeExchange(item2) {
      return item2.config.type_exchange === 1 && !this.isFreeUsed(item2.config.id);
    }
    /**
     * 是否已拥有（购买类型=2）
     */
    isOwned(item2) {
      if (item2.config.if_buy !== 2) {
        return false;
      }
      const itemId = item2.config.item_id;
      const thingCfg = ThingData.ins().getThingConfig(itemId);
      if (!thingCfg) {
        return false;
      }
      switch (thingCfg.maintype) {
        case 1 /* cue */:
          return ThingUtils.isCueOwned(itemId);
        case 2 /* clothes */:
          return ThingUtils.isDressOwned(itemId);
        case 3 /* table */:
          return ThingUtils.isTableOwned(itemId);
        default:
          return ThingUtils.isSynthesizeItemOwned(itemId);
      }
    }
    /**
     * 是否已售罄（购买类型=1 且达到限购）
     */
    isSoldOut(item2) {
      if (item2.config.if_buy !== 1) {
        return false;
      }
      const limit = item2.config.buy_times;
      if (limit <= 0) {
        return false;
      }
      return item2.buyTimes >= limit;
    }
    /**
     * 是否不可购买（置灰并排到列表末尾）
     */
    isUnavailable(item2) {
      return this.isSoldOut(item2);
    }
    /**
     * 是否需要隐藏（购买类型=2且已拥有）
     */
    isHidden(item2) {
      return item2.config.if_buy === 2 && this.isOwned(item2);
    }
    /**
     * 获取展示列表：可购买按 sort 升序，不可购买置后，已拥有的限购类型商品不显示
     */
    getDisplayList() {
      const available = [];
      const unavailable = [];
      for (const item2 of this._items) {
        if (this.isHidden(item2)) {
          continue;
        }
        if (this.isUnavailable(item2)) {
          unavailable.push(item2);
        } else {
          available.push(item2);
        }
      }
      const sortFn = (a, b) => a.config.sort - b.config.sort;
      available.sort(sortFn);
      unavailable.sort(sortFn);
      return available.concat(unavailable);
    }
    getItemById(id) {
      return this._items.find((e) => e.id === id);
    }
    /**
     * 是否有可免费兑换的商品（用于红点显示）
     */
    hasFreeExchangeItem() {
      for (const item2 of this._items) {
        if (this.canFreeExchange(item2) && !this.isOwned(item2)) {
          return true;
        }
      }
      return false;
    }
  };

