  // src/script/module/club/view/UIClubCreateView.ts
  var UIClubCreateView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/club/UIClubCreateView.lh";
    }
    onConstruct() {
      this.img_clubLogo = this.elems.getElement("img_clubLogo");
      this.btn_changeLogo = this.elems.getElement("btn_changeLogo");
      this.input_name = this.elems.getElement("input_name");
      this.input_notice_in = this.elems.getElement("input_notice_in");
      this.input_notice_out = this.elems.getElement("input_notice_out");
      this.input_name.textIns.on(Laya.Event.INPUT, this, this.updateInputNum);
      this.input_notice_in.textIns.on(Laya.Event.INPUT, this, this.updateInputNum);
      this.input_notice_out.textIns.on(Laya.Event.INPUT, this, this.updateInputNum);
      this.input_notice_in.maxChars = ClubConst.MAX_NOTICE_IN_INPUT_LEN;
      this.input_notice_out.maxChars = ClubConst.MAX_NOTICE_OUT_INPUT_LEN;
      this.input_name.maxChars = ClubConst.MAX_CLUB_NAME_INPUT_LEN;
      this.input_notice_in.prompt = LangData.ins().getLang(ClubConst.CLUB_NOTICE_IN_TIP_ID);
      this.input_notice_out.prompt = LangData.ins().getLang(ClubConst.CLUB_NOTICE_OUT_TIP_ID);
      this.txt_input_name_size = this.elems.getElement("txt_input_name_size");
      this.txt_input_out_size = this.elems.getElement("txt_input_out_size");
      this.txt_input_in_size = this.elems.getElement("txt_input_in_size");
      this.txt_cost = this.elems.getElement("txt_cost");
      this.btn_create = this.elems.getElement("btn_create");
      this.addClickListener(this.btn_changeLogo, this.onClickChangeLogo);
      this.addClickListener(this.btn_create, this.onClickCreate);
      this.addClickListener(this.elems.getElement("btn_x"), this.close);
    }
    onOpen(...args) {
      const heads = ClubData.ins().getClubHeadCfgList();
      this.selectedHeadCfg = heads[Math.floor(Math.random() * heads.length)];
      this.input_name.text = "";
      this.input_notice_in.text = "";
      this.input_notice_out.text = "";
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const cost = ClubData.ins().getCreateNeedItem();
      this.txt_cost.text = `${cost.num}` + ThingUtils.getThingHtmlIconPath(cost.id, 48, 48);
      this.img_clubLogo.src = ClubUtils.getClubLogoPath(this.selectedHeadCfg.id);
      this.updateInputNum();
    }
    /**
     * 输入字符更新
     */
    updateInputNum() {
      this.txt_input_name_size.text = `${this.input_name.text.length}/${this.input_name.maxChars}`;
      this.txt_input_in_size.text = `${this.input_notice_in.text.length}/${this.input_notice_in.maxChars}`;
      this.txt_input_out_size.text = `${this.input_notice_out.text.length}/${this.input_notice_out.maxChars}`;
    }
    /**
     * 点击更换Logo
     */
    onClickChangeLogo() {
      UIManager.ins().openForm(UIClubLogoSelectView, this.selectedHeadCfg, (cfg) => {
        this.selectedHeadCfg = cfg;
        this.updateView();
      });
    }
    /**
     * 点击创建俱乐部
     */
    onClickCreate() {
      let clubName = this.input_name.text.trim();
      if (clubName.length == 0) {
        TipsManager.ins().showMessageTips("请输入正确的俱乐部名字");
        return;
      }
      const cost = ClubData.ins().getCreateNeedItem();
      if (CurrencyData.ins().diamond < cost.num) {
        ShopManager.ins().showNoDiamondTips(cost.num, () => {
          this.onClickCreate();
        });
      } else {
        ClubProtoUtils.club_create_club_tos(clubName, this.selectedHeadCfg.id, this.input_notice_in.text || this.input_notice_in.prompt, this.input_notice_out.text || this.input_notice_out.prompt);
      }
    }
  };

  // src/script/module/club/view/UIClubInfoView.ts
  var UIClubInfoView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/club/UIClubInfoView.lh";
    }
    onConstruct() {
      this.img_clubLogo = this.elems.getElement("img_clubLogo");
      this.txt_name = this.elems.getElement("txt_name");
      this.txt_level = this.elems.getElement("txt_level");
      this.txt_condition = this.elems.getElement("txt_condition");
      this.txt_clubId = this.elems.getElement("txt_clubId");
      this.txt_desc = this.elems.getElement("txt_desc");
      this.txt_memberCnt = this.elems.getElement("txt_memberCnt");
      this.btn_apply = this.elems.getElement("btn_apply");
      this.btn_cancel = this.elems.getElement("btn_cancel");
      this.ownerHeadItem = new HeadIconCtrl(this.elems.getElement("ownerHeadItem"));
      this.userName = new UserNameCtrl(this.elems.getElement("txt_ownerNick"));
      this.gender = new GenderCtrl(this.elems.getElement("gender"));
      this.txt_lv = this.elems.getElement("txt_lv");
      this.img_clubPosition = this.elems.getElement("img_clubPos");
      this.addClickListener(this.btn_apply, this.onClickApply);
      this.addClickListener(this.btn_cancel, this.onClickCancel);
      this.addClickListener(this.elems.getElement("btn_x"), this.close);
    }
    onRegisterEvent() {
      this.registerEvent(11 /* ClubChange */, this.updateView);
      this.registerEvent(6 /* PlayerInfoChange */, this.updateHead);
    }
    onOpen(data) {
      this._data = data;
      this.userName.update("", 0);
      PlayerProtoUtils.player_info_query_simple_req_tos([data.owner]);
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const data = this._data;
      const levelCfg = ClubData.ins().getClubLevelCfg(data.lvl);
      this.img_clubLogo.src = ClubUtils.getClubLogoPath(data.headicon);
      this.txt_name.text = data.name;
      this.txt_level.text = `等级：${data.lvl}级`;
      const applyStr = data.auto_apply ? "无需审批" : "需要审批";
      this.txt_condition.text = "申请条件：" + applyStr + "，" + data.request_lvl + "级以上";
      this.txt_memberCnt.text = data.user_num + "/" + levelCfg.member_limit;
      this.txt_clubId.text = `ID:${data.clubid}`;
      this.txt_desc.text = data.notice;
      UIUtils.setActive(this.btn_apply, !data.is_apply);
      UIUtils.setActive(this.btn_cancel, data.is_apply);
      this.updateHead();
    }
    updateHead() {
      var _a;
      const data = this._data;
      const playerInfo = PlayerManager.ins().getSimplePlayerInfo(data.owner);
      if (playerInfo) {
        this.userName.update(playerInfo.nick, playerInfo.is_subscribe);
        this.ownerHeadItem.update(playerInfo.head_icon, playerInfo.head_frame, playerInfo.sex, 0, (_a = playerInfo.vip_lvl) != null ? _a : 0);
        this.gender.update(playerInfo.sex);
        this.txt_lv.text = `lv${playerInfo.lvl}`;
      }
    }
    /**
     * 点击申请
     */
    onClickApply() {
      ClubProtoUtils.club_join_club_apply_tos(this._data.clubid);
    }
    /**
     * 点击取消申请
     */
    onClickCancel() {
      ClubProtoUtils.club_join_club_cancel_apply_tos(this._data.clubid);
    }
  };

  // src/script/module/club/view/UIClubAddView.ts
  var UIClubAddView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      /**
       * 标记当前是否正在搜索
       */
      this.isSearching = false;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/club/UIClubAddView.lh";
    }
    onConstruct() {
      this.list_items = this.elems.getList("list_items");
      this.list_items.itemCtrl = ClubListItemCtrl;
      this.list_items.setRenderListener(this, this.onUpdateListItemAt);
      this.input = this.elems.getElement("input");
      this.btnSearch = this.elems.getElement("btnSearch");
      this.check_condition = this.elems.getElement("check_condition");
      this.btn_createClub = this.elems.getElement("btn_createClub");
      this.btn_quickAdd = this.elems.getElement("btn_quickAdd");
      this.addClickListener(this.btn_createClub, this.onClickCreateClub);
      this.addClickListener(this.btn_quickAdd, this.onClickQuickAdd);
      this.addClickListener(this.btnSearch, this.onClickSearch);
      this.addClickListener(this.check_condition, this.onClickConSwitch);
    }
    onRegisterEvent() {
      this.registerEvent(11 /* ClubChange */, this.updateView);
    }
    onOpen(...args) {
      this.check_condition.selected = false;
      this.isSearching = false;
      this.input.text = "";
      this.updateView();
      this.list_items.scrollTop();
      ClubPageManager.ins().clubPage.startPage(1);
    }
    onClose() {
    }
    updateView() {
      if (this.isSearching) {
        return;
      }
      const page = this.check_condition.selected ? ClubPageManager.ins().clubRecomPage : ClubPageManager.ins().clubPage;
      this.list_items.array = page.array;
      if (ClubData.ins().clubId > 0) {
        this.close();
        return;
      }
    }
    showSearchResult(searchList) {
      this.isSearching = true;
      this.list_items.array = searchList;
    }
    /**
     * 列表更新到当前分页终点时，请求下一页数据
     */
    onUpdateListItemAt(index) {
      if (index >= this.list_items.arrayLen - 10) {
        if (this.check_condition.selected) {
          ClubPageManager.ins().clubRecomPage.tryNextPage();
        } else {
          ClubPageManager.ins().clubPage.tryNextPage();
        }
      }
    }
    /**
     * 点击创建俱乐部
     */
    onClickCreateClub() {
      UIManager.ins().openForm(UIClubCreateView);
    }
    /**
     * 点击快速加入俱乐部
     */
    onClickQuickAdd() {
      ClubProtoUtils.club_quick_join_tos();
    }
    /**
     * 点击搜索回调
     */
    onClickSearch() {
      const clubId = parseInt(this.input.text);
      this.input.text = "";
      if (!clubId) {
        this.isSearching = false;
        this.updateView();
      } else {
        ClubProtoUtils.club_search_tos(clubId);
      }
    }
    /**
     * 点击条件切换
     */
    onClickConSwitch() {
      if (this.check_condition.selected) {
        ClubPageManager.ins().clubRecomPage.startPage(1);
      }
      this.updateView();
      this.list_items.scrollTop();
    }
  };
  var ClubListItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.img_clubLogo = ElemFinder.getElement(rootNode, "img_clubLogo");
      this.txt_name = ElemFinder.getElement(rootNode, "box/txt_name");
      this.txt_level = ElemFinder.getElement(rootNode, "box/img_4/txt_level");
      this.txt_condition_level = ElemFinder.getElement(rootNode, "txt_condition_level");
      this.txt_condition_apply = ElemFinder.getElement(rootNode, "txt_condition_apply");
      this.txt_memberCnt = ElemFinder.getElement(rootNode, "txt_memberCnt");
      this.btn_add = ElemFinder.getElement(rootNode, "btn_add");
      this.btn_apply = ElemFinder.getElement(rootNode, "btn_apply");
      this.btn_cancel = ElemFinder.getElement(rootNode, "btn_cancel");
      UIUtils.addClickListener(this.btn_add, this, this.onClickApply);
      UIUtils.addClickListener(this.btn_apply, this, this.onClickApply);
      UIUtils.addClickListener(this.btn_cancel, this, this.onClickCancel);
      UIUtils.addClickListener(ElemFinder.getElement(rootNode, "img"), this, this.onClickInfo);
    }
    update(data, index, ...args) {
      this.data = data;
      const levelCfg = ClubData.ins().getClubLevelCfg(data.lvl);
      this.img_clubLogo.src = ClubUtils.getClubLogoPath(data.headicon);
      this.txt_name.text = data.name;
      this.txt_level.text = `${data.lvl}级`;
      this.txt_condition_apply.text = data.auto_apply == 1 ? "无需审批" : "需要审批";
      this.txt_condition_level.text = data.request_lvl + "级以上";
      this.txt_memberCnt.text = data.user_num + "/" + levelCfg.member_limit;
      if (data.is_apply) {
        UIUtils.setActive(this.btn_cancel, true);
        UIUtils.setActive(this.btn_apply, false);
        UIUtils.setActive(this.btn_add, false);
      } else {
        UIUtils.setActive(this.btn_apply, data.auto_apply != 1);
        UIUtils.setActive(this.btn_add, data.auto_apply == 1);
        UIUtils.setActive(this.btn_cancel, false);
      }
    }
    /**
     * 点击申请
     */
    onClickApply() {
      if (PlayerData.ins().level < this.data.request_lvl) {
        TipsManager.ins().showMessageTips(ClubConst.CLUB_LEVEL_TIP);
        return;
      }
      ClubProtoUtils.club_join_club_apply_tos(this.data.clubid);
    }
    /**
     * 点击取消申请
     */
    onClickCancel() {
      ClubProtoUtils.club_join_club_cancel_apply_tos(this.data.clubid);
    }
    /**
     * 点击查看详情
     */
    onClickInfo() {
      UIManager.ins().openForm(UIClubInfoView, this.data);
    }
  };

