  // src/script/module/club/ClubManager.ts
  var ClubManager = class extends BaseClass {
    constructor() {
      super(...arguments);
      /**
       * 简单玩家信息
       */
      this._memberPosInfos = {};
      this._memberPosBatchList = [];
    }
    /**
     * 请求玩家信息
     * @param userId 用户id
     * @returns 
     */
    requestClubPosInfo(userId) {
      if (this._memberPosBatchList.indexOf(userId) == -1) {
        this._memberPosBatchList.push(userId);
        if (!this._memberPosRequested) {
          this._memberPosRequested = true;
          Laya.timer.once(300, this, () => {
            ClubProtoUtils.club_get_user_post_tos(this._memberPosBatchList);
            this._memberPosRequested = false;
            this._memberPosBatchList = [];
          });
        }
      }
    }
    /**
     * 内部使用
     * @param msg 
     */
    _club_get_user_post_toc(toc) {
      if (toc.list.length > 0) {
        for (let temp of toc.list) {
          this._memberPosInfos[temp.userid] = temp;
        }
      }
    }
    /**
     * 获取玩家职位信息
     * @param userId 用户id
     * @returns 
     */
    getUserPosInfo(userId) {
      return this._memberPosInfos[userId];
    }
    /**
     * 请求加入俱乐部
     * @param clubid 俱乐部id
     * @param clubName 俱乐部名称
     */
    requestJoinClub(clubid, clubName) {
      if (clubid == 0) {
        TipsManager.ins().showMessageTips(`俱乐部邀请信息有误`);
        return;
      }
      if (ClubData.ins().clubId === 0) {
        if (!FuncLimitUtils.isFuncAvailable(100302 /* club */, true)) {
          return;
        }
        TipsManager.ins().showMessageBox({
          content: `确定加入${clubName}俱乐部吗？`,
          title_ok: "加入",
          callback_ok: () => {
            ClubProtoUtils.club_join_club_apply_tos(clubid);
          }
        });
      } else {
        TipsManager.ins().showMessageTips(`已加入了俱乐部`);
      }
    }
    /**
     * 请求更新俱乐部信息
     */
    requestUpdateClub() {
      ClubProtoUtils.club_get_my_club_info_tos();
    }
    /**
     * 发送俱乐部邀请信息 
     * toid 邀请对象
     * isAttention 是否已关注（从关注列表邀请时传入true跳过关注检查）
     */
    inviteAddClub(chatTo, toid, isAttention) {
      if (ClubData.ins().clubId === 0) {
        TipsManager.ins().showMessageTips(`你还没有加入俱乐部`);
        return;
      }
      const success = () => {
        const clubInfo = ClubData.ins().clubInfo;
        const levelCfg = ClubData.ins().getClubLevelCfg(clubInfo.lvl);
        ChatProtoUtils.chat_send_msg_tos(chatTo, "", cmd.CHAT_TYPE.CLUB_INVITE, toid, [
          clubInfo.headicon.toString(),
          clubInfo.name,
          clubInfo.lvl.toString(),
          clubInfo.user_num + `/` + levelCfg.member_limit,
          clubInfo.clubid.toString(),
          clubInfo.grade.toString()
        ]);
        const tab = chatTo == cmd.CHAT_TO_TYPE.CTT_PLAYER ? 2 /* Private */ : 0 /* World */;
        GameNavigator.ins().gotoWithClose(1015 /* chat */, tab, toid);
      };
      if (chatTo == cmd.CHAT_TO_TYPE.CTT_WORLD) {
        ChatData.ins().startWorldInviteCD();
        success();
      } else {
        TipsManager.ins().showMessageBox({
          content: "是否邀请好友加入俱乐部？",
          callback_ok: () => {
            if (!isAttention && !SocialData.ins().isUserYourAttention(toid)) {
              console.log("isUserYourAttention", toid);
              TipsManager.ins().showMessageTips("该玩家不是你的粉丝");
              return;
            }
            ChatData.ins().addContact(toid);
            success();
          }
        });
      }
    }
  };

  // src/script/module/club/view/UIClubInviteView.ts
  var UIClubInviteView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/club/UIClubInviteView.lh";
    }
    onConstruct() {
      this.btn_diamond = this.elems.getUIButton("btn_diamond");
      this.btn_ad = this.elems.getUIButton("btn_ad");
      this.btn_social = this.elems.getUIButton("btn_social");
      this.addClickListener(this.elems.getElement("btn_x"), this.close);
      this.addClickListener(this.btn_diamond.rootNode, this.onClickDiamond);
      this.addClickListener(this.btn_ad.rootNode, this.onClickAd);
      this.addClickListener(this.btn_social.rootNode, this.onClickSocial);
    }
    onOpen() {
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const price = ClubData.ins().getWorldInviteCost();
      this.btn_diamond.setTitle(ThingUtils.getThingHtmlIconPath(1 /* DIAMOND */, 48, 48) + `×${price}`);
      this.btn_ad.setTitle(UIUtils.getHtmlPath(UIUtils.getImageUrl("media", "ui_qd_sp")) + `招募`);
    }
    onClickDiamond() {
      const price = ClubData.ins().getWorldInviteCost();
      const now = TimeData.ins().serverTimeS;
      if (ChatData.ins().worldInviteCDEndAt > now) {
        const seconds = Math.ceil(ChatData.ins().worldInviteCDEndAt - now);
        TipsManager.ins().showMessageTips(StringUtils.format(ChatConst.INVITE_TOOFAST_TIP, seconds));
        return;
      }
      if (ChatData.ins().worldChatCDEndAt > now) {
        TipsManager.ins().showMessageTips(ChatConst.CHAT_TOOFAST_TIP);
        return;
      }
      const doSuccess = () => {
        ShopManager.ins().costItemRequest(1 /* DIAMOND */, price, () => {
          ClubManager.ins().inviteAddClub(cmd.CHAT_TO_TYPE.CTT_WORLD, 0);
        });
      };
      if (ThingUtils.isEnough(1 /* DIAMOND */, price)) {
        doSuccess();
      } else {
        ShopManager.ins().showNoDiamondTips(10, doSuccess);
      }
    }
    onClickAd() {
      const now = TimeData.ins().serverTimeS;
      if (ChatData.ins().worldInviteCDEndAt > now) {
        const seconds = Math.ceil(ChatData.ins().worldInviteCDEndAt - now);
        TipsManager.ins().showMessageTips(StringUtils.format(ChatConst.INVITE_TOOFAST_TIP, seconds));
        return;
      }
      if (ChatData.ins().worldChatCDEndAt > now) {
        TipsManager.ins().showMessageTips(ChatConst.CHAT_TOOFAST_TIP);
        return;
      }
      let data = ClubData.ins().clubInfo;
      let clubLevelCfg = ClubData.ins().getClubLevelCfg(data.lvl);
      let jsoninfo = { "video_id": 2, "totype": cmd.CHAT_TO_TYPE.CTT_WORLD, "type": cmd.CHAT_TYPE.CLUB_INVITE, "toid": 0, "extra_param": [data.headicon.toString(), data.name, data.lvl.toString(), data.user_num + `/` + clubLevelCfg.member_limit, data.clubid.toString(), data.grade.toString()] };
      AdManager.ins().showAd({
        ad_id: 2,
        ext: JSON.stringify(jsoninfo),
        callback_succ_look: () => {
          ChatData.ins().startWorldInviteCD();
          GameNavigator.ins().gotoWithClose(1015 /* chat */, 0 /* World */, 0);
        }
      });
    }
    onClickSocial() {
      GameNavigator.ins().gotoWithClose(100301 /* friend */);
    }
  };

