  // src/script/module/club/view/UIClubMemberOpView.ts
  var UIClubMemberOpView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/club/UIClubMemberOpView.lh";
    }
    onConstruct() {
      this.listBg = this.elems.getElement("listBg");
      this.box = this.elems.getElement("box");
      this.btn_detail = this.elems.getElement("btn_detail");
      this.btn_appointVice = this.elems.getUIButton("btn_appointVice");
      this.btn_appointMinister = this.elems.getElement("btn_appointMinister");
      this.btn_kick = this.elems.getElement("btn_kick");
      this.addClickListener(this.view, this.close);
      this.addClickListener(this.btn_detail, this.onClickDetail);
      this.addClickListener(this.btn_appointVice.rootNode, this.onClickAppointVice);
      this.addClickListener(this.btn_appointMinister, this.onClickAppointMinister);
      this.addClickListener(this.btn_kick, this.onClickKick);
    }
    onOpen(targetWidget, offsetX, offsetY, data) {
      this._data = data;
      let point = UIUtils.convertPos(targetWidget, this.listBg);
      point.x += offsetX;
      point.y += offsetY;
      if (point.x + this.listBg.width > Laya.stage.designWidth) {
        point.x = Laya.stage.designWidth - this.listBg.width;
      } else if (point.x < 0) {
        point.x = 0;
      }
      if (point.y + this.listBg.height > Laya.stage.designHeight) {
        point.y = Laya.stage.designHeight - this.listBg.height;
      } else if (point.y < 0) {
        point.y = 0;
      }
      this.listBg.pos(point.x, point.y);
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const data = this._data;
      const clubMemberType = ClubData.ins().clubMemberType;
      if (clubMemberType == 1 /* Minister */) {
        this.btn_appointVice.setTitle(data.jur_lvl == 2 /* DeputyMinister */ ? "撤销职位" : "任命副部长");
        UIUtils.setActive(this.btn_appointVice.rootNode, true);
        UIUtils.setActive(this.btn_appointMinister, true);
        UIUtils.setActive(this.btn_kick, true);
      } else if (clubMemberType == 2 /* DeputyMinister */) {
        UIUtils.setActive(this.btn_appointVice.rootNode, false);
        UIUtils.setActive(this.btn_appointMinister, false);
        if (data.jur_lvl == 1 /* Minister */ || data.jur_lvl == 2 /* DeputyMinister */) {
          UIUtils.setActive(this.btn_kick, false);
        } else {
          UIUtils.setActive(this.btn_kick, true);
        }
      } else {
        UIUtils.setActive(this.btn_appointVice.rootNode, false);
        UIUtils.setActive(this.btn_appointMinister, false);
        UIUtils.setActive(this.btn_kick, false);
      }
      let activeNow = false;
      let lastLine;
      this.box.children.forEach((element) => {
        if (element.name == "line") {
          UIUtils.setActive(element, activeNow);
          if (activeNow) {
            lastLine = element;
          }
          activeNow = false;
        } else {
          activeNow = element.active;
          if (activeNow) {
            lastLine = null;
          }
        }
      });
      if (lastLine) {
        UIUtils.setActive(lastLine, false);
      }
      this.box.layout.refresh();
      this.listBg.height = this.box.layout.contentHeight + 15;
    }
    /**
     * 点击查看详情
     */
    onClickDetail() {
      this.close();
      PlayerManager.ins().openPersonalInfo(this._data.userid);
    }
    /**
     * 点击任命副部长
     */
    onClickAppointVice() {
      this.close();
      if (this._data.jur_lvl == 2 /* DeputyMinister */) {
        TipsManager.ins().showMessageBox({
          callback_ok: () => {
            ClubProtoUtils.club_set_position_tos(this._data.userid, 4 /* Normal */);
          },
          content: "是否撤销副部长职位"
        });
      } else {
        const clubInfo = ClubData.ins().clubInfo;
        const levelCfg = ClubData.ins().getClubLevelCfg(clubInfo.lvl);
        if (ClubData.ins().vice_minister_count >= levelCfg.secretary_limit) {
          TipsManager.ins().showMessageBox({
            title: "温馨提示",
            content: "副部长人数已满",
            visible_cancel: false
          });
        } else {
          TipsManager.ins().showMessageBox({
            title: "职位变更",
            content: "确定任命[" + this._data.nick + "]为[副部长]吗?\n(已任命" + ClubData.ins().vice_minister_count + "/" + levelCfg.secretary_limit + ")",
            callback_ok: () => {
              ClubProtoUtils.club_set_position_tos(this._data.userid, 2 /* DeputyMinister */);
            }
          });
        }
      }
    }
    /**
     * 点击任命部长
     */
    onClickAppointMinister() {
      this.close();
      TipsManager.ins().showMessageBox({
        content: "是否转让部长位置",
        callback_ok: () => {
          ClubProtoUtils.club_set_position_tos(this._data.userid, 1 /* Minister */);
        }
      });
    }
    /**
     * 点击踢出
     */
    onClickKick() {
      this.close();
      TipsManager.ins().showMessageBox({
        content: "是否剔除对应成员",
        callback_ok: () => {
          ClubProtoUtils.club_kick_out_tos(this._data.userid);
        }
      });
    }
  };

