  var ClubShopItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.img = ElemFinder.getElement(rootNode, "img");
      this.txt_name = ElemFinder.getText(rootNode, "img/txt_name");
      this.txt_limit = ElemFinder.getElement(rootNode, "img/txt_limit");
      this.itemIcon = new ItemIconCtrl(ElemFinder.getLoader(rootNode, "img/itemIcon"));
      this.itemIcon.setBgActive(false);
      this.btn_buy = ElemFinder.getUIButton(rootNode, "img/btn_buy");
      this.img_lock = ElemFinder.getElement(rootNode, "img_lock");
      this.txt_con_activity = ElemFinder.getElement(rootNode, "img_lock/txt_con_activity");
      this.txt_con_level = ElemFinder.getElement(rootNode, "img_lock/txt_con_level");
      UIUtils.addClickListener(this.btn_buy.rootNode, this, this.onClickBuy);
    }
    update(data, index, shopInfoList) {
      var _a;
      this.data = data;
      let shopInfo = shopInfoList.list.find((element) => {
        return element.shopid == data.id;
      });
      this.buycount = (_a = shopInfo == null ? void 0 : shopInfo.buycount) != null ? _a : 0;
      const itemId = data.item_id;
      const thingCfg = ThingData.ins().getThingConfig(itemId);
      this.txt_name.text = LangData.ins().getLang(thingCfg.name);
      this.itemIcon.update(itemId);
      this.txt_limit.text = `限购：${UIUtils.getColorText(`${this.buycount}/${data.limit_number}`, this.buycount >= this.data.limit_number ? ColorUtils.COLOR_WHITE : "#FFE430")}`;
      let locked = false;
      this.txt_con_level.text = "俱乐部达到" + data.level_limit + "级";
      if (data.level_limit > shopInfoList.clublvl) {
        locked = true;
        this.txt_con_level.color = "#dfdfe0";
      } else {
        this.txt_con_level.color = ColorUtils.COLOR_GREEN;
      }
      this.txt_con_activity.text = data.active_limit + "累计活跃度";
      if (data.active_limit > ClubData.ins().clubInfo.activity) {
        locked = true;
        this.txt_con_activity.color = "#dfdfe0";
      } else {
        this.txt_con_activity.color = ColorUtils.COLOR_GREEN;
      }
      if (this.buycount >= this.data.limit_number) {
        this.btn_buy.grayed = true;
      } else {
        this.btn_buy.grayed = false;
      }
      this.btn_buy.setTitle(ThingUtils.getThingHtmlIconPath(8 /* CLUBACTIVITY */, 48, 48) + `×${data.price}`);
      UIUtils.setActive(this.img_lock, locked);
    }
    onClickBuy() {
      if (this.buycount >= this.data.limit_number) {
        TipsManager.ins().showMessageTips("本周购买已达上限！周六刷新");
        return;
      }
      ShopManager.ins().buyCustomItem({
        itemId: this.data.item_id,
        price: this.data.price,
        buyTimes: this.buycount,
        limitTimes: this.data.limit_number,
        currencyId: 8 /* CLUBACTIVITY */,
        buyCallback: (day, num) => {
          ClubProtoUtils.club_buy_item_tos(this.data.id, num);
        }
      });
    }
  };

