          const clockGot = ClubData.ins().clubInfo.clock_in_tag == 1;
          this.btn_reward.setVisible(!clockGot);
          this.btn_reward.setRedDotVisible(true);
          this.btn_go.setVisible(false);
          this.btn_got.setVisible(clockGot);
          this.btn_reward.setTitle("打卡");
