  // src/script/module/main/funcEntry/base/BaseFuncsContainer.ts
  var BaseFuncsContainer = class {
    constructor() {
      /**
       * 控制器列表
       */
      this._ctrls = [];
      /**
       * 功能id映射
       */
      this._ctrlMap = {};
    }
    /**
     * 初始化容器
     * @param elems 节点容器
     * @param clonePrefab 默认复制模板
     * @param pos 关联控制器位置，与表格关联
     */
    setView(elems, clonePrefab, pos) {
      this._elems = elems;
      this._root = elems.root;
      this._clonePrefab = clonePrefab;
      UIUtils.setActive(clonePrefab, false);
      const entryList = FuncEntryManager.ins().getEntryList(pos);
      entryList.sort((a, b) => a.data.cfg.order - b.data.cfg.order);
      for (const entry of entryList) {
        this.addCtrl(entry);
      }
    }
    /**
     * 添加一个UI节点与ctrl的绑定
     * @param ctrl ctrl
     */
    addCtrl(ctrl) {
      let renderer = new (ctrl.rendererClass || DefaultItemRenderer)();
      let goGetSet = null;
      if (ctrl.uiName) {
        goGetSet = this._elems.getElement(ctrl.uiName);
      } else {
        goGetSet = UIUtils.instantiateUINode(this._clonePrefab);
        this._root.addChild(goGetSet);
      }
      renderer.bindCtrl(goGetSet, ctrl);
      ctrl._bind(renderer, this);
      this._ctrls.push(ctrl);
      this._ctrlMap[ctrl.data.id] = ctrl;
    }
    /**
     * 更新容器显示状态
     */
    update() {
      this.isDirty = false;
      for (let ctrl of this._ctrls) {
        let funcShow = FuncLimitUtils.isFuncAvailable(ctrl.data.id);
        if (funcShow) {
          ctrl.data.state = ctrl.checkStatus();
          if (2 /* Invisible */ == ctrl.data.state) {
            ctrl.setActive(false);
            continue;
          }
          ctrl.updateRedDot();
          ctrl.setActive(true);
        } else {
          ctrl.data.state = 2 /* Invisible */;
          ctrl.setActive(false);
        }
      }
      this.updateTime();
      this.onLayoutChange();
    }
    /**
     * 更新容器红点
     */
    updateRedDots() {
      for (let ctrl of this._ctrls) {
        if (ctrl.actived) {
          ctrl.updateRedDot();
        }
      }
    }
    /**
     * 更新容器时间相关
     */
    updateTime() {
      let now = TimeData.ins().serverTimeS;
      for (let ctrl of this._ctrls) {
        if (ctrl.actived) {
          if (ctrl.data.activityId > 0 || ctrl.data.startTime > 0 || ctrl.data.hasTimer) {
            ctrl.onUpdateTime(now);
          }
        }
      }
    }
    /**
     * 容器内容物变化调用
     */
    onLayoutChange() {
      if (this._layoutChangeHandler) {
        this._layoutChangeHandler();
      }
    }
    /**
     * 当前容器内入口总数（已绑定ctrl数量）
     */
    getCtrlCount() {
      return this._ctrls.length;
    }
    /**
     * 当前容器内可见入口数量（active状态）
     */
    getActivedCtrlCount() {
      let count = 0;
      for (const ctrl of this._ctrls) {
        if (ctrl.actived) {
          count++;
        }
      }
      return count;
    }
    /**
     * 设置入口布局个数变化回调（入口显示数量有变化后触发）
     */
    setLayoutChangeHandler(handler) {
      this._layoutChangeHandler = handler;
    }
  };

