  // src/script/module/table/utils/TableUtils.ts
  var TableUtils = class {
    /**
     * 获取3d球桌资源路径
     * @param tableId 球桌id
     * @returns 
     */
    static GetTableModelPath(tableId, ruleset) {
      let tableCfg = ConfigUtil.Tables.item.get(tableId);
      if (!tableCfg) {
        return null;
      }
      let tableName = tableCfg.model;
      if (ruleset == 2 /* SNKBall */) {
        tableName = tableCfg.model + "_SNK";
      }
      return `u3d/Assets/prefab/table/${tableName}.lh`;
    }
  };

  // src/script/module/qipai/QiPaiManager.ts
  var QiPaiManager = class extends BaseClass {
    getSkinPath(iconName, ext = "png") {
      return UIUtils.getImageUrl("qipai", iconName, ext);
      ;
    }
    getCardSkin(data) {
      let str = ``;
      if (data.value <= 13) {
        switch (data.suit) {
          case cmd.CARD_TYPE.SPADE:
            str = `ui_icon_qp_ht8`;
            break;
          case cmd.CARD_TYPE.HEART:
            str = `ui_icon_qp_hx8`;
            break;
          case cmd.CARD_TYPE.CLUBS:
            str = `ui_icon_qp_mh8`;
            break;
          case cmd.CARD_TYPE.DIAMOND:
            str = `ui_icon_qp_fk8`;
            break;
        }
      } else {
        str = `ui_icon_qp_wn`;
      }
      return this.getSkinPath(str);
    }
    getRankBg(rank2) {
      let str = ``;
      switch (rank2) {
        case 1:
          str = "ui_icon_wq_pmdb01";
          break;
        case 2:
          str = "ui_icon_wq_pmdb02";
          break;
        case 3:
          str = "ui_icon_wq_pmdb03";
          break;
        case 4:
          str = "ui_icon_wq_pmdb03";
          break;
        case 5:
          str = "ui_icon_wq_pmdb04";
          break;
      }
      return this.getSkinPath(str);
    }
    getRankStr(rank2) {
      switch (rank2) {
        case 1:
          return "头游";
        case 2:
          return "二游";
        case 3:
          return "三游";
        case 4:
          return "四游";
        case 5:
          return "五游";
      }
    }
    getNameByPos(pos, selfPos) {
      const offset = (pos - selfPos + 5) % 5;
      const relation = ["", "下家", "下下家", "上上家", "上家"];
      return relation[offset] || "";
    }
    updateBg(img_bg, isHor) {
      if (isHor) {
        img_bg.src = "ui/atlas/common/bg/newbg/ui_bg_nwdy_base02.png";
        let h = 1560;
        img_bg.width = h;
        img_bg.height = 720;
        img_bg.rotation = -90;
        img_bg.x = 0;
        img_bg.y = h - (h - img_bg.parent.height) * 0.5;
      } else {
        img_bg.src = "ui/atlas/common/bg/newbg/ui_bj_wqbp_zjm.png";
        let h = 1660;
        img_bg.width = 720;
        img_bg.height = h;
        img_bg.rotation = 0;
        img_bg.x = 0;
        img_bg.y = img_bg.parent.height - h;
      }
    }
  };
  QiPaiManager.isTest = false;
  window["QiPaiManager"] = QiPaiManager;

