  // src/script/module/chat/chatPanel/ctrls/ChatMultiEmoCtrl.ts
  var ChatMultiEmoCtrl = class extends ListItemCtrl {
    constructor() {
      super();
    }
    setComponents(rootNode, index, ...args) {
      this.img_ten = ElemFinder.getElement(rootNode, "img_ten");
      this.img_coin = ElemFinder.getElement(rootNode, "box_cost/img_coin");
      this.lb_cost = ElemFinder.getElement(rootNode, "box_cost/lb_cost");
      this.lb_des = ElemFinder.getElement(rootNode, "lb_des");
      this.img_emo = ElemFinder.getElement(rootNode, "img_emo");
    }
    update(data, index) {
      this.index = index;
      this._data = data;
      this._configVip = ConfigUtil.Tables.vip.get(PlayerData.ins().vip);
      let type = Math.floor(this._data.expression_id / 100);
      this._num = ThingData.ins().getThingNum(this._data.expression_id);
      this.img_ten.visible = this._data.playNum == 10;
      this.img_emo.src = ChatUtils.getEmojiPath(data.icon);
      if (this._num > 0) {
        this.img_coin.visible = false;
        this.lb_cost.visible = false;
        this.lb_des.visible = true;
        if (this._num > 999) {
          this.lb_des.text = "拥有999+";
        } else {
          this.lb_des.text = "拥有" + this._num + "个";
        }
      } else {
        this.lb_des.visible = false;
        if (this._data.type_cost === 0) {
          this.img_coin.visible = false;
          this.lb_cost.visible = false;
        } else if (this._data.type_cost === 2) {
          this.img_coin.visible = true;
          this.img_coin.src = ThingUtils.getThingIconPath(2 /* COIN */);
          this.lb_cost.visible = true;
          this.lb_cost.text = data.cost + "";
        } else if (this._data.type_cost === 1) {
          this.img_coin.visible = true;
          this.img_coin.src = ThingUtils.getThingIconPath(1 /* DIAMOND */);
          this.lb_cost.visible = true;
          this.lb_cost.text = data.cost + "";
        }
      }
    }
    sendMsg(type, msg) {
      let msgToSend = msg;
      let sendMsg = new cmd.g_chat_in_room_c2s();
      sendMsg.content = msgToSend;
      sendMsg.type = type;
      let data = {
        fromId: PlayerData.ins().playerId,
        toId: PersonalInfoData.ins().personalInfo_data.userid
      };
      sendMsg.data = JSON.stringify(data);
      NetService.send(sendMsg);
      UIManager.ins().closeForm(UIChatMultiView);
    }
    onClick(e) {
      const roomInfo = PoolGameRoomData.ins().getRoomInfo();
      if (roomInfo == null)
        return;
      let type = 3;
      if (this._num > 0) {
        if (type === 1) {
          this.sendMsg(type, this._data.expression_id.toString());
        } else if (type === 2 || type === 3) {
          if (PlayerData.ins().playerId === roomInfo.creator && roomInfo.room_type == 3 /* PvpMatch */) {
            TipsManager.ins().showMessageTips(`房主不支持发此表情`);
            return;
          }
          if (this._data.type_cost === 0) {
            this.sendMsg(3, this._data.expression_id.toString());
          } else if (this._data.type_cost === 2) {
            this.sendMsg(3, this._data.expression_id.toString());
          } else if (this._data.type_cost === 1) {
            this.sendMsg(3, this._data.expression_id.toString());
          } else if (this._data.type_cost === 6) {
            this.sendMsg(3, this._data.expression_id.toString());
          }
        }
      } else {
        if (type === 1) {
          if (this._data.type_cost === 3 && !SubscribeData.ins().isSubscribed) {
            let cfg = ConfigUtil.Tables.chat_expression.get(this._data.expression_id);
            return;
          }
          if (this._data.type_cost === 6 && !SubscribeData.ins().isSuper) {
            return;
          }
          this.sendMsg(type, this._data.expression_id.toString());
        } else if (type === 2 || type === 3) {
          if (PlayerData.ins().playerId === roomInfo.creator && roomInfo.room_type == 3 /* PvpMatch */) {
            TipsManager.ins().showMessageTips(`房主不支持发此表情`);
            return;
          }
          if (this._data.type_cost === 6 && !SubscribeData.ins().isSuper) {
            return;
          }
          if (this._data.type_cost === 0 || this._data.type_cost === 6) {
            this.sendMsg(3, this._data.expression_id.toString());
          } else if (this._data.type_cost === 2) {
            if (!CurrencyData.ins().isEnough(2 /* COIN */, Math.ceil(this._data.cost))) {
              UIManager.ins().openForm(UIRechargeView, 1);
            } else {
              this.sendMsg(3, this._data.expression_id.toString());
            }
          } else if (this._data.type_cost === 1) {
            if (!CurrencyData.ins().isEnough(1 /* DIAMOND */, Math.ceil(this._data.cost))) {
              UIManager.ins().openForm(UIRechargeView, 0);
            } else {
              this.sendMsg(3, this._data.expression_id.toString());
            }
          }
        }
      }
    }
  };

