      const letters = [];
      const fontSize = 32;
      for (let i = 0, len = fullText.length; i < len; i++) {
        const letter = this.createLetter(fullText.charAt(i));
        letters.push(letter);
        totalWidth += letter.width > 0 ? letter.width : fontSize;
      }
      if (totalWidth <= 0)
        totalWidth = fullText.length * fontSize;
