  // src/script/module/main/utils/LinkUtils.ts
  var LinkUtils = class {
    /**
     * 获取链接
     * @param text 文本
     * @param linkList 链接列表
     * @returns 链接
     */
    static getLink(text, linkList) {
      if (!linkList || linkList.length === 0) {
        return text;
      }
      const linkStrList = [];
      for (const link of linkList) {
        let linkStr = "";
        switch (link.type) {
          case 1:
            linkStr = link.val;
            break;
          case 2:
            linkStr = ThingUtils.getThingName(Number(link.val));
            break;
          default:
            linkStr = link.val || "";
            break;
        }
        linkStrList.push(linkStr);
      }
      return StringUtils.format(text, ...linkStrList);
    }
  };

  // src/script/module/chat/chatPanel/ctrls/ChatSystemTextCtrl.ts
  var ChatSystemTextCtrl = class extends ChatCtrlBase {
    onConstruct() {
      this.txt_content = ElemFinder.getElement(this.rootNode, "txt_content");
    }
    onUpdate(msg) {
      this.rootNode.x = this.panelWidth / 2;
      if (StringUtils.isNullOrEmpty(msg.context)) {
        let cfgId = parseInt(msg.extra_param[0]);
        let config = ClubData.ins().getClubNews(cfgId);
        let str = LangData.ins().getLang(config == null ? void 0 : config.news_name) || "";
        let linkJson = [];
        for (let i = 1; i < msg.extra_param.length; i++) {
          try {
            let linkParam = JSON.parse(msg.extra_param[i]);
            linkJson.push({
              type: Number(linkParam.type),
              val: String(linkParam.val)
            });
          } catch (error) {
            console.error(error);
          }
        }
        let linkStr = LinkUtils.getLink(str, linkJson);
        if (config && config.news_type === 0) {
          this.txt_content.color = "#ffef48";
        } else {
          this.txt_content.color = "#FFFFFF";
        }
        this.txt_content.text = str;
      } else {
        this.txt_content.text = msg.context;
        this.txt_content.color = "#FFFFFF";
      }
      this.rootNode.height = this.txt_content.textHeight + 16;
    }
  };

