  // src/script/module/chat/chatPanel/ChatPanelCtrl.ts
  var ChatPanelCtrl = class {
    constructor(panel, content, unreadBtn, creator) {
      /**
       * 触发缓存的大小阈值
       */
      this.CACHE_TRIGGER_SIZE = 20;
      /**
       * 当前渲染显示的聊天列表
       * 渲染聊天列表对象要大于缓存本身，但是也会到极限处进行限制
       */
      this._renderMsgList = [];
      /**
       * 当前渲染的ctrl
       */
      this._renderCtrls = [];
      /**
       * 未读消息列表
       */
      this._unreadMsgList = [];
      /**
       * 聊天对象高度
       * 默认从下向上创建，只增不减
       */
      this._contentHeight = 0;
      /**
       * 是否滑动到尽头
       */
      this._scrollHead = false;
      this._panel = panel;
      this._defaultPanelWidth = panel.width;
      this._defaultPanelX = panel.x;
      this._defaultPanelY = panel.y;
      this._defaultPanelHeight = panel.height;
      this._chatContent = content;
      this._unreadBtn = unreadBtn;
      this._creator = creator;
      panel.scroller.owner.on(Laya.UIEvent.Scroll, this, this.onScroll);
      UIUtils.addClickListener(unreadBtn.rootNode, this, this.onClickUnreadBtn);
    }
    /**
     * 当前消息数量
     */
    get msgNum() {
      return this._renderMsgList.length;
    }
    /**
     * 点击新消息提示
     */
    onClickUnreadBtn() {
      const headCtrl = this._renderCtrls.length > 0 ? this._renderCtrls[0] : null;
      if (!headCtrl) {
        return;
      }
      this.build(Array.from(this._renderMsgList), this._totype, this._toid, false);
    }
    /**
     * 更新未读消息按钮
     */
    updateUnreadBtn() {
      const len = this._unreadMsgList.length;
      if (len > 0) {
        this._unreadBtn.setVisible(true);
        this._unreadBtn.setTitle(`${len}条新消息`);
      } else {
        this._unreadBtn.setVisible(false);
      }
    }
    /**
     * 清理
     */
    clear() {
      for (let i = 0, len = this._renderCtrls.length; i < len; i++) {
        this._renderCtrls[i].recover();
      }
      this._renderCtrls.length = 0;
      this._renderMsgList.length = 0;
      this._unreadMsgList.length = 0;
    }
    /**
     * 界面打开首次构造面板
     * @param msgList 消息列表 
     * @param totype 聊天类型
     * @param toid 聊天对象id
     * @param isNew 是否是新构建
     */
    build(msgList, totype, toid, isNew = true) {
      this._totype = totype;
      this._toid = toid;
      ChatPageManager.ins().toid = toid;
      ChatPageManager.ins().totype = totype;
      this.clear();
      if (!msgList) {
        msgList = [];
      }
      if (msgList.length > 0) {
        for (const msg of msgList) {
          if (this.isSupportMsg(msg)) {
            this._renderMsgList.push(msg);
          }
        }
      }
      if (isNew) {
        this.addSystemTips();
      }
      this._contentHeight = 5e5;
      this._chatContent.height = this._contentHeight;
      this._chatContent.pos(0, 0);
      this._scrollHead = false;
      const initSize = Math.min(this._renderMsgList.length, 10);
      if (initSize > 0) {
        for (let i = 0; i < initSize; i++) {
          const msg = this._renderMsgList[this._renderMsgList.length - 1 - i];
          this._addChatMsgToPanel(msg, false);
        }
      }
      this.updateUnreadBtn();
      this._panel.scroller.scrollBottom();
      this.onScroll();
    }
    /**
     * 检查旧消息，触发额外滚动内容
     */
    updateMsgList(msgList) {
      if (!msgList) {
        msgList = [];
      }
      this._renderMsgList = [];
      if (msgList.length > 0) {
        for (const msg of msgList) {
          if (this.isSupportMsg(msg)) {
            this._renderMsgList.push(msg);
          }
        }
      }
      this.addSystemTips();
      this._scrollHead = false;
      this.fixScrollValue(0);
      this.onScroll();
    }
    /**
     * 更新俱乐部信息
     */
    updateClubInfo() {
      for (const ctrl of this._renderCtrls) {
        if (ctrl instanceof ChatPlayerCtrl) {
          ctrl.updateClubPos(false);
        }
      }
    }
    /**
     * 更新房间信息
     */
    updateRoomInfo() {
      for (const ctrl of this._renderCtrls) {
        if (ctrl instanceof ChatPlayerCtrl) {
          ctrl.updateRoomInfo();
        }
      }
    }
    /**
    * 更新头像信息
    */
    updateHeadInfo() {
      for (const ctrl of this._renderCtrls) {
        if (ctrl instanceof ChatPlayerCtrl) {
          ctrl.updateHead();
        }
      }
    }
    /**
     * 更新红包信息
     */
    updateRedPacketInfo(packet_id) {
      for (const ctrl of this._renderCtrls) {
        if (ctrl instanceof ChatPlayerCtrl) {
          ctrl.updateRedPacket(packet_id);
        }
      }
    }
    /**
     * 添加一条系统提示消息
     */
    addSystemTips() {
      if (this._totype == cmd.CHAT_TO_TYPE.CTT_WORLD || this._totype == cmd.CHAT_TO_TYPE.CTT_REGION) {
        if (this._renderMsgList.length > 0) {
          this._renderMsgList.splice(this._renderMsgList.length - 1, 0, ChatData.ins().getSystemTipMessage(this._totype));
        } else {
          this._renderMsgList.push(ChatData.ins().getSystemTipMessage(this._totype));
        }
      } else {
        if (this._renderMsgList.length > 0) {
          this._renderMsgList.push(ChatData.ins().getSystemTipMessage(this._totype));
        }
      }
    }
    /**
     * 修复当前滚动值
     * @param tailPosY 目标起始点
     */
    fixScrollValue(tailPosY) {
      const offset = this._chatContent.y + tailPosY;
      if (offset < 0) {
        return;
      }
      this._chatContent.y = -tailPosY;
      this._panel.scroller._beginTouchPos.y -= offset;
      this._panel.scroller.posY -= offset;
    }
    /**
     * 滚动时触发
     */
    onScroll() {
      let posY = this._panel.scroller.posY - this._chatContent.y;
      const headCtrl = this._renderCtrls.length > 0 ? this._renderCtrls[0] : null;
      const tailCtrl = this._renderCtrls.length > 0 ? this._renderCtrls[this._renderCtrls.length - 1] : null;
      const tailPosY = tailCtrl ? tailCtrl.rootNode.y : this._contentHeight;
      if (this._renderCtrls.length > 0) {
        const headPosY = headCtrl ? headCtrl.rootNode.y + headCtrl.rootNode.height : this._contentHeight;
        if (posY - tailPosY < 100) {
          const tailIndex = this._renderMsgList.indexOf(tailCtrl.msg);
          if (tailIndex > -1) {
            const nextSize = Math.min(tailIndex, 10);
            if (nextSize > 0) {
              if (this._renderCtrls.length > this.CACHE_TRIGGER_SIZE + nextSize) {
                for (let i = 0; i < nextSize; i++) {
                  this._renderCtrls[i].recover();
                }
                this._renderCtrls.splice(0, nextSize);
              }
              for (let i = 0; i < nextSize; i++) {
                this._addChatMsgToPanel(this._renderMsgList[tailIndex - (i + 1)], false);
              }
            }
          }
        } else if (headPosY - (posY + this._panel.height) < 100) {
          const nowIndex = this._renderMsgList.indexOf(headCtrl.msg);
          if (nowIndex > -1) {
            const nextSize = Math.min(this._renderMsgList.length - nowIndex - 1, 10);
            if (nextSize > 0) {
              if (this._renderCtrls.length > this.CACHE_TRIGGER_SIZE + nextSize) {
                for (let i = 0; i < nextSize; i++) {
                  this._renderCtrls[this._renderCtrls.length - i - 1].recover();
                }
                this._renderCtrls.splice(this._renderCtrls.length - nextSize, nextSize);
              }
              for (let i = 0; i < nextSize; i++) {
                this._addChatMsgToPanel(this._renderMsgList[nowIndex + (i + 1)], true);
              }
              return;
            }
          }
        }
      }
      if (!this._scrollHead && this._panel.scroller.posY <= tailPosY && (tailCtrl == null ? void 0 : tailCtrl.msg) == this._renderMsgList[0]) {
        this._scrollHead = true;
        this.fixScrollValue(tailPosY);
        posY = this._panel.scroller.posY - this._chatContent.y;
      }
      for (const ctrl of this._renderCtrls) {
        if (ctrl.rootNode.y + ctrl.rootNode.height < posY || ctrl.rootNode.y > posY + this._panel.height) {
          ctrl.setVisible(false);
        } else {
          ctrl.setVisible(true);
        }
      }
    }
    /**
     * 设置面板左侧偏移
     * @param offset 偏移量
     */
    setLeftOffset(offset) {
      this._offset = offset;
      this._panel.x = this._defaultPanelX + offset;
      this._panel.width = this._defaultPanelWidth - offset;
    }
    /**
     * 设置面板上侧偏移
     * @param offset 偏移量
     */
    setTopOffset(offset) {
      this._panel.y = this._defaultPanelY + offset;
      this._panel.height = this._defaultPanelHeight - offset;
    }
    /**
     * 添加聊天元素
     */
    addNewChatMsg(msg) {
      if (!this.isSupportMsg(msg)) {
        return;
      }
      if (this._panel.scroller.isBottomMost) {
        const success = this._addChatMsgToPanel(msg, true);
        if (!success) {
          return;
        }
        if (this._renderCtrls.length > this.CACHE_TRIGGER_SIZE + 1) {
          this._renderCtrls[this._renderCtrls.length - 1].recover();
          this._renderCtrls.splice(this._renderCtrls.length - 1, 1);
        }
        this._renderMsgList.push(msg);
        this._unreadMsgList.length = 0;
        this.updateUnreadBtn();
        this._panel.scroller.scrollBottom();
      } else {
        this._renderMsgList.push(msg);
        this._unreadMsgList.push(msg);
        this.updateUnreadBtn();
      }
      if (this._renderMsgList.length > ChatConst.MAX_CHAT_SHOW_LEN) {
        const removed = this._renderMsgList.splice(0, 1)[0];
        if (removed == this._renderCtrls[this._renderCtrls.length - 1].msg) {
          this._renderCtrls[this._renderCtrls.length - 1].recover();
          this._renderCtrls.splice(this._renderCtrls.length - 1, 1);
          this._scrollHead = false;
          this.onScroll();
        }
      }
    }
    isSupportMsg(msg) {
      switch (msg.type) {
        case cmd.CHAT_TYPE.TEXT:
        case cmd.CHAT_TYPE.LOUDSPEAKER:
        case cmd.CHAT_TYPE.EMOJI:
        case cmd.CHAT_TYPE.TIME:
        case cmd.CHAT_TYPE.SYSTEM:
        case cmd.CHAT_TYPE.CLUB_INVITE:
        case cmd.CHAT_TYPE.FROOM_INVITE:
        case cmd.CHAT_TYPE.CHARGE_REDPACKAGE:
          return true;
        default:
          console.warn("未处理消息：" + JSON.stringify(msg));
          return false;
      }
    }
    /**
     * 添加聊天元素到显示面板
     * @param next 是否向后创建 true = 新聊天，false = 聊天记录
     */
    _addChatMsgToPanel(msg, next) {
      let ctrl;
      switch (msg.type) {
        case cmd.CHAT_TYPE.TEXT:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatPlayerTextCtrl());
            ctrl = playerCtrl;
          }
          break;
        case cmd.CHAT_TYPE.LOUDSPEAKER:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatSpeakerTextCtrl());
            ctrl = playerCtrl;
          }
          break;
        case cmd.CHAT_TYPE.EMOJI:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatPlayerEmojiCtrl());
            ctrl = playerCtrl;
          }
          break;
        case cmd.CHAT_TYPE.TIME:
          {
            ctrl = this._creator.createChatTimeTextCtrl();
          }
          break;
        case cmd.CHAT_TYPE.SYSTEM:
          {
            ctrl = this._creator.createChatSystemTextCtrl();
          }
          break;
        case cmd.CHAT_TYPE.CLUB_INVITE:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatClubInviteCtrl());
            ctrl = playerCtrl;
          }
          break;
        case cmd.CHAT_TYPE.FROOM_INVITE:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatRoomInviteCtrl());
            ctrl = playerCtrl;
          }
          break;
        case cmd.CHAT_TYPE.CHARGE_REDPACKAGE:
          {
            let playerCtrl = this._creator.createChatPlayerCtrl();
            playerCtrl.addSubCtrl(this._creator.createChatRedPacketCtrl());
            ctrl = playerCtrl;
          }
          break;
        default:
          console.log("未处理消息 ：" + JSON.stringify(msg));
          break;
      }
      if (!ctrl) {
        return false;
      }
      ctrl.update(msg, this._offset, this._panel.width);
      this._chatContent.addChild(ctrl.rootNode);
      ctrl.setVisible(true);
      if (next) {
        const headCtrl = this._renderCtrls.length > 0 ? this._renderCtrls[0] : null;
        const yNow = headCtrl ? headCtrl.rootNode.y + headCtrl.rootNode.height : this._contentHeight;
        ctrl.rootNode.y = yNow;
        const addedHeight = ctrl.rootNode.height;
        this._contentHeight = yNow + addedHeight;
        this._chatContent.height = this._contentHeight;
        this._renderCtrls.unshift(ctrl);
      } else {
        const tailCtrl = this._renderCtrls.length > 0 ? this._renderCtrls[this._renderCtrls.length - 1] : null;
        const yNow = tailCtrl ? tailCtrl.rootNode.y : this._contentHeight;
        ctrl.rootNode.y = yNow - ctrl.rootNode.height;
        this._renderCtrls.push(ctrl);
        const nowRenderAt = this._renderMsgList.indexOf(ctrl.msg);
        if (nowRenderAt <= 3 && (this._totype == cmd.CHAT_TO_TYPE.CTT_PLAYER || this._totype == cmd.CHAT_TO_TYPE.CTT_CLUB)) {
          ChatPageManager.ins().msgid = this._renderMsgList[0].msgid;
          ChatPageManager.ins().chatPage.tryNextPage();
        }
      }
      const unreadIndex = this._unreadMsgList.indexOf(msg);
      if (unreadIndex > -1) {
        this._unreadMsgList.splice(unreadIndex, 1);
        this.updateUnreadBtn();
      }
      return true;
    }
  };

