  var ChatRoomListItemCtrl = class extends ListItemCtrl {
    constructor() {
      super(...arguments);
      // 能否进入房间
      this._canEnterRoom = false;
    }
    setComponents(rootNode, index, ...args) {
      this.headItem = new HeadIconCtrl(ElemFinder.getElement(this.rootNode, "headItem"));
      this.txt_name = ElemFinder.getElement(rootNode, "txt_name");
      this.txt_desc = ElemFinder.getElement(rootNode, "txt_desc");
      this.txt_link = ElemFinder.getElement(rootNode, "txt_link");
      this.txt_memberCnt = ElemFinder.getElement(rootNode, "txt_memberCnt");
      this.img_null = ElemFinder.getElement(rootNode, "img_null");
      UIUtils.addClickListener(ElemFinder.getElement(rootNode, "bg"), this, this.onClickInfo);
    }
    update(data, index, ...args) {
      var _a, _b;
      this.data = data;
      if (data.extra_param.length === 0) {
        return;
      }
      this._roomId = parseInt(data.extra_param[0]);
      const roomType = parseInt(data.extra_param[1]);
      const ruleId = parseInt(data.extra_param[2]);
      const ruleCfg = PoolGameFriendRoomData.ins().getModeCfg(ruleId);
      const modeCfg = PoolGameRoomData.ins().getGameModeCfg(ruleCfg == null ? void 0 : ruleCfg.mode);
      const playerInfo = PlayerManager.ins().getSimplePlayerInfo(data.fromid);
      if (!playerInfo) {
        UIUtils.setActive(this.headItem.rootNode, false);
        PlayerManager.ins().requestSimplePlayerInfo(data.fromid);
      } else {
        this.headItem.update(playerInfo.head_icon, playerInfo.head_frame, playerInfo.sex, 0, (_a = playerInfo.vip_lvl) != null ? _a : 0);
      }
      if (ruleCfg && modeCfg) {
        this.txt_name.text = `${data.fromnick} 的房间`;
        this.txt_desc.text = `${LangData.ins().getLang(modeCfg.mode_name)}-${LangData.ins().getLang(ruleCfg.rule_name)}`;
      } else {
        this.txt_name.text = "";
        this.txt_desc.text = "";
      }
      const roomInfo = PoolGameRoomManager.ins().getRoomCountInfo(this._roomId);
      if (roomInfo) {
        if (roomInfo.count === 1 || roomInfo.count === 2 && roomInfo.inroom) {
          this._canEnterRoom = true;
          this.txt_link.text = "进入房间";
          this.txt_link.color = "#3681cc";
          this.txt_link.underline = true;
        } else {
          this._canEnterRoom = false;
          this.txt_link.text = "房间已开始或已解散";
          this.txt_link.color = "#AAB5D2";
          this.txt_link.underline = false;
        }
      } else {
        this._canEnterRoom = false;
        this.txt_link.text = "";
      }
      this.txt_memberCnt.text = `${(_b = roomInfo == null ? void 0 : roomInfo.count) != null ? _b : 0}/2`;
    }
    /**
     * 点击查看详情
     */
    onClickInfo() {
      if (this._canEnterRoom) {
        PoolGameRoomManager.ins().tryEnterRoom(this._roomId, this.data.fromnick);
      } else {
        TipsManager.ins().showMessageTips(`房间已开始或已解散`);
      }
    }
  };

  // src/script/module/chat/view/UIChatSendRedPakView.ts
  var UIChatSendRedPakView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      this.btn_numZS = [];
      this.defaultNum = 3;
      this.num = 3;
      this.maxNum = 60;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/chat/UIChatSendRedPakView.lh";
    }
    onConstruct() {
      for (let i = 1; i < 5; i++) {
        this.btn_numZS.push(this.elems.getWidget("btn_numZS" + i));
      }
      for (let i = 0; i < 4; i++) {
        this.addClickListener(this.btn_numZS[i], this.onClickNumZS, SoundID.SYS_BTNCLICK, i);
      }
      const rpList = ConfigUtil.Tables.recharge_rp.getDataList();
      for (let i = 0; i < 4; i++) {
        const txtDiamondNum = ElemFinder.getText(this.btn_numZS[i], "txt_diamondnum");
        const rpCfg = rpList[i];
        if (txtDiamondNum && rpCfg) {
          txtDiamondNum.text = rpCfg.num.toString();
        }
      }
      this.addClickListener(this.elems.getImage("btn_x"), this.close);
      this.addClickListener(this.elems.getImage("btn_add"), this.onClickNum, SoundID.SYS_BTNCLICK, 0);
      this.addClickListener(this.elems.getImage("btn_sub"), this.onClickNum, SoundID.SYS_BTNCLICK, 1);
      this.addClickListener(this.elems.getImage("btn_send"), this.onClickSend, SoundID.SYS_BTNCLICK);
      this.input_msg = this.elems.getTextInput("input_msg");
      this.txt_num = this.elems.getTextInput("txt_num");
      this.txt_price = this.elems.getText("txt_price");
      this.minNum = ConfigUtil.Tables.comm_config.get(238).int_value;
      if (this.txt_num && this.txt_num.textIns) {
        this.txt_num.textIns.on(Laya.Event.INPUT, this, this.onNumInput);
        this.txt_num.textIns.on(Laya.Event.BLUR, this, this.onNumInput);
        this.txt_num.textIns.on(Laya.Event.ENTER, this, this.onNumInput);
      }
    }
    onOpen(data, playerId) {
      this._data = data;
      this._playerId = playerId;
      this.onClickNumZS(0);
    }
    onClose() {
    }
    updateView() {
    }
    onClickNumZS(index) {
      UIUtils.setNodeCtrlStatus(this.btn_numZS[index], 1);
      for (let i = 0; i < 4; i++) {
        if (i != index)
          UIUtils.setNodeCtrlStatus(this.btn_numZS[i], 0);
      }
      this.num = this.defaultNum;
      this.txt_num.text = this.num.toString();
      const rpList = ConfigUtil.Tables.recharge_rp.getDataList();
      const rpCfg = rpList[index];
      if (rpCfg) {
        this.gift = ConfigUtil.Tables.charge_new.get(rpCfg.recharge_id);
        this.maxNum = rpCfg.num;
      }
      this.updatePrice();
    }
    updatePrice() {
      if (this.txt_price) {
        this.txt_price.text = `￥${this.gift.currency_ch}`;
      }
    }
    onNumInput() {
      let val = parseInt(this.txt_num.text);
      if (isNaN(val) || val < this.minNum)
        val = this.minNum;
      if (val > this.maxNum)
        val = this.maxNum;
      this.num = val;
      this.txt_num.text = val.toString();
      this.updatePrice();
    }
    onClickNum(index) {
      let val = parseInt(this.txt_num.text);
      if (isNaN(val) || val < this.minNum)
        val = this.minNum;
      switch (index) {
        case 0:
          val++;
          if (val > this.maxNum)
            val = this.maxNum;
          break;
        case 1:
          val--;
          if (isNaN(val) || val < this.minNum)
            val = this.minNum;
          break;
      }
      this.num = val;
      this.txt_num.text = val.toString();
      this.updatePrice();
    }
    onClickSend() {
      let num = parseInt(this.txt_num.text);
      if (isNaN(num) || num < this.minNum)
        num = this.minNum;
      if (num > this.maxNum)
        num = this.maxNum;
      this.num = num;
      this.txt_num.text = num.toString();
      if (this.input_msg.text == "")
        this.input_msg.text = "恭喜发财，把把清台";
      let title2 = this.input_msg.text;
      let toId = 0;
      if (this._data == cmd.CHAT_TO_TYPE.CTT_PLAYER) {
        toId = this._playerId;
      }
      const totype = UIManager.ins().getForm(UIChatView).getCurChatType();
      let extra = `&${title2}&${totype}&${this.num}&${toId}`;
      RechargeManager.ins().recharge(
        this.gift,
        () => {
          this.close();
        },
        extra
      );
    }
  };

  // src/script/module/chat/view/UIChatSpeakerView.ts
  var UIChatSpeakerView = class extends UITabSubView {
    get path() {
      return "ui/prefab/module/chat/UIChatSpeakerView.lh";
    }
    get layer() {
      return 2 /* Second */;
    }
    onConstruct() {
      this.btn_x = this.elems.getElement("btn_x");
      this.input = this.elems.getElement("input");
      this.input.maxChars = ChatConst.MAX_SPEAKER_INPUT_LEN;
      this.input.textIns.on(Laya.Event.INPUT, this, this.onInputCheck);
      this.btn_ok = this.elems.getUIButton("btn_ok");
      this.txt_material = this.elems.getElement("txt_material");
      this.txt_input_size = this.elems.getElement("txt_input_size");
      this.addClickListener(this.btn_ok.rootNode, this.onClickOk);
      this.addClickListener(this.btn_x, this.close);
    }
    onRegisterEvent() {
      this.registerEvent(1 /* ThingChange */, this.updateView);
    }
    onOpen(...args) {
      this.input.text = "";
      this.onInputCheck();
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      const matNum = CurrencyData.ins().getCurrency(9 /* LOUDSPEAKER */);
      this.txt_material.text = matNum.toString();
      this.txt_material.color = matNum > 0 ? ColorUtils.COLOR_ORANGE : ColorUtils.COLOR_RED;
    }
    onRedDotChange() {
    }
    /**
     * 检查输入长度超出限制
     * @param data 
     */
    onInputCheck() {
      if (this.input.text.length >= ChatConst.MAX_SPEAKER_INPUT_LEN) {
        TipsManager.ins().showMessageTips(StringUtils.format(ChatConst.INPUT_LIMIT_TIP, ChatConst.MAX_SPEAKER_INPUT_LEN));
      }
      this.txt_input_size.text = `${this.input.text.length}/${this.input.maxChars}`;
    }
    /**
     * 点击确认
     */
    onClickOk() {
      if (PlayerData.ins().level < ChatConst.UNLOCK_WORLDCHAT_SEND_LEVEL) {
        TipsManager.ins().showMessageTips(StringUtils.format(ChatConst.WORLD_LEVEL_TIP, ChatConst.UNLOCK_WORLDCHAT_SEND_LEVEL));
        return;
      }
      let content = this.input.text.trim();
      if (content.length == 0) {
        TipsManager.ins().showMessageTips(ChatConst.INPUT_EMPTY_TIP);
        return;
      }
      const num = CurrencyData.ins().getCurrency(9 /* LOUDSPEAKER */);
      if (num > 0) {
        ChatProtoUtils.chat_send_msg_tos(cmd.CHAT_TO_TYPE.CTT_WORLD, content, cmd.CHAT_TYPE.LOUDSPEAKER);
        this.close();
      } else {
        ShopManager.ins().buyItem(9 /* LOUDSPEAKER */);
      }
    }
  };

