  // src/script/module/chat/ChatManager.ts
  var ChatManager = class extends BaseClass {
    /**
     * 显示禁言提示
     * @param endDt 禁言时间 
     */
    showChatBanAlert(endDt) {
      let locDt = Date.now() / 1e3;
      let offset = endDt - locDt;
      let offsetMin = Math.round(offset / 60);
      let tips2 = "您已被禁言，还需要" + offsetMin + "分钟后自动解禁，请勿再发布违规言论，以免造成不必要的损失";
      if (endDt === 0) {
        tips2 = "您已被解封！";
      }
      TipsManager.ins().showMessageBox({
        content: tips2,
        visible_cancel: false
      });
    }
    /**
     * 和指定id玩家开始聊天
     * @param userid 玩家id ， = 0时会走向俱乐部聊天
     */
    chatTo(userid) {
      ChatData.ins().addContact(userid);
      UIManager.ins().openForm(UIChatView, 2 /* Private */, userid);
    }
    /**
     * 移除联系人
     * @param userid 玩家id
     */
    removeContact(userid) {
      ChatData.ins().removeContact(userid);
      ChatData.ins().removeStrangerContact(userid);
    }
    /**
     * 移除俱乐部新消息
     */
    removeClubNewMsg() {
      if (ClubData.ins().clubId > 0) {
        this.removeContactNewMsg(ClubData.ins().clubId);
      }
    }
    /**
     * 移除联系人新消息
     */
    removeContactNewMsg(userid) {
      if (ChatData.ins().getNewMessageNum(userid) > 0) {
        ChatData.ins().deleteNewMessage(userid);
        EventEngine.dispatchEvent(10 /* ChatChange */);
      }
    }
    //进入聊天界面 (根据普通消息进入)
    toChatView() {
      let openTab = 0 /* World */;
      let chatto = 0;
      const lobbyMsg = ChatData.ins().lobbyMsg;
      if (lobbyMsg) {
        switch (lobbyMsg.totype) {
          case cmd.CHAT_TO_TYPE.CTT_REGION:
            openTab = 1 /* Region */;
            break;
          case cmd.CHAT_TO_TYPE.CTT_CLUB:
            openTab = 2 /* Private */;
            break;
          case cmd.CHAT_TO_TYPE.CTT_PLAYER:
            if (lobbyMsg.fromid == PlayerData.ins().playerId) {
              chatto = Number(lobbyMsg.toid);
              if (SocialData.ins().isUserYourAttention(chatto)) {
                openTab = 2 /* Private */;
              } else {
                openTab = 3 /* Stranger */;
              }
            } else {
              chatto = Number(lobbyMsg.fromid);
              if (SocialData.ins().isUserYourAttention(chatto)) {
                openTab = 2 /* Private */;
              } else {
                openTab = 3 /* Stranger */;
              }
            }
            break;
        }
      }
      UIManager.ins().openForm(UIChatView, openTab, chatto);
    }
    //从聊天气泡进入聊天界面 (根据新消息列表进入)
    toChatViewOnBubble() {
      if (ChatData.ins().newMessages.size > 0) {
        for (let [key, value] of ChatData.ins().newMessages) {
          if (value > 0) {
            if (key == ClubData.ins().clubId) {
              UIManager.ins().openForm(UIChatView, 2 /* Private */, key);
            } else {
              const playerId = key;
              let openTab;
              if (SocialData.ins().isUserYourAttention(playerId)) {
                openTab = 2 /* Private */;
              } else {
                openTab = 3 /* Stranger */;
              }
              UIManager.ins().openForm(UIChatView, openTab, playerId);
            }
            break;
          }
        }
      } else {
        this.toChatView();
      }
    }
  };

