  // src/script/module/bag/BagManager.ts
  var BagManager = class extends BaseClass {
    constructor() {
      super(...arguments);
      /**
           * 新物品数组，用于记录新获得物品
           */
      this._newThingMap = {};
      /**
       * 新物品获得时，判断数组
       */
      this._newThingMarkJudgeMap = {};
    }
    /**
     * 初始化
     */
    init() {
      const json = PlayerLocalStorageManager.ins().getJson("bag", "newThingMark");
      if (json) {
        this._newThingMap = json;
      }
    }
    /**
     * 设置获得新物品决定是否保存标记的回调
     * @param maintype 物品主类型
     * @param callthis this
     * @param func 回调
     */
    setNewThingMarkJudgeFunc(maintype, callthis, func) {
      this._newThingMarkJudgeMap[maintype] = {
        callthis,
        func
      };
    }
    /**
         * 保存新物品记录
         */
    saveNewThingMarks() {
      PlayerLocalStorageManager.ins().saveString("bag", "newThingMark", JSON.stringify(this._newThingMap));
    }
    /**
     * 标记新物品已读
     */
    markNewThingRead(id) {
      const cfg = ThingData.ins().getThingConfig(id);
      if (!cfg) {
        return;
      }
      const list = this._newThingMap[cfg.maintype];
      if (!list) {
        return;
      }
      const index = list.indexOf(id);
      if (index == -1) {
        return;
      }
      list.splice(index, 1);
      this.saveNewThingMarks();
      EventEngine.dispatchEvent(1 /* ThingChange */);
    }
    /**
     * 根据物品主类型获取物品列表
     * @param maintype 物品类型
     */
    getNewThingList(maintype) {
      const list = this._newThingMap[maintype];
      if (!list) {
        return null;
      }
      return list;
    }
    /**
     * 获取物品新获得状态 true = 是
     * @param id 物品id
     */
    getNewThingStatus(id) {
      const cfg = ThingData.ins().getThingConfig(id);
      if (!cfg) {
        return false;
      }
      const list = this._newThingMap[cfg.maintype];
      if (!list) {
        return false;
      }
      const index = list.indexOf(id);
      if (index == -1) {
        return false;
      }
      return true;
    }
    /**
     * 内部使用
     */
    _addNewThing(thing) {
      const judge = this._newThingMarkJudgeMap[thing.config.maintype];
      if (judge && judge.func.apply(judge.callthis, [thing])) {
        let newList = this._newThingMap[thing.config.maintype];
        if (!newList) {
          newList = this._newThingMap[thing.config.maintype] = [];
        }
        if (newList.indexOf(thing.id) == -1) {
          newList.push(thing.id);
        }
        this.saveNewThingMarks();
      }
    }
  };

  // src/script/module/dress/DressRedDot.ts
  var DressRedDot = class extends RedDotBase {
    constructor() {
      super(1016 /* dress */);
      /**
       * 新头像数量
       */
      this.newHeadNum = 0;
      /**
       * 新头像框数量
       */
      this.newHeadFrameNum = 0;
      /**
       * 新聊天气泡数量
       */
      this.newChatBubbleNum = 0;
      /**
       * 新称号数量
       */
      this.newTitleNum = 0;
      this.setConnectedEvents(4 /* DressChange */, 1 /* ThingChange */, 22 /* TaskChange */);
    }
    doCheck() {
      this.newHeadNum = 0;
      this.newHeadFrameNum = 0;
      this.newChatBubbleNum = 0;
      this.newTitleNum = 0;
      const list = BagManager.ins().getNewThingList(5 /* dress */);
      if (list) {
        for (const id of list) {
          const dressCfg = DressData.ins().getDressCfg(id);
          if (dressCfg) {
            switch (dressCfg.type_show) {
              case 1 /* head */:
                this.newHeadNum++;
                break;
              case 2 /* head_frame */:
                this.newHeadFrameNum++;
                break;
              case 3 /* bubble */:
                this.newChatBubbleNum++;
                break;
              case 4 /* title */:
                this.newTitleNum++;
                break;
            }
          } else {
            const titleCfg = DressData.ins().getTitleCfg(id);
            if (titleCfg) {
              this.newTitleNum++;
            }
          }
        }
      }
      const titleTaskList = TaskData.ins().getTasksByType(4 /* TITLE_TASK */);
      for (const taskConfig of titleTaskList) {
        const taskStatus = TaskData.ins().getTaskStatus(taskConfig.id);
        if (taskStatus === 2) {
          const titleCfg = DressData.ins().getTitleCfgList().find((title2) => title2.title_taskid === taskConfig.id);
          if (titleCfg) {
            const isInNewList = list && list.includes(titleCfg.id);
            if (!isInNewList) {
              this.newTitleNum++;
            }
          }
        }
      }
      return this.newHeadNum + this.newHeadFrameNum + this.newChatBubbleNum + this.newTitleNum;
    }
  };

