  var DressHeadFrameItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.bg = ElemFinder.getElement(rootNode, "bg");
      this.img_icon = ElemFinder.getElement(rootNode, "bg/img_icon");
      this.img_lock = ElemFinder.getElement(rootNode, "img_lock");
      this.img_using = ElemFinder.getElement(rootNode, "img_using");
      this.frameRenderer = new FrameAnimationRenderer(this.img_icon);
      this.frameRenderer.setScale(this.img_icon.width / DressConst.defaultHeadFrameWidth);
      this.redDot = ElemFinder.getElement(rootNode, "redDot");
    }
    update(data, index) {
      this.data = data;
      const usingHeadFrame = DressData.ins().usingHeadFrame;
      const using = usingHeadFrame == data.item_id;
      const has = !ThingUtils.isThingExpired(data.item_id);
      UIUtils.setNodeFilterColor(this.bg, has ? ColorUtils.COLOR_WHITE : ColorUtils.COLOR_GRAY);
      UIUtils.setActive(this.img_lock, !has);
      UIUtils.setActive(this.img_using, using);
      const thingCfg = ThingData.ins().getThingConfig(data.item_id);
      if (thingCfg && thingCfg.effect) {
        this.img_icon.src = "";
        this.frameRenderer.load(`model2d/headFrame/${thingCfg.effect}_frame/${thingCfg.effect}_frame.lh`);
      } else {
        this.img_icon.src = DressUtils.getHeadFramePath(data.item_id);
        this.frameRenderer.destroyModel();
      }
      UIUtils.setActive(this.redDot, BagManager.ins().getNewThingStatus(data.item_id));
    }
  };

