  // src/script/module/task/utils/TaskProtoUtils.ts
  var TaskProtoUtils = class {
    /**type:请求类型 0:请求全部任务数据;1:根据ids列表请求对应id的任务数据 */
    static send_task_list_req_c2s(type = 0, ids = []) {
      let msg = new cmd.task_list_req_c2s();
      msg.type = type;
      msg.ids = ids;
      NetService.send(msg);
    }
    /**
     * 请求领奖
     */
    static send_task_reward_c2s(id = 0) {
      let msg = new cmd.task_reward_c2s();
      msg.id = id;
      NetService.send(msg);
    }
  };

