    createWxBtn() {
      let sysInfo = GamePlatform.getSystemInfoSync();
      let screenW = sysInfo.screenWidth;
      let screenH = sysInfo.screenHeight;
      let stageW = 183;
      let stageH = 63;
      let w = stageW / Laya.stage.width * screenW;
      let h = stageH / Laya.stage.height * screenH;
      let x = (screenW - w) / 2;
      let y = this.btn_ok.y / Laya.stage.height * screenH;
      if (this._wxBtn) {
        this._wxBtn.offTap(this.wxBtnOnTap);
        this._wxBtn.destroy();
        this._wxBtn = null;
      }
      if (DeviceUtils.ins().isWxGame) {
        this._wxBtn = wx.createUserInfoButton({
          type: "image",
          image: "load/ui_btn_enter_auth.png",
          withCredentials: false,
          style: {
            left: x,
            top: y,
            width: w,
            height: h,
            color: "#fff",
            backgroundColor: "",
            textAlign: "center",
            fontSize: 48,
            borderRadius: 0,
            borderColor: "#4ea72f",
            borderWidth: 0,
            lineHeight: h
          }
        });
      }
      this._wxBtn.show();
      this._wxBtn.onTap(this.wxBtnOnTap);
    }
