  // src/script/module/player/ctrl/HeadIconCtrl.ts
  var HeadIconCtrl = class {
    constructor(rootNode) {
      this.rootNode = rootNode;
      this.canOpenInfo = true;
      this.img_head = ElemFinder.getElement(rootNode, "img_head");
      this.img_frame = ElemFinder.getElement(rootNode, "img_frame");
      this.img_corner = ElemFinder.getElement(rootNode, "img_corner");
      this.frameRenderer = new FrameAnimationRenderer(this.img_frame);
      if (this.img_corner) {
        this.levelCornerRenderer = new SpineRenderer(this.img_corner);
      }
    }
    /**
     * 赋予userId后，将支持点击打开个人信息
     * @param headIcon 
     * @param headFrameId 
     * @param sex 
     * @param userId 
     * @param vipLevel VIP等级
     * @param gradeLevel 段位等级（用于角标显示）
     */
    update(headIcon, headFrameId, sex, userId = 0, vipLevel = 0) {
      this.userId = userId;
      this.img_head.src = DressUtils.getHeadIconPath(headIcon, sex);
      const headFrameCfg = ThingData.ins().getThingConfig(headFrameId);
      if (headFrameCfg && headFrameCfg.effect) {
        this.img_frame.src = "";
        this.frameRenderer.load(`model2d/headFrame/${headFrameCfg.effect}_frame/${headFrameCfg.effect}_frame.lh`);
      } else {
        this.img_frame.src = DressUtils.getHeadFramePath(headFrameId);
        this.frameRenderer.destroyModel();
      }
      if (userId > 0) {
        UIUtils.addClickListener(this.rootNode, this, this.onClickHead);
      }
      if (vipLevel <= 0) {
        this.updateLevelCorner(0);
      } else {
        this.updateLevelCorner(vipLevel);
      }
    }
    /**
     * 更新等级角标特效
     * @param vipLevel VIP等级，0不显示，>=1显示对应数字的spine动画
     */
    updateLevelCorner(vipLevel) {
      if (!this.levelCornerRenderer || !this.img_corner) {
        return;
      }
      if (vipLevel <= 0) {
        UIUtils.setActive(this.img_corner, false);
        this.levelCornerRenderer.destroyModel();
        return;
      }
      UIUtils.setActive(this.img_corner, true);
      const spinePath = "model2d/headFrame/ui_txk_xz_fx/ui_txk_xz_fx.lh";
      this.levelCornerRenderer.load(spinePath);
      this.levelCornerRenderer.onAnimStopped = null;
      this.levelCornerRenderer.loop = true;
      const animName = String(Math.min(vipLevel, 15));
      this.levelCornerRenderer.playAnim(animName);
    }
    static getVipCornerEffectPath() {
      return;
    }
    updateEmpty() {
      this.userId = 0;
      this.img_head.src = "";
      this.img_frame.src = "";
      this.frameRenderer.destroyModel();
      if (this.levelCornerRenderer) {
        this.levelCornerRenderer.destroyModel();
      }
      if (this.img_corner) {
        UIUtils.setActive(this.img_corner, false);
      }
    }
    /**
     * 更新玩家自己的头像信息
     */
    updateSelf() {
      this.update(DressData.ins().usingHeadIcon, DressData.ins().usingHeadFrame, PlayerData.ins().sex, 0, PlayerData.ins().vip);
    }
    onClickHead() {
      if (!this.userId) {
        return;
      }
      if (this.canOpenInfo) {
        PlayerManager.ins().openPersonalInfo(this.userId);
      }
    }
  };

