  // src/script/module/vip/utils/VipPrivilegeUtils.ts
  var VipPrivilegeUtils = class {
    static buildPrivilegeTypeMap(level2) {
      const map = /* @__PURE__ */ new Map();
      const cfg = ConfigUtil.Tables.vip.get(level2);
      if (!cfg) {
        return map;
      }
      for (const privId of cfg.privilege) {
        const sub = ConfigUtil.Tables.subscribe_new.get(privId);
        if (sub) {
          map.set(sub.type, sub.condition);
        }
      }
      return map;
    }
    static getPrivilegeIconIndex(previewLevel, privilegeId) {
      if (previewLevel <= 0) {
        return 1;
      }
      const cur = ConfigUtil.Tables.subscribe_new.get(privilegeId);
      if (!cur) {
        return 0;
      }
      const prevMap = this.buildPrivilegeTypeMap(previewLevel - 1);
      if (!prevMap.has(cur.type)) {
        return 1;
      }
      const prevCond = prevMap.get(cur.type);
      return prevCond !== cur.condition ? 2 : 0;
    }
  };

