  // src/script/module/vip/ctrl/VipInfoCtrl.ts
  var EXP_PER_YUAN = 10;
  function getMaxVipLevelExpLv() {
    const list = ConfigUtil.Tables.vip.getDataList();
    if (!(list == null ? void 0 : list.length)) {
      return 1;
    }
    let maxLv = -1;
    let expLv = 1;
    for (const row of list) {
      if (row.level_vip > maxLv) {
        maxLv = row.level_vip;
        expLv = row.exp_lv > 0 ? row.exp_lv : 1;
      }
    }
    return expLv;
  }
  var VipInfoCtrl = class {
    constructor(box2, enableJumpToRecharge) {
      this.box = box2;
      this.enableJumpToRecharge = enableJumpToRecharge;
      this.txt_vipLevel = ElemFinder.getText(box2, "txt_vipLevel");
      this.img_vipicon = ElemFinder.getImage(box2, "img_vipicon");
      this.txt_vipLevelNext = ElemFinder.getWidget(box2, "txt_vipLevelNext");
      this.txt_progressTip = ElemFinder.getText(box2, "txt_progressTip");
      const porRoot = ElemFinder.getElement(box2, "Por_line");
      this.porLine = porRoot;
      this.exp_txt = ElemFinder.getText(porRoot, "exp_txt");
      UIUtils.addClickListener(box2, this, this.onClickBox);
    }
    onClickBox() {
      if (!this.enableJumpToRecharge) {
        UIManager.ins().closeForm(UIRechargeView);
        UIManager.ins().openForm(UIPrivilegeTabView, 100803 /* vip */);
        return;
      }
      UIManager.ins().openForm(UIRechargeView, 0);
    }
    refresh() {
      const lvl = PlayerData.ins().vip;
      const exp = PlayerData.ins().vipExp;
      const curCfg = ConfigUtil.Tables.vip.get(lvl);
      const nextCfg = ConfigUtil.Tables.vip.get(lvl + 1);
      this.txt_vipLevel.text = String(lvl);
      this.txt_vipLevel.stroke = 2;
      this.txt_vipLevel.strokeColor = curCfg.color;
      this.img_vipicon.src = UIUtils.getImageUrl(`viplogo`, curCfg.icon);
      if (!nextCfg || !curCfg) {
        UIUtils.setActive(this.txt_vipLevelNext, false);
        this.txt_progressTip.text = "当前已达到最高级";
        this.porLine.value = 1;
        const maxDenom = getMaxVipLevelExpLv();
        this.exp_txt.text = `${exp}/${maxDenom}`;
        return;
      }
      UIUtils.setActive(this.txt_vipLevelNext, true);
      const need = curCfg.exp_lv || 1;
      this.txt_vipLevelNext.text = String(lvl + 1);
      this.exp_txt.text = `${exp}/${need}`;
      this.porLine.value = Math.min(1, need > 0 ? exp / need : 1);
      const remainExp = Math.max(0, need - exp);
      const yuan = Math.ceil(remainExp / EXP_PER_YUAN);
      this.txt_progressTip.text = `再充值${yuan}元可升级VIP`;
    }
  };

