  // src/script/module/shop/ShopManager.ts
  var ShopManager = class _ShopManager extends BaseClass {
    constructor() {
      super(...arguments);
      /**
       * 消耗请求字典
       */
      this._costRequestList = {};
    }
    /**
     * 登录后重置数据
     */
    reset() {
      this._costRequestList = {};
    }
    /**
     * 购买自定义物品
     * @param buyItem 购买参数
     */
    buyCustomItem(buyItem) {
      UIManager.ins().openForm(UIShopBuyItemView, buyItem);
    }
    /**
     * 通过道具id购买商城物品，如果配置了多个相同道具的商品，可能会异常，请使用buyShopItem接口
     * @param itemId 物品id
     * @param checkEnough 检查道具是否足够
     */
    buyItem(itemId, checkEnough = true) {
      const shopItem = ShopData.ins().getShopItemByItemId(itemId);
      if (!shopItem) {
        console.error("商品关联道具不存在：" + itemId);
        return;
      }
      const price = shopItem.config.price[0];
      _ShopManager.ins().buyCustomItem({
        buyId: 0,
        itemId,
        price: price.num,
        buyTimes: shopItem.buyTimes,
        limitTimes: shopItem.config.limit_day,
        currencyId: price.currency,
        ui_type: 1,
        buyCallback: (day, num) => {
          ShopProtoUtils.player_mall_item_buy_req_c2s(shopItem.id, day, num);
        }
      });
    }
    /**
     * 购买商城物品
     * @param id 商品id
     * @param checkEnough 检查道具是否足够
     */
    buyShopItem(id, checkEnough = true, wantBuyTimes = 1) {
      const shopItem = ShopData.ins().getShopItemById(id);
      if (!shopItem) {
        console.error("商品不存在：" + id);
        return;
      }
      const price = shopItem.config.price[0];
      _ShopManager.ins().buyCustomItem({
        buyId: id,
        itemId: shopItem.config.item_id,
        price: price.num,
        buyTimes: shopItem.buyTimes,
        limitTimes: shopItem.config.limit_day,
        currencyId: price.currency,
        ui_type: shopItem.config.type_ui,
        wantBuyTimes,
        buyCallback: (day, num) => {
          ShopProtoUtils.player_mall_item_buy_req_c2s(shopItem.id, day, num);
        }
      });
    }
    /**
     * 显示钻石不足提示 (如果足够，直接执行buySuccess)
     * @param needNum 数量
     * @param buySuccess 购买成功的行为，如果赋值，则会在现有充值文案后面附加自动购买的字样
     * @param cancelCallback 取消购买后的回调
     */
    showNoDiamondTips(needNum, buySuccess = null, cancelCallback = null) {
      if (CurrencyData.ins().diamond >= needNum) {
        if (buySuccess) {
          buySuccess();
        }
        return;
      }
      if (PlatformUtils.isHidePay()) {
        TipsManager.ins().showMessageBox({
          content: StringUtils.format(LangData.ins().getLang(3004), needNum - CurrencyData.ins().diamond),
          title: "钻石不足",
          title_ok: "去充值",
          title_cancel: "取消",
          callback_cancel: cancelCallback,
          callback_ok: () => {
            GameNavigator.ins().gotoWithClose(100002 /* coin_shop */, 0);
          }
        });
        return;
      }
      let disNum = needNum - CurrencyData.ins().diamond;
      if (disNum <= 0) {
        return;
      }
      const chargeCfg = RechargeData.ins().getShopZSGift(disNum);
      let totalGet = 0;
      if (chargeCfg) {
        chargeCfg.award.forEach((value) => {
          if (value.id == 1 /* DIAMOND */) {
            totalGet += value.num;
          }
        });
      }
      const hasSatisfiedCharge = !!chargeCfg && totalGet >= disNum;
      if (!hasSatisfiedCharge) {
        TipsManager.ins().showMessageBox({
          content: StringUtils.format(LangData.ins().getLang(3004), disNum),
          title: "钻石不足",
          title_ok: "去充值",
          visible_cancel: false,
          callback_cancel: cancelCallback,
          callback_ok: () => {
            GameNavigator.ins().gotoWithClose(100002 /* coin_shop */, 0);
          }
        });
        return;
      }
      const monthTotal = PlayerData.ins().ChargeCount || 0;
      if (!RechargeUtils.checkRechargeLimit(disNum, monthTotal)) {
        return;
      }
      let tips2 = StringUtils.format(LangData.ins().getLang(3003), disNum, chargeCfg.currency_ch, totalGet);
      TipsManager.ins().showMessageBox({
        content: tips2,
        title: "钻石不足",
        title_ok: "充值并购买",
        visible_cancel: false,
        callback_cancel: cancelCallback,
        callback_ok: () => {
          RechargeManager.ins().recharge(chargeCfg, buySuccess);
        }
      });
    }
    /**
     * 显示金币不足提示
     * @param needNum 需要数量
     * @param buySuccess 购买成功后的回调
     * @param cancelCallback 取消购买后的回调
     */
    showNoCoinTips(needNum, buySuccess = null, cancelCallback = null) {
      if (CurrencyData.ins().coin >= needNum) {
        if (buySuccess) {
          buySuccess();
        }
        return;
      }
      TipsManager.ins().showMessageTips(LangData.ins().getLang(5021));
      UIManager.ins().openForm(UIRechargeView);
    }
    /**
     * 内部使用
     * @param toc 
     */
    _player_cost_items_toc(toc) {
      let list = toc.items;
      if (list.length > 0) {
        for (const key in this._costRequestList) {
          if (Number(key) == list[0].id) {
            this._costRequestList[key]();
          }
        }
      }
      this._costRequestList = {};
    }
    /**
     * 消耗道具请求 该函数直接消耗掉目标道具，并非使用，注意区分
     * @param id 道具id
     * @param num 数量
     */
    costItemRequest(id, num, callback) {
      if (this._costRequestList[id]) {
        return;
      }
      this._costRequestList[id] = callback;
      ShopProtoUtils.player_cost_items_tos(id, num);
    }
  };

  // src/script/module/main/GameNavigator.ts
  var GameNavigator = class extends BaseClass {
    /**
     * 通过配置的link id 跳转
     * 注意 表里tab，实际需要-1才能对应代码里的页签，原因是tab默认值 = 0
     * @param linkId 跳转id
     * @param args 参数
     */
    gotoByLink(linkId, ...args) {
      const linkCfg = FuncLimitData.ins().getLinkCfg(linkId);
      if (!linkCfg) {
        console.log("linkCfg not found", linkId);
        return;
      }
      if (linkCfg.sub_funcid > 0) {
        if (linkCfg.tab > 0) {
          this.gotoWithClose(linkCfg.funcid, linkCfg.tab - 1);
        } else {
          this.gotoWithClose(linkCfg.funcid);
        }
        this.gotoWithClose(linkCfg.sub_funcid, ...args);
      } else {
        if (linkCfg.tab > 0) {
          this.gotoWithClose(linkCfg.funcid, linkCfg.tab - 1, ...args);
        } else {
          this.gotoWithClose(linkCfg.funcid, ...args);
        }
      }
    }
    _goto(funcId, autoCloseOther = true, ...args) {
      const funcCfg = FuncLimitData.ins().getFuncCfg(funcId);
      const fatherId = (funcCfg == null ? void 0 : funcCfg.father_id) || 0;
      if (fatherId) {
        if (!FuncLimitUtils.isFuncAvailable(fatherId, true)) {
          return;
        }
      }
      if (!FuncLimitUtils.isFuncAvailable(funcId, true)) {
        return;
      }
      if (fatherId == 100302 /* club */ || funcId == 100302 /* club */) {
        if (!ClubData.ins().clubId) {
          TipsManager.ins().showMessageTips("尚未加入俱乐部");
          return;
        }
      }
      if (funcId == 10000101 /* shopbuy */) {
        ShopManager.ins().buyItem(args[0]);
        return;
      }
      if (funcId != 1015 /* chat */) {
        if (autoCloseOther) {
          UIManager.ins().closeLayerForms(2 /* Second */);
        }
      }
      UIManager.ins().openFormById(funcId, ...args);
    }
    /**
     * 前往某个功能
     * @param funcId 功能id
     */
    gotoWithClose(funcId, ...args) {
      this._goto(funcId, true, ...args);
    }
    /**
     * 与goto不同，gotoKeep会保留当前的界面不关闭
     * @param funcId 功能id
     * @param args 参数
     * @returns 
     */
    gotoWithKeep(funcId, ...args) {
      this._goto(funcId, false, ...args);
    }
    /**
     * 与gotoWithClose不同，open会保留当前的界面不关闭
     * 限制是不支持跳跃部分界面
     * @param funcId 功能id
     * @param args 参数
     * @returns 
     */
    open(funcId, ...args) {
      if (!FuncLimitUtils.isFuncAvailable(funcId, true)) {
        return;
      }
      UIManager.ins().openFormById(funcId, ...args);
    }
  };

