  // src/script/module/ad/AdModule.ts
  var AdModule = class extends BaseModule {
    constructor() {
      super(...arguments);
      /**
       * 视频频控限制
       */
      this._isCanVideo = true;
      /**
       * 视频领奖回包回调
       */
      this.videoWachS2cCallBack = /* @__PURE__ */ new Map();
    }
    onInit() {
      this.registerMessage(cmd.video_watch_s2c, this.video_watch_s2c);
      this.registerMessage(cmd.player_share_click_link_toc, this.player_share_click_link_toc);
    }
    onLogin(toc) {
      AdManager.ins().init();
    }
    onAfterLogin(s2c) {
    }
    onRegisterView() {
    }
    onCrossDay(s2c) {
    }
    /**
     * 看视频完统一接口
     * @param videoId 视频点id 枚举
     * @param ext json字符串(对应功能协议需要的字段)
     * @param type 1-使用广告券 2-钻石跳过(华为鸿蒙)
     * @param callback 收到回包回调
     */
    video_watch_c2s(videoId, ext, type = 0, callback) {
      let time = 300;
      if (this._isCanVideo) {
        this._isCanVideo = false;
        let msg = new cmd.video_watch_c2s();
        msg.video_id = videoId;
        msg.ext = ext;
        if (type) {
          msg.skip_type = type;
        } else {
          let num = CurrencyData.ins().getCurrency(20 /* AD_TICKET */);
          if (num > 0) {
            msg.skip_type = 1;
          }
        }
        if (callback) {
          this.videoWachS2cCallBack.set(videoId, callback);
        }
        NetService.send(msg);
        Laya.timer.once(time, this, () => {
          this._isCanVideo = true;
        }, null, false);
      } else {
        let str = type == 2 ? "点击太快" : `看视频太快`;
        TipsManager.ins().showMessageTips(str);
        Laya.timer.once(time, this, () => {
          this._isCanVideo = true;
        }, null, false);
      }
    }
    /**
     * 视频领奖回包
     * @param toc 
     */
    video_watch_s2c(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      let callBack = this.videoWachS2cCallBack.get(toc.video_id);
      if (callBack) {
        callBack();
        this.videoWachS2cCallBack.delete(toc.video_id);
      }
    }
    /**
     * 分享点击链接
     * @param type 分享类型 ad_point 配置表id
     * @param userId 用户id
     * @param is_new 是否新用户
     * @param share_time 分享时间
     */
    player_share_click_link_tos(type, userId, is_new, share_time, encryptedData, iv) {
      let msg = new cmd.player_share_click_link_tos();
      msg.type = type;
      msg.userid = userId;
      msg.is_new = is_new;
      msg.share_time = share_time;
      msg.encryptedData = encryptedData;
      msg.iv = iv;
      NetService.send(msg);
      console.log("点击分享测试 ==  ", msg);
    }
    /**分享点击回包 */
    player_share_click_link_toc() {
    }
  };

