  // src/script/module/chat/view/UIChatGetRedPakView.ts
  var UIChatGetRedPakView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      this.cacheList = [];
      this.lastRandomIndex = -1;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/chat/UIChatGetRedPakView.lh";
    }
    onConstruct() {
      this.addClickListener(this.elems.getImage("btn_sendmsg"), this.onClickSendMsg);
      this.addClickListener(this.elems.getImage("btn_txt"), this.onClickTxt);
      this.addClickListener(this.elems.getImage("btn_close"), this.close);
      this.txt_from = this.elems.getText("txt_from");
      this.headItem = new HeadIconCtrl(this.elems.getWidget("headItem"));
      this.itemIcon = new ItemIconCtrl(this.elems.getWidget("itemIcon"));
      this.txt_titile = this.elems.getText("txt_titile");
      this.cacheList = ConfigUtil.Tables.club_news.getDataList().filter((cfg) => cfg.news_type == 2);
      this.input_msg = this.elems.getTextInput("input_msg");
    }
    onOpen(data) {
      var _a;
      if (!data)
        return;
      this._data = data;
      if (data.info) {
        this.headItem.update(data.info.head_icon, data.info.head_frame, data.info.sex, 0, (_a = data.info.vip_lvl) != null ? _a : 0);
        this.txt_from.text = data.info.nick;
      }
      this.txt_titile.text = data.context;
      this.itemIcon.update(data.items[0].id, +data.items[0].num);
    }
    onClose() {
    }
    updateView() {
    }
    onClickSendMsg() {
      let id = 0;
      if (this._data.channel == cmd.CHAT_TO_TYPE.CTT_PLAYER) {
        id = +this._data.info.userid;
      }
      if (this.input_msg.text == "") {
        TipsManager.ins().showMessageTips("请输入内容");
        return;
      }
      const totype = UIManager.ins().getForm(UIChatView).getCurChatType();
      ChatProtoUtils.chat_send_msg_tos(totype, this.input_msg.text, cmd.CHAT_TYPE.TEXT, id);
      this.close();
    }
    onClickTxt() {
      if (this.cacheList.length > 0) {
        let randomIndex;
        if (this.cacheList.length === 1) {
          randomIndex = 0;
        } else {
          do {
            randomIndex = Math.floor(Math.random() * this.cacheList.length);
          } while (randomIndex === this.lastRandomIndex);
        }
        this.lastRandomIndex = randomIndex;
        const randomItem = this.cacheList[randomIndex];
        this.input_msg.text = LangData.ins().getLang(randomItem.news_name);
      }
    }
  };

