  // src/script/module/login/LoginShareHelper.ts
  var LoginShareHelper = class extends BaseClass {
    constructor() {
      super(...arguments);
      this._shareModuleMap = {};
    }
    /**
     * 注册分享模块
     * @param funcId 功能id
     * @param module 模块
     */
    registerModule(funcId, module) {
      const oldModule = this._shareModuleMap[funcId];
      if (!oldModule) {
        this._shareModuleMap[funcId] = [module];
      } else {
        if (oldModule.includes(module)) {
          return;
        }
        oldModule.push(module);
      }
    }
    analysisShareQuery(opt) {
      if (DeviceUtils.ins().isWxGame) {
        opt = opt || GamePlatform.getLaunchOptionsSync();
        console.log("analysisShareQuery opt", opt);
        this._analysisStartScene(opt);
        this._ingestQuery(opt && opt.query || opt, opt);
      } else if (DeviceUtils.ins().isWeb) {
        opt = opt || GamePlatform.getLaunchOptionsSync();
        console.log("analysisShareQuery opt", opt);
        this._analysisStartScene(opt);
        this._ingestQuery(opt && opt.query || opt, opt);
      }
    }
    /** 解析启动场景 */
    _analysisStartScene(opt) {
      if (!opt || !DeviceUtils.ins().isWxGame && !DeviceUtils.ins().isWeb) {
        return;
      }
      const scene = Number(opt.scene);
      if (scene === 1023) {
        ShareDeskData.setAddToDesktop(true);
      }
      const sdkVersion = GamePlatform.systemInfo && GamePlatform.systemInfo.SDKVersion;
      if (sdkVersion && DeviceUtils.ins().compareVersion(sdkVersion, "2.29.1") >= 0) {
        if (scene === 1103 || scene === 1104) {
          ShareDeskData.setAddToMiniProgram(true);
        }
      } else if (scene === 1001 || scene === 1089) {
        ShareDeskData.setAddToMiniProgram(true);
      }
    }
    /** 解析分享参数 */
    _ingestQuery(query, opt) {
      if (!query || !DeviceUtils.ins().isWxGame && !DeviceUtils.ins().isWeb) {
        return false;
      }
      const queryKeys = Object.keys(query);
      if (queryKeys.length === 0) {
        console.log("冷启动 / 切前台且非分享链进入游戏，query为空");
        return false;
      }
      if (!this._isValidFroomInvite(query, opt)) {
        console.log("query 不合法  ", query);
        return false;
      }
      const funcId = Number(query.funcId);
      const modules = this._shareModuleMap[funcId];
      if (!modules) {
        return false;
      }
      for (const module of modules) {
        module.onShare(query);
      }
    }
    /** 验证是否有效的邀请分享 */
    _isValidFroomInvite(query, opt) {
      const isValidScene = opt.scene != -1;
      if (!isValidScene) {
        console.log("验证是否有效的邀请分享 ，scene为-1");
        return false;
      }
      return true;
    }
  };

