    /** 设置是否允许他人查看战绩请求返回 */
    battle_record_set_show_record_s2c(msg) {
      SetUpData.ins().isMatchHistory = msg.show_record;
      EventEngine.dispatchEvent(6 /* PlayerInfoChange */);
    }
    /** 查看战绩内其他额外的详细信息请求返回 */
    battle_record_ext_s2c(msg) {
    }
