  // src/script/module/rank/data/RankData.ts
  var _RankData = class _RankData extends BaseDataClass {
    constructor() {
      super(...arguments);
      // 球杆榜数据
      this._cueRankList = [];
      // 球杆榜加载时间
      this._cueRankLoadTime = 0;
      //球杆榜自己排名的数据
      this._selfCueRankInfo = null;
      // 财富榜数据
      this._wealthRankList = [];
      // 财富榜加载时间
      this._wealthRankLoadTime = 0;
      //财富榜自己排名的数据
      this._selfWealthRankInfo = null;
    }
    get cueRankList() {
      return this._cueRankList;
    }
    set cueRankList(value) {
      this._cueRankList = value;
      this._cueRankLoadTime = Date.now();
    }
    get selfCueRankInfo() {
      return this._selfCueRankInfo;
    }
    set selfCueRankInfo(value) {
      this._selfCueRankInfo = value;
    }
    get wealthRankList() {
      return this._wealthRankList;
    }
    set wealthRankList(value) {
      this._wealthRankList = value;
      this._wealthRankLoadTime = Date.now();
    }
    get selfWealthRankInfo() {
      return this._selfWealthRankInfo;
    }
    set selfWealthRankInfo(value) {
      this._selfWealthRankInfo = value;
    }
    /**
     * 判断是否需要重新加载排行榜数据
     * @param funcId 排行榜类型
     */
    needReloadRank(funcId) {
      switch (funcId) {
        case 0 /* CueRank */:
          return this._cueRankList.length === 0 || Date.now() - this._cueRankLoadTime > _RankData.CACHE_EXPIRE_TIME;
        case 1 /* WealthRank */:
          return this._wealthRankList.length === 0 || Date.now() - this._wealthRankLoadTime > _RankData.CACHE_EXPIRE_TIME;
        default:
          return true;
      }
    }
    /**
     * 清除指定排行榜缓存
     * @param funcId 排行榜类型
     */
    clearCache(funcId) {
      switch (funcId) {
        case 0 /* CueRank */:
          this._cueRankList = [];
          this._selfCueRankInfo = null;
          this._cueRankLoadTime = 0;
          break;
        case 1 /* WealthRank */:
          this._wealthRankList = [];
          this._selfWealthRankInfo = null;
          this._wealthRankLoadTime = 0;
          break;
      }
    }
    /**
     * 强制刷新指定排行榜
     * @param funcId 排行榜类型
     */
    forceRefresh(funcId) {
      this.clearCache(funcId);
    }
    /**
     * 获取缓存剩余有效时间（毫秒）
     * @param funcId 排行榜类型
     * @returns 剩余时间，已过期返回0
     */
    getCacheRemainingTime(funcId) {
      let loadTime = 0;
      switch (funcId) {
        case 0 /* CueRank */:
          loadTime = this._cueRankLoadTime;
          break;
        case 1 /* WealthRank */:
          loadTime = this._wealthRankLoadTime;
          break;
        default:
          return 0;
      }
    }
  };
  // 缓存有效期（5分钟）
  _RankData.CACHE_EXPIRE_TIME = 5 * 60 * 1e3;
  var RankData = _RankData;

