  // src/script/module/rank/utils/RankUtils.ts
  var RankUtils = class {
    static getMaxLoveCueId(cues) {
      let maxLove = 0;
      let maxLoveCueId = 0;
      for (let i = 0; i < cues.length; i++) {
        const cueId = cues[i].cues[0].id;
        const star = cues[i].cues[0].star || 0;
        const cueAttr = CueData.ins().getCueAttr(cueId, star);
        if (cueAttr && cueAttr.charm > maxLove) {
          maxLove = cueAttr.charm;
          maxLoveCueId = cueId;
        }
      }
      return maxLoveCueId;
    }
  };

