  // src/script/module/sevensign/data/SevenSignData.ts
  var SevenSignData = class extends BaseClass {
    constructor() {
      super(...arguments);
      /**
       * 累计签到的天数
       */
      this.sign_cnt = -1;
      /**
       * 当前领奖的天数
       */
      this.reward_day = -1;
    }
    /**
     * 根据天数获取签到奖励
     */
    getDataOfRewardByDay(day) {
      return ConfigUtil.Tables.sev_day.get(day);
    }
    /**
     * 设置累计签到的天数
     */
    setSignCnt(value) {
      this.sign_cnt = value;
    }
    /**
     * 获取累计签到的天数
     */
    getSignCnt() {
      return this.sign_cnt || 0;
    }
    /**
     * 设置已领取的奖励天数
     */
    getRewardDay() {
      return this.reward_day;
    }
    /**
     * 设置已领取的奖励天数
     */
    setRewardDay(value) {
      this.reward_day = value;
    }
  };

  // src/script/module/sevensign/utils/SevenSignUtils.ts
  var SevenSignUtils = class {
    /**
     * 
     * @param day 判断是否该天可以领取
     * @returns 
     */
    static isDaySign(day) {
      const sign_cnt = SevenSignData.ins().getSignCnt();
      const get_day = SevenSignData.ins().getRewardDay();
      if (day < 1 || day > 7) {
        throw new Error("目标天数必须在 1-7 范围内");
      }
      return day <= sign_cnt && // 目标天数需在累计签到范围内
      day > get_day;
    }
    /**
     * 判断该天是否已领取,false 未领取，true 领取
     */
    static isDayReward(day) {
      return day <= SevenSignData.ins().getRewardDay();
    }
    /**
     * 是否有未领取的签到奖励
     */
    static isHasReward() {
      return SevenSignData.ins().getRewardDay() < SevenSignData.ins().getSignCnt();
    }
    /**
     * 判断是否领取完7天奖励
     */
    static isRewardComplete() {
      return SevenSignData.ins().getRewardDay() >= 7;
    }
  };

