  // src/script/module/shop/ctrl/ShopBaseItemCtrl.ts
  var ShopBaseItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.btn_buy = ElemFinder.getUIButton(rootNode, "btn_buy");
      this.txt_limit = ElemFinder.getText(rootNode, "txt_limit");
      this.img_hot = ElemFinder.getImage(this.btn_buy.rootNode, "img_hot");
      UIUtils.addClickListener(this.btn_buy.rootNode, this, this.onClickBuy);
    }
    update(data, index, ...args) {
      this.data = data;
      const isLimited = data.config.limit_day > 0 && data.buyTimes >= data.config.limit_day;
      let showPrice = 0;
      let showCurrency = 0;
      if (isLimited) {
        this.btn_buy.setTitle("已售罄");
        this.btn_buy.grayed = true;
      } else {
        this.btn_buy.grayed = false;
        if (data.config.discount_tag != "0") {
          const discountPrice = data.config.discount[0];
          showCurrency = discountPrice.currency;
          showPrice = discountPrice.num;
        } else {
          const price = data.config.price[0];
          showCurrency = price.currency;
          showPrice = price.num;
        }
        if (SubscribeUtils.hasPrivilege(4 /* shop_sale */) && data.config.discount_if == 1) {
          showPrice = ShopUtils.getIntPrice(showPrice * SubscribeUtils.getPrivilegeValue(4 /* shop_sale */) / 100);
        }
        this.btn_buy.setTitle(ThingUtils.getThingHtmlIconPath(showCurrency, 48, 48) + `${DataFormatter.formatSpecialNumber(showPrice)}`);
      }
      if (data.config.limit_day > 0) {
        this.txt_limit.text = `限购：${data.config.limit_day - data.buyTimes}/${data.config.limit_day}`;
      } else {
        this.txt_limit.text = "";
      }
      UIUtils.setActive(this.img_hot, data.config.hot_recommend == 1);
    }
  };

