  // src/script/module/shop/ExchangeShopManager.ts
  var ExchangeShopManager = class extends BaseClass {
    /**
     * 点击兑换商品
     */
    onClickItem(item2) {
      const data = ExchangeShopData.ins();
      if (data.isOwned(item2)) {
        TipsManager.ins().showMessageTips("已拥有，无法重复购买");
        return;
      }
      if (data.isSoldOut(item2)) {
        TipsManager.ins().showMessageTips("已售罄");
        return;
      }
      if (data.canFreeExchange(item2)) {
        this.doExchangeBuy(item2);
        return;
      }
      this.openBuyView(item2);
    }
    /**
     * 打开购买弹窗
     */
    openBuyView(item2) {
      const cfg = item2.config;
      switch (cfg.type) {
        case 1:
          UIManager.ins().openForm(UIShopCueConfirmView, item2);
          break;
        case 2:
          UIManager.ins().openForm(UIShopClothesConfirmView, item2);
          break;
        case 3:
          UIManager.ins().openForm(UIShopTableConfirmView, item2);
          break;
        default:
          this.openItemBuyView(item2);
          break;
      }
    }
    openItemBuyView(item2) {
      const cfg = item2.config;
      const limitTimes = cfg.if_buy === 1 ? cfg.buy_times : 0;
      const isFree = ExchangeShopData.ins().canFreeExchange(item2);
      const buyItem = {
        buyId: cfg.id,
        itemId: cfg.item_id,
        price: this.getShowPrice(item2),
        currencyId: cfg.currency_id,
        buyTimes: item2.buyTimes,
        limitTimes,
        ui_type: 1,
        wantBuyTimes: 1,
        buyCallback: (_day, num) => {
          if (isFree) {
            ExchangeShopData.ins().markFreeUsed(cfg.id);
          }
          ShopProtoUtils.player_mall_exchange_buy_req_c2s(cfg.id, num);
        }
      };
      ShopManager.ins().buyCustomItem(buyItem);
    }
    /**
     * 获取展示价格（含每日免费）
     */
    getShowPrice(item2) {
      if (ExchangeShopData.ins().canFreeExchange(item2)) {
        return 0;
      }
      return item2.config.price;
    }
    /**
     * 执行兑换购买（货币校验后调用）
     */
    doExchangeBuy(item2, num = 1) {
      const cfg = item2.config;
      const data = ExchangeShopData.ins();
      const isFree = data.canFreeExchange(item2);
      const price = this.getShowPrice(item2) * num;
      const currencyId = cfg.currency_id;
      const doBuy = () => {
        if (isFree) {
          data.markFreeUsed(cfg.id);
        }
        ShopProtoUtils.player_mall_exchange_buy_req_c2s(cfg.id, num);
      };
      if (price <= 0) {
        doBuy();
        return;
      }
      const has = CurrencyData.ins().getCurrency(currencyId);
      if (price > has) {
        if (currencyId === 1 /* DIAMOND */) {
          ShopManager.ins().showNoDiamondTips(price, doBuy);
          return;
        }
        if (currencyId === 2 /* COIN */) {
          ShopManager.ins().showNoCoinTips(price, doBuy);
          return;
        }
        TipsManager.ins().showMessageTips(`${ThingUtils.getThingName(currencyId)}不足`);
        return;
      }
      doBuy();
    }
  };

