  var ExchangeShopItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.title_container = ElemFinder.getElement(rootNode, "title_container");
      this.txt_name = ElemFinder.getText(this.title_container, "txt_name");
      this.txt_limit = ElemFinder.getText(rootNode, "txt_limit");
      this.txt_num = ElemFinder.getText(rootNode, "txt_num");
      this.img_item = ElemFinder.getLoader(rootNode, "img_item");
      this.img_quality = ElemFinder.getImage(this.title_container, "img_quality");
      this.btn_buy = ElemFinder.getUIButton(rootNode, "btn_buy");
      this.img_hot = ElemFinder.getImage(this.btn_buy.rootNode, "img_hot");
      this.img_black = ElemFinder.getImage(rootNode, "img_black");
      this.redDot = ElemFinder.getImage(rootNode, "redDot");
      this.box_btn = ElemFinder.getElement(this.btn_buy.rootNode, "box_btn");
      this.img_curr = ElemFinder.getImage(this.box_btn, "img_curr");
      this.txt_title = ElemFinder.getText(this.box_btn, "txt_title");
      UIUtils.addClickListener(this.btn_buy.rootNode, this, this.onClickBuy);
    }
    update(data, index, ...args) {
      this.data = data;
      const cfg = data.config;
      const shopData = ExchangeShopData.ins();
      const unavailable = shopData.isUnavailable(data);
      const thingCfg = ThingData.ins().getThingConfig(cfg.item_id);
      UIUtils.setActive(this.img_black, unavailable);
      UIUtils.setActive(this.img_hot, false);
      UIUtils.setActive(this.img_curr, true);
      if (thingCfg) {
        this.txt_name.text = LangData.ins().getLang(thingCfg.name);
        const showQuality = cfg.type !== 4;
        UIUtils.setActive(this.img_quality, showQuality);
        if (showQuality) {
          this.img_quality.src = UIUtils.getImageUrl("cueQuality", thingCfg.quality.toString());
        }
        UIUtils.setActive(this.img_item, true);
        this.img_item.src = ThingUtils.getThingIconPath(cfg.item_id);
      }
      this.txt_num.text = "";
      if (cfg.if_buy === 1 && cfg.buy_times > 0) {
        this.txt_limit.text = `限购：${data.buyTimes}/${cfg.buy_times}`;
      } else {
        this.txt_limit.text = "";
      }
      let showPrice = ExchangeShopManager.ins().getShowPrice(data);
      if (unavailable) {
        if (shopData.isSoldOut(data)) {
          this.btn_buy.setTitle("已售罄");
        } else {
          this.btn_buy.setTitle("已拥有");
        }
        this.btn_buy.grayed = true;
      } else {
        this.btn_buy.grayed = false;
        const isFree = shopData.canFreeExchange(data);
        const priceText = isFree ? "免费" : DataFormatter.formatSpecialNumber(data.config.price);
        this.btn_buy.setTitle(priceText);
        UIUtils.setActive(this.img_curr, !isFree);
        if (!isFree) {
          this.img_curr.src = UIUtils.getTextureUrl("itemIcon", `icon_${cfg.currency_id}`);
        }
      }
      UIUtils.setActive(this.redDot, shopData.canFreeExchange(data));
    }
    onClickBuy() {
      if (!this.data) {
        return;
      }
      ExchangeShopManager.ins().onClickItem(this.data);
    }
  };

