  // src/script/module/shop/ShopModule.ts
  var ShopModule = class extends BaseModule {
    onInit() {
      RedDotManager.ins().registerRedDot(ShopRedDot.ins());
      FuncEntryManager.ins().registerEntryCtrl(ShopEntryCtrl);
      this.registerMessage(cmd.player_mall_item_buy_req_s2c, this.player_mall_item_buy_req_s2c);
      this.registerMessage(cmd.player_cost_items_toc, this.player_cost_items_toc);
      this.registerMessage(cmd.player_mall_list_req_s2c, this.player_mall_list_req_s2c);
      this.registerMessage(cmd.player_mall_exchange_buy_req_toc, this.player_mall_exchange_buy_req_toc);
      this.registerMessage(cmd.player_mall_exchange_free_list_toc, this.player_mall_exchange_free_list_toc);
    }
    onRegisterView() {
      UIManager.ins().registerForm(1e3 /* shop */, UIShopTabView);
      UIManager.ins().registerTabSubView(100001 /* shop_shop */, UIShopView, 1e3 /* shop */);
      UIManager.ins().registerTabSubView(
        100003 /* exchange */,
        UIShopExchangeView,
        1e3 /* shop */,
        () => ShopRedDot.ins().actived
      );
    }
    onLogin(toc) {
      ShopData.ins().onReady();
      ExchangeShopData.ins().onReady();
      ShopManager.ins().reset();
      ShopProtoUtils.player_mall_list_req_c2s();
      ShopProtoUtils.player_mall_exchange_free_list_c2s();
    }
    onAfterLogin(s2c) {
    }
    onCrossDay(s2c) {
      ShopProtoUtils.player_mall_exchange_free_list_c2s();
    }
    player_mall_item_buy_req_s2c(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      const shopItem = ShopData.ins().getShopItemById(toc.id);
      if (shopItem) {
        shopItem.buyTimes += toc.num;
      }
      if (toc.is_gift) {
        TipsManager.ins().showMessageTips("礼物已赠送给好友");
      } else {
        TipsManager.ins().showMessageTips("购买成功");
      }
      EventEngine.dispatchEvent(2 /* ShopChange */);
      EventEngine.dispatchEvent(65 /* GameToolMallBuySuccess */, [toc]);
    }
    player_cost_items_toc(toc) {
      ShopManager.ins()._player_cost_items_toc(toc);
      if (toc.result === cmd.e_error_code.SYS_SUCCESS && toc.items && toc.items.length > 0) {
        const id = toc.items[0].id;
        if (PoolGameToolData.isSuperTargetItemId(id)) {
          EventEngine.dispatchEvent(66 /* GameToolUseSuccess */, [id]);
        }
      }
    }
    /**
     * 商城信息
     * @param toc 
     */
    player_mall_list_req_s2c(toc) {
      for (const item2 of toc.buyed_list) {
        const shopItem = ShopData.ins().getShopItemById(item2.id);
        if (shopItem) {
          shopItem.buyTimes = item2.num;
        }
      }
      ExchangeShopData.ins().setBuyedList(toc.buyed_list);
      EventEngine.dispatchEvent(2 /* ShopChange */);
    }
    /**
     * 兑换商品
     * @param toc 
     */
    player_mall_exchange_buy_req_toc(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      TipsManager.ins().showMessageTips("购买成功");
      ShopProtoUtils.player_mall_list_req_c2s();
      ShopProtoUtils.player_mall_exchange_free_list_c2s();
      EventEngine.dispatchEvent(2 /* ShopChange */);
    }
    /**
     * 获取已使用的免费兑换列表
     * @param toc 
     */
    player_mall_exchange_free_list_toc(toc) {
      ExchangeShopData.ins().setFreeUsedList(toc.list);
      ExchangeShopData.ins().setExchangeList(toc.exchange_list);
      EventEngine.dispatchEvent(2 /* ShopChange */);
    }
  };

