  // src/script/module/sign/utils/SignUtils.ts
  var SignUtils = class {
    /**
     * 当前累计签到距离稀有奖励天数
     * @param day 天数
     */
    static dayOfSPReward(day) {
      let list = SignData.ins().getSPRewardDayList();
      for (let i = 0; i < list.length; i++) {
        if (list[i] - day > 0) {
          return list[i] - day;
        }
      }
      return -1;
    }
    /**
     * 获取当天是否是特殊奖励
     */
    static isSPday() {
      let list = SignData.ins().getSPRewardDayList();
      for (let i = 0; i < list.length; i++) {
        if (list[i] == SignData.ins().getDay()) {
          return true;
        }
      }
      return false;
    }
  };

  // src/script/module/sign/view/UISignView.ts
  var UISignView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      this.showCallBack = null;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/sign/UISignView.lh";
    }
    onConstruct() {
      this.list_items = this.elems.getList("list_reward");
      this.list_items.itemCtrl = SignRewardListCtrl;
      this.btn_sign = this.elems.getImage("btn_sign");
      this.txt_sign_label = this.btn_sign.getChild("txt_1");
      this.addClickListener(this.btn_sign, this.onClickSign);
      this.ad = this.getElement("btn_AD");
      this.addClickListener(this.ad, this.onClickAD);
      this.txt_adinfo = this.elems.getText("txt_adinfo");
      this.addClickListener(this.txt_adinfo, this.onClickAD);
      this.txt_info = this.elems.getText("txt_info");
      this.txt_video = this.elems.getText("txt_video");
      this.img_video = this.elems.getImage("img_video");
      this.addClickListener(this.elems.getImage("btn_close"), this.close);
    }
    onRegisterEvent() {
      this.registerEvent(16 /* SignChange */, this.updateView);
    }
    onOpen(...args) {
      if (args.length > 0) {
        this.showCallBack = args[0];
      }
      if (!SignData.ins().hasValidSignData()) {
        TipsManager.ins().showMessageTips("出错啦，数据有误。");
        this.close();
        return;
      }
      SignData.ins().setSignAdStatus(0);
      this.updateView();
    }
    onClose() {
      if (this.showCallBack) {
        this.showCallBack(true);
        this.showCallBack = null;
      }
    }
    updateView() {
      let signData = SignData.ins();
      if (!signData.hasValidSignData()) {
        this.list_items.array = [];
        return;
      }
      this.ad.visible = SignData.ins().getSignStatus() != 1;
      this.ad.mouseEnabled = SignData.ins().getSignStatus() != 2;
      const btn_sign_status = signData.getSignStatus() == 2 ? 1 : 0;
      UIUtils.setNodeCtrlStatus(this.btn_sign, btn_sign_status, "c1");
      this.btn_sign.enabled = SignData.ins().getSignStatus() != 2;
      if (this.txt_sign_label) {
        this.txt_sign_label.visible = signData.getSignStatus() != 2;
      }
      this.txt_video.visible = SignData.ins().getSignStatus() != 2;
      this.txt_video.text = SignData.ins().getSignStatus() == 1 ? "继续签到" : "视频签到";
      this.img_video.visible = SignData.ins().getSignStatus() != 2;
      const signday = signData.getSignedDays();
      const SPday = SignUtils.dayOfSPReward(signday);
      if (SPday != -1) {
        this.txt_info.text = UIUtils.getColorText(SPday.toString(), "E22B2B") + "天后出现" + UIUtils.getColorText("稀有奖励", "E22B2B") + "，已签到" + UIUtils.getColorText(signday.toString(), "E22B2B") + "天";
        if (SignUtils.isSPday()) {
          this.txt_info.text = "今天是" + UIUtils.getColorText("稀有奖励", "E22B2B") + "，已签到" + UIUtils.getColorText(signday.toString(), "E22B2B") + "天";
        }
      } else {
        TipsManager.ins().showMessageTips("出错啦，数据有误。");
        this.list_items.array = [];
        return;
      }
      const reward4 = SignData.ins().getSignDataByDay();
      if (!reward4) {
        TipsManager.ins().showMessageTips("出错啦，数据有误。");
        this.list_items.array = [];
        return;
      }
      let sourceData = signData.getSignAdStatus() == 0 ? reward4.reward_onAd : reward4.reward;
      let btn_src = SignUtils.isSPday() ? UIUtils.getImageUrl("sign", "btn_1") : UIUtils.getImageUrl("sign", "btn_0");
      this.img_video.src = SignUtils.isSPday() ? UIUtils.getImageUrl("media", "ui_qd_sp_2") : UIUtils.getImageUrl("media", "ui_qd_sp");
      this.txt_video.color = SignUtils.isSPday() ? "#6C2C02" : "#9e5621";
      this.btn_sign.src = btn_src;
      if (signData.getSignStatus() == 1) {
        sourceData = reward4.reward_again;
      }
      this.list_items.setUpdateParam(signData.getSignStatus() == 2 ? 1 : 0, reward4.type);
      this.list_items.array = sourceData;
      this.ad.getController("c1").selectedIndex = signData.getSignAdStatus();
    }
    onClickSign() {
      if (this.ad.getController("c1").selectedIndex == 1) {
        SignProtoUtils.sign_c2s();
      } else {
        AdManager.ins().showAd({
          ad_id: 1
        });
      }
    }
    onClickAD() {
      this.ad.getController("c1").selectedIndex = this.ad.getController("c1").selectedIndex == 1 ? 0 : 1;
      SignData.ins().setSignAdStatus(this.ad.getController("c1").selectedIndex);
      this.updateView();
    }
  };

