  // src/script/module/sign/SignModule.ts
  var SignModule = class extends BaseModule {
    onInit() {
      FuncEntryManager.ins().registerEntryCtrl(SignInEntryCtrl);
      RedDotManager.ins().registerRedDot(SignRedDot.ins());
      this.registerMessage(cmd.sign_s2c, this.sign_s2c);
    }
    onRegisterView() {
      UIManager.ins().registerForm(1005 /* sign_in */, UISignView);
    }
    onLogin(toc) {
    }
    onAfterLogin(s2c) {
      this.syncSignData(s2c.sign);
      EventEngine.dispatchEvent(16 /* SignChange */);
      FuncEntryManager.ins().setDirty();
    }
    onCrossDay(s2c) {
      EventEngine.dispatchEvent(16 /* SignChange */);
      FuncEntryManager.ins().setDirty();
    }
    /**
     * 同步签到数据
     */
    syncSignData(sign) {
      var _a, _b;
      const signdata = SignData.ins();
      if (!sign) {
        signdata.setSignStatus(-1);
        signdata.setDay(-1);
        return;
      }
      const signStatus = (_a = sign.sign) != null ? _a : 0;
      const cnt = (_b = sign.cnt) != null ? _b : 0;
      const day = signStatus == 0 ? cnt + 1 : cnt;
      if (cnt < 0 || day < 1 || day > 7) {
        signdata.setSignStatus(-1);
        signdata.setDay(-1);
        return;
      }
      signdata.setSignStatus(signStatus);
      signdata.setDay(day);
    }
    /**
     * 获取签到礼包数据
     * @param toc 签到
     */
    sign_s2c(toc) {
      if (toc.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(toc.result);
        return;
      }
      SignData.ins().setSignStatus(toc.sign);
      if (toc.sign == 1) {
        SignData.ins().setSignAdStatus(0);
      }
      EventEngine.dispatchEvent(16 /* SignChange */);
      FuncEntryManager.ins().setDirty();
    }
  };

