  // src/script/module/social/view/UISocialAttentionView.ts
  var UISocialAttentionView = class extends UITabSubView {
    get path() {
      return "ui/prefab/module/social/UISocialAttentionView.lh";
    }
    onConstruct() {
      this.txt_num = this.elems.getElement("txt_num");
      this.input = this.elems.getElement("input");
      this.btnSearch = this.elems.getElement("btnSearch");
      this.check_mutual = this.elems.getElement("check_mutual");
      this.txt_free = this.elems.getElement("txt_free");
      this.list_items = this.elems.getList("list_items");
      this.list_items.itemCtrl = AttentionItemCtrl2;
      this.list_items.setRenderListener(this, this.onUpdateListItemAt);
      this.btn_reward = this.elems.getUIButton("btn_reward");
      this.txt_tip = this.elems.getElement("txt_tip");
      this.addClickListener(this.btnSearch, this.onClickSearch);
      this.addClickListener(this.check_mutual, this.onClickMutSwitch);
      this.addClickListener(this.btn_reward.rootNode, this.onClickReward);
    }
    onRegisterEvent() {
      this.registerEvent(9 /* SocialChange */, this.updateView);
    }
    onOpen(...args) {
      this.check_mutual.selected = false;
      this.updateView();
      this.list_items.scrollTop();
      SocialPageManager.ins().attentionPage.startPage();
    }
    onClose() {
    }
    updateView() {
      this.txt_num.text = `(${SocialData.ins().attentionNum})`;
      if (this.check_mutual.selected) {
        let attList = SocialData.ins().getMutAttentionList();
        if (attList.length == 0) {
          this.txt_tip.visible = false;
        } else {
          this.txt_tip.visible = false;
        }
        this.list_items.array = attList;
      } else {
        let attList = SocialData.ins().getAttentionList();
        if (attList.length == 0) {
          this.txt_tip.visible = true;
        } else {
          this.txt_tip.visible = false;
        }
        this.list_items.array = attList;
      }
      const freeSendTimes = SocialData.ins().giveCoinTimes;
      const freeSendMax = SocialData.ins().getGoldSendMaxNum();
      const freeRecvTimes = SocialData.ins().receiveCoinTimes;
      const freeRecvMax = SocialData.ins().getGoldRecvMaxNum();
      this.txt_free.text = ``;
      this.btn_reward.rootNode.visible = SocialConst.enableReceiveGold;
    }
    /**
     * 点击搜索回调
     */
    onClickSearch() {
      const str = this.input.text;
      this.input.text = "";
      if (str == "") {
        TipsManager.ins().showMessageTips("玩家ID不能为空");
        return;
      }
      const userid = parseInt(str);
      if (userid == PlayerData.ins().playerId) {
        TipsManager.ins().showMessageTips("搜索的玩家为自己");
        return;
      }
      SocialProtoUtils.comm_search_player_tos(userid);
    }
    /**
     * 点击互关切换
     */
    onClickMutSwitch() {
      this.updateView();
      if (this.check_mutual.selected) {
        SocialPageManager.ins().mutAttentionPage.startPage();
      } else {
      }
    }
    /**
     * 点击一键领取/接收
     */
    onClickReward() {
      let attList = SocialData.ins().getAttentionList();
      let sendUserids = [];
      let leftSendTimes = SocialData.ins().getGoldSendMaxNum() - SocialData.ins().giveCoinTimes;
      for (let att of attList) {
        if (leftSendTimes > 0 && att.attention.mutfollow && !SocialData.ins().isGoldGive(att.attention.userid)) {
          leftSendTimes--;
          sendUserids.push(att.attention.userid);
        }
      }
      let op = false;
      if (sendUserids.length > 0) {
        op = true;
        SocialProtoUtils.comm_give_coin_tos(sendUserids);
      }
      if (SocialData.ins().canReceiveGold) {
        op = true;
        SocialProtoUtils.comm_recive_all_tos(0);
      }
      if (!op) {
        TipsManager.ins().showMessageTips("没有可收取金币");
      }
    }
    /**
     * 列表更新到当前分页终点时，请求下一页数据
     */
    onUpdateListItemAt(index) {
      if (index >= this.list_items.arrayLen - 10) {
        const page = this.check_mutual.selected ? SocialPageManager.ins().mutAttentionPage : SocialPageManager.ins().attentionPage;
        page.tryNextPage();
      }
    }
    onRedDotChange() {
      this.btn_reward.setRedDotVisible(SocialData.ins().canReceiveGold);
    }
  };
