      this.headItem.update(data.info.head_icon, data.info.head_frame, data.info.sex, data.info.userid, (_a = data.info.vip_lvl) != null ? _a : 0);
      UIUtils.setActive(this.img_each, data.attention.mutfollow);
      this._goldGiveStatus = SocialData.ins().isGoldGive(data.info.userid);
