  // src/script/module/growtask/utils/GrowTaskUtils.ts
  var GrowTaskUtils = class _GrowTaskUtils {
    // 读取novice_task任务列表
    static getNoviceTaskList() {
      return ConfigUtil.Tables.novice_task.getDataList();
    }
    // 获取成长之路的配置表的全部day
    static getGrowTaskDayList() {
      return ConfigUtil.Tables.novice_task.getDataList().map((item2) => item2.day);
    }
    // 获取目标奖励表里的枷锁星星数
    static getLockStarCount() {
      return ConfigUtil.Tables.novice_loading.getDataList().map((item2) => item2.num);
    }
    // 通过进度的index获取对应的奖励ID
    static getAwardIdByProgressIndex(index) {
      return ConfigUtil.Tables.novice_loading.getDataList()[index].reward[0].id;
    }
    // 获取所有已解锁天数内的任务id
    static getUnlockedTaskIds() {
      const unlockedDay = GrowTaskData.ins().getUnlockedDay();
      const noviceTaskConfigs = ConfigUtil.Tables.novice_task.getDataList();
      let unlockedTaskIds = [];
      noviceTaskConfigs.forEach((cfg) => {
        if (cfg.day !== void 0 && cfg.day <= unlockedDay && Array.isArray(cfg.id)) {
          unlockedTaskIds.push(...cfg.id);
        }
      });
      return unlockedTaskIds;
    }
    // 通过任务的天数获取任务配置
    static getTaskGroup(day) {
      return ConfigUtil.Tables.novice_task.get(day);
    }
    // 通过任务的id获取任务的描述
    static getTaskDescription(id) {
      const taskConfig = TaskData.ins().getTaskGroup(id);
      return taskConfig.description;
    }
    // 通过任务的id获取任务的进度文本
    static getTaskProgressText(id) {
      const taskInfo = GrowTaskData.ins().getTaskInfo(id);
      const taskConfig = TaskData.ins().getTaskGroup(id);
      return `${taskInfo.count}/${taskConfig.counter}`;
    }
    // 获取某一天任务ID，并按状态排序：2(可领奖) -> 1(进行中) -> 其他 -> 3(已领取)
    static getSortedTaskIdsByDay(day) {
      const taskGroup = this.getTaskGroup(day);
      if (!taskGroup || !Array.isArray(taskGroup.id)) {
        return [];
      }
      const taskIds = taskGroup.id.slice();
      taskIds.sort((a, b) => {
        var _a, _b, _c, _d;
        const statusA = (_b = (_a = GrowTaskData.ins().getTaskInfo(a)) == null ? void 0 : _a.status) != null ? _b : 0;
        const statusB = (_d = (_c = GrowTaskData.ins().getTaskInfo(b)) == null ? void 0 : _c.status) != null ? _d : 0;
        const priorityA = this.getTaskStatusPriority(statusA);
        const priorityB = this.getTaskStatusPriority(statusB);
        return priorityA - priorityB;
      });
      return taskIds;
    }
    static getTaskStatusPriority(status) {
      if (status === 2) {
        return 0;
      }
      if (status === 1) {
        return 1;
      }
      if (status === 3) {
        return 3;
      }
      return 2;
    }
    // 活动解锁的时间
    static getUnlockTime() {
      const unlockedDay = GrowTaskData.ins().getUnlockedDay();
      const totalDaysFixedPeriod = 7;
      let timeText = "";
      if (unlockedDay > totalDaysFixedPeriod) {
        timeText = `剩余0天`;
      } else if (unlockedDay < totalDaysFixedPeriod) {
        const remainingUnlockableDays = totalDaysFixedPeriod - unlockedDay;
        timeText = `剩余${remainingUnlockableDays}天`;
      } else {
        const currentServerTime = TimeData.ins().serverTimeS;
        const now = new Date(currentServerTime * 1e3);
        const nextMidnight = new Date(now);
        nextMidnight.setDate(now.getDate() + 1);
        nextMidnight.setHours(0, 0, 0, 0);
        let remainingSeconds = Math.max(0, Math.floor((nextMidnight.getTime() - now.getTime()) / 1e3));
        const oneHourInSeconds = 60 * 60;
        const oneMinuteInSeconds = 60;
        if (remainingSeconds > oneHourInSeconds) {
          const remainingHours = Math.ceil(remainingSeconds / oneHourInSeconds);
          timeText = `剩余${remainingHours}时`;
        } else if (remainingSeconds > oneMinuteInSeconds) {
          const remainingMinutes = Math.ceil(remainingSeconds / oneMinuteInSeconds);
          timeText = `剩余${remainingMinutes}分`;
        } else {
          timeText = `剩余1分`;
        }
      }
      return timeText;
    }
    // 获取可选择的最大天数
    static getMaxSelectableDay() {
      const dayList = _GrowTaskUtils.getGrowTaskDayList();
      if (!dayList || dayList.length === 0) {
        return 1;
      }
      return dayList.length;
    }
    // 获取选中的天数，并限制在可选择的天数范围内
    static getClampedSelectedDay(day) {
      const unlockedDay = GrowTaskData.ins().getUnlockedDay();
      const maxSelectableDay = _GrowTaskUtils.getMaxSelectableDay();
      return Math.max(1, Math.min(day, unlockedDay, maxSelectableDay));
    }
  };

