  // src/script/module/growtask/ctrl/ProgressListCtrl.ts
  var ProgressListCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.img_progress = ElemFinder.getImage(this._rootNode, "img_progress");
      this.img_progress_blue = ElemFinder.getImage(this._rootNode, "img_progress_blue");
      this.txt_progressnum = ElemFinder.getText(this._rootNode, "txt_progressnum");
      this.img_lock = ElemFinder.getImage(this._rootNode, "img_lock");
      this.img_reward = ElemFinder.getImage(this._rootNode, "img_reward");
      this.img_grow = ElemFinder.getImage(this._rootNode, "img_grow");
      this.img_ok = ElemFinder.getImage(this._rootNode, "img_ok");
      this.img_10 = ElemFinder.getImage(this._rootNode, "img_10");
      this.redDot = ElemFinder.getWidget(this._rootNode, "redDot");
      UIUtils.addClickListener(this.img_reward, this, this.onClickAward);
    }
    update(data, index, ...args) {
      this._itemData = data;
      if (!data) {
        UIUtils.setActive(this._rootNode, false);
        return;
      }
      UIUtils.setActive(this._rootNode, true);
      let id = GrowTaskUtils.getAwardIdByProgressIndex(index);
      this.img_grow.src = UIUtils.getTextureUrl("itemIcon", "icon_" + id);
      this.txt_progressnum.text = data.toString();
      const isUnlocked = data <= GrowTaskData.ins().getTotalStarCount();
      if (isUnlocked) {
        this.img_progress_blue.visible = true;
        this.img_progress.visible = false;
        this.img_lock.visible = false;
      } else {
        this.img_lock.visible = true;
        this.img_progress_blue.visible = false;
        this.img_progress.visible = true;
      }
      if (this.img_ok) {
        this.img_ok.visible = GrowTaskData.ins().isProgressRewardClaimed(data);
      }
      if (index === 3) {
        if (this.img_grow) {
          this.img_grow.scaleX = 2;
          this.img_grow.scaleY = 2;
          this.img_grow.x = -20;
          this.img_grow.y = -90;
        }
        if (this.img_reward) {
          this.img_reward.src = UIUtils.getImageUrl("growtask", "ui_cz_tbk__qq");
          this.img_reward.x = -38;
          this.img_reward.y = -105;
          this.img_lock.x = 10;
          this.img_lock.y = -70;
          this.img_lock.scaleX = 1.2;
          this.img_lock.scaleY = 1.2;
          this.img_ok.x = 10;
          this.img_ok.y = -70;
        }
      } else {
        if (this.img_grow) {
          this.img_grow.scaleX = 1;
          this.img_grow.scaleY = 1;
        }
        if (this.img_reward) {
          this.img_reward.scaleX = 1;
          this.img_reward.scaleY = 1;
        }
      }
      if (this.redDot) {
        this.redDot.visible = isUnlocked && GrowTaskData.ins().isProgressRewardClaimed(data);
      }
    }
    onClickAward() {
      const target = this._itemData;
      const starCount = GrowTaskData.ins().getTotalStarCount();
      if (starCount < target) {
        TipsManager.ins().showMessageTips("未达到领取奖励的条件");
        return;
      }
      let rewardId = 0;
      switch (target) {
        case 5:
          rewardId = 1;
          break;
        case 10:
          rewardId = 2;
          break;
        case 15:
          rewardId = 3;
          break;
        case 20:
          rewardId = 4;
          break;
        default:
          rewardId = Math.floor(target / 5);
          break;
      }
      if (rewardId > 0) {
        GrowTaskProtoUtils.send_nov_grown_cum_reward_c2s(rewardId);
      }
    }
  };

  // src/script/module/growtask/view/UIGrowTaskMainView.ts
  var UIGrowTaskMainView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      this._currentSelectedDay = 1;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/growtask/UIGrowTaskMainView.lh";
    }
    onConstruct() {
      this.txt_time = this.elems.getText("txt_time");
      this.txt_amount = this.elems.getText("txt_reward_amount");
      this.list_tab = this.elems.getList("list_tab");
      this.list_task = this.elems.getList("list_task");
      this.progressBar = this.elems.getElement("progressBar");
      this.list_progress = this.elems.getList("list_progress");
      this.list_tab.itemCtrl = DayItemListCtrl;
      this.list_task.itemCtrl = TaskItemListCtrl;
      this.list_progress.itemCtrl = ProgressListCtrl;
      this.list_tab.setClickListener(this, (index, ctrl) => {
        const selectedDay = index + 1;
        const unlockedDay = GrowTaskData.ins().getUnlockedDay();
        const unlock = selectedDay <= unlockedDay;
        if (!unlock) {
          ctrl.setSelected(false, index);
          this.list_tab.selected = Math.max(0, this._currentSelectedDay - 1);
          return;
        }
        this._currentSelectedDay = selectedDay;
        GrowTaskData.ins().setLastSelectedDay(this._currentSelectedDay);
        this.list_tab.selected = index;
        ctrl.setSelected(true, index);
        this.updateView();
      });
      this.addMuteClickListener(this.elems.getElement("btn_close"), this.close);
    }
    onRegisterEvent() {
      this.registerEvent(22 /* TaskChange */, this.updateView);
      this.registerEvent(25 /* GrowTaskChange */, this.updateView);
    }
    onOpen(...args) {
      TaskProtoUtils.send_task_list_req_c2s();
      const lastSelectedDay = GrowTaskData.ins().getLastSelectedDay();
      const targetDay = lastSelectedDay > 0 ? lastSelectedDay : GrowTaskData.ins().getUnlockedDay();
      this._currentSelectedDay = GrowTaskUtils.getClampedSelectedDay(targetDay);
      GrowTaskData.ins().setLastSelectedDay(this._currentSelectedDay);
      this.updateView();
    }
    onClose() {
    }
    updateView() {
      this.txt_time.text = GrowTaskUtils.getUnlockTime();
      const clampedDay = GrowTaskUtils.getClampedSelectedDay(this._currentSelectedDay);
      if (clampedDay !== this._currentSelectedDay) {
        this._currentSelectedDay = clampedDay;
        GrowTaskData.ins().setLastSelectedDay(this._currentSelectedDay);
      }
      this.list_task.array = GrowTaskUtils.getSortedTaskIdsByDay(this._currentSelectedDay);
      this.list_tab.array = GrowTaskUtils.getGrowTaskDayList();
      this.list_tab.selected = Math.max(0, this._currentSelectedDay - 1);
      const totalStars = GrowTaskData.ins().getTotalStarCount();
      this.txt_amount.text = totalStars.toString();
      const maxStars = 20;
      if (maxStars > 0) {
        this.progressBar.value = totalStars / maxStars * 100;
      } else {
        this.progressBar.value = 0;
      }
      this.list_progress.array = GrowTaskUtils.getLockStarCount();
    }
  };

