  // src/script/module/firstCharge/view/UIFirstChargeMainView.ts
  var UIFirstChargeMainView = class extends UIBaseView {
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/firstcharge/UIFirstChargeMainView.lh";
    }
    onConstruct() {
      this.btn_close = this.elems.getImage("img_X");
      this.addClickListener(this.btn_close, this.close);
      this.txt_price = this.elems.getText("txt_price");
      this.txt_cue_name = this.elems.getText("txt_cue_name");
      this.img_quality = this.elems.getImage("img_quality");
      this.btn_charge = this.elems.getImage("btn_charge");
      this.addClickListener(this.btn_charge, this.onClickCharge);
      this.list_reward = this.elems.getList("list_reward");
      this.list_reward.itemCtrl = RewardListCtrl;
      this.txt_btn = this.elems.getText("txt_btn");
      this.modelPos = this.elems.getWidget("modelPos");
      this.cueRenderer = new Cue2DRenderer(this.modelPos);
    }
    onRegisterEvent() {
      this.registerEvent(27 /* FirstChargeChange */, this.updateView);
    }
    onOpen(...args) {
      if (FirstChargeUtils.shouldShowDailyRedDot()) {
        FirstChargeUtils.markPageOpenedToday();
        EventEngine.dispatchEvent(27 /* FirstChargeChange */);
      }
      this.updateView();
    }
    updateView() {
      const rewardList = FirstChargeData.ins().getRewardList();
      const config = FirstChargeData.ins().getFirstChargeList()[0];
      const thingCfg = ThingData.ins().getThingConfig(config.cue_id[0]);
      const chargeConfig = ConfigUtil.Tables.charge_new.get(config.charge_id);
      this.list_reward.array = rewardList;
      this.cueRenderer.loadCue(config.cue_id[0]);
      this.cueRenderer.setScale(0.8);
      this.txt_price.text = config.discount_id.toString() + "元";
      this.txt_cue_name.text = LangData.ins().getLang(thingCfg.name);
      this.img_quality.src = UIUtils.getImageUrl("cueQuality", thingCfg.quality.toString());
      this.txt_btn.text = FirstChargeUtils.isCharged() ? "领取奖励" : chargeConfig.currency_ch + "元超值";
    }
    onClickCharge() {
      const config = FirstChargeData.ins().getFirstChargeList()[0];
      const chargeConfig = ConfigUtil.Tables.charge_new.get(config.charge_id);
      if (FirstChargeUtils.isRewardComplete()) {
        console.log("已领取，按钮禁用，不会进来");
        return;
      }
      if (FirstChargeUtils.isCharged()) {
        console.log("已充值未领取，按钮要变成领取");
        FirstChargeProtoUtils.send_player_first_charge_get_tos(config.cue_id[0]);
      } else {
        if (!chargeConfig) {
          console.error("未找到对应的充值配置！");
          return;
        }
        const monthTotal = PlayerData.ins().ChargeCount || 0;
        if (!RechargeUtils.checkRechargeLimit(parseFloat(chargeConfig.currency_ch), monthTotal)) {
          return;
        }
        RechargeManager.ins().recharge(chargeConfig, () => {
          console.log("充值成功，刷新数据");
          TipsManager.ins().showMessageTips("充值成功");
          FirstChargeProtoUtils.send_player_first_charge_info_tos();
        });
      }
    }
    onClose() {
    }
  };

