    static getLevelFromExp(exp) {
      const period = PermitData.ins().data.index;
      if (!period) {
        return 0;
      }
      const rewards = PermitData.ins().getPermitInfo(period).filter((item2) => item2.level > 0 && item2.experience > 0).sort((a, b) => a.level - b.level);
      const extraLevelCfg = PermitData.ins().getAllPermitInfo(period).find((item2) => item2.level === -1 && item2.experience > 0);
      let currentLevel = 0;
      let remainExp = exp;
      for (const reward4 of rewards) {
        if (remainExp < reward4.experience) {
          return currentLevel;
        }
        remainExp -= reward4.experience;
        currentLevel = reward4.level;
      }
      if (extraLevelCfg) {
        currentLevel += Math.floor(remainExp / extraLevelCfg.experience);
      }
      return currentLevel;
    }
    static islvEnable(level2) {
      return this.getCurrentLevel() >= level2;
    }
