  // src/script/module/daytask/ctrl/MainDayTaskListCtrl.ts
  var MainDayTaskListCtrl = class extends ListItemCtrl {
    setComponents(rootNode, index, ...args) {
      this.btn_go = ElemFinder.getElement(rootNode, "btn_go");
      UIUtils.addClickListener(this.btn_go, this, this.onClickGo);
      this.btn_finish = ElemFinder.getElement(rootNode, "btn_finish");
      UIUtils.addClickListener(this.btn_finish, this, this.onClickGet);
      this.txt_btninfo = ElemFinder.getElement(rootNode, "txt_btninfo");
      this.txt_taskdes = ElemFinder.getElement(rootNode, "txt_taskdes");
      this.pb = ElemFinder.getElement(rootNode, "pb");
      this.txt_pbdes = ElemFinder.getElement(rootNode, "txt_pbdes");
      this.img_finish = ElemFinder.getElement(rootNode, "img_finish");
      this.rewardlist = ElemFinder.getList(rootNode, "rewardlist");
      this.rewardlist.itemCtrl = ShowRewardListCtrl;
      this.redDot = ElemFinder.getWidget(this.btn_finish, "redDot");
    }
    update(data, index, ...args) {
      this.data = data;
      if (!this.data)
        return;
      const taskData = TaskData.ins();
      const taskStatus = taskData.getTaskStatus(this.data.id);
      const taskCount = taskData.getTaskCount(this.data.id);
      const targetCount = this.data.counter;
      this.txt_taskdes.text = this.data.description || "";
      this.txt_pbdes.text = "(" + taskCount + "/" + targetCount + ")";
      if (this.pb) {
        this.pb.value = taskCount / targetCount * 100;
      }
      switch (taskStatus) {
        case 0:
          this.txt_btninfo.text = "去完成";
          this.txt_btninfo.color = "#31578B";
          this.btn_go.visible = true;
          this.btn_finish.visible = false;
          this.redDot.visible = false;
          this.img_finish.visible = false;
          break;
        case 1:
          this.txt_btninfo.text = "去完成";
          this.txt_btninfo.color = "#31578B";
          this.btn_go.visible = true;
          this.btn_finish.visible = false;
          this.redDot.visible = false;
          this.img_finish.visible = false;
          break;
        case 2:
          this.txt_btninfo.text = "领取奖励";
          this.txt_btninfo.color = "#9E5621";
          this.btn_go.visible = false;
          this.btn_finish.visible = true;
          this.redDot.visible = true;
          this.img_finish.visible = false;
          break;
        case 3:
          this.txt_btninfo.text = "已完成";
          this.txt_btninfo.color = "#9E5621";
          this.btn_go.visible = false;
          this.btn_finish.visible = true;
          this.redDot.visible = false;
          this.img_finish.visible = true;
          break;
      }
      this.rewardlist.array = this.data.award;
    }
    onClickGo() {
      TaskUtils.clickTaskBtn(this.data.id);
    }
    onClickGet() {
      const status = TaskData.ins().getTaskStatus(this.data.id);
      if (status == 2) {
        console.log("任务已经完成，发送领取奖励的协议！");
        TaskProtoUtils.send_task_reward_c2s(this.data.id);
      }
    }
  };

