  // src/script/module/subscribe/SubscribeModule.ts
  var SubscribeModule = class extends BaseModule {
    onInit() {
      RedDotManager.ins().registerRedDot(SubscribeRedDot.ins());
      FuncEntryManager.ins().registerEntryCtrl(PrivilegeEntryCtrl);
      this.registerMessage(cmd.player_idol_privilege_reward_s2c, this.player_idol_privilege_reward_s2c);
      this.registerMessage(cmd.player_idol_privilege_chg_notify, this.player_idol_privilege_chg_notify);
      this.registerMessage(cmd.player_idol_privilege_lvlup_s2c, this.player_idol_privilege_lvlup_s2c);
    }
    onRegisterView() {
      UIManager.ins().registerForm(1008 /* privilege */, UIPrivilegeTabView);
      UIManager.ins().registerTabSubView(
        100802 /* subscribe */,
        UISubscribeNewView,
        1008 /* privilege */
      );
    }
    onLogin(toc) {
      SubscribeData.ins().onReady();
      let subscribeType = toc.is_subscribe >= 0 && toc.is_subscribe <= 2 ? toc.is_subscribe : 0 /* NONE */;
      SubscribeData.ins().setSubscribe(subscribeType);
    }
    onAfterLogin(s2c) {
      this.refreshData(s2c.idol_privilege);
    }
    onCrossDay(s2c) {
      this.refreshData(s2c.idol_privilege);
    }
    refreshData(data) {
      if (!data) {
        return;
      }
      SubscribeData.ins().subscribeInfo = data;
      let subscribeType = 0 /* NONE */;
      if (data.end_time > TimeData.ins().serverTimeS) {
        subscribeType = 1 /* ADVANCED */;
        if (data.is_super_vip) {
          subscribeType = 2 /* SUPER */;
        }
      }
      SubscribeData.ins().setSubscribe(subscribeType);
      EventEngine.dispatchEvent(13 /* SubscribeChange */);
    }
    /**
     * 会员每日奖励领取
     * @param s2c 
     */
    player_idol_privilege_reward_s2c(s2c) {
      if (SubscribeData.ins().subscribeInfo) {
        SubscribeData.ins().subscribeInfo.get_today_rewards = true;
      }
      EventEngine.dispatchEvent(13 /* SubscribeChange */);
    }
    /**
     * 会员激活推送
     * @param s2c 
     */
    player_idol_privilege_chg_notify(s2c) {
      this.refreshData(s2c.idol_privilege);
      MailProtoUtils.player_new_mail_info_req_tos();
    }
    player_idol_privilege_lvlup_s2c(s2c) {
      if (s2c.result != cmd.e_error_code.SYS_SUCCESS) {
        TipsManager.ins().showErrorMessageTips(s2c.result);
        return;
      }
      TipsManager.ins().showMessageTips("升级成功");
    }
  };

