  // src/script/module/lottery/data/LotteryData.ts
  var LotteryData = class _LotteryData extends BaseClass {
    constructor() {
      super(...arguments);
      /**球杆抽奖信息返回 */
      this.cueBoxInfo = null;
      /**球杆抽奖兑换商城信息返回 */
      this.cueExchangeInfo = [];
      /**球杆抽奖信息配置*/
      this.timeConfig = null;
      /**是否显示过球杆抽奖特惠礼包*/
      this.isShowBoxCueGift = false;
    }
    updateConfig() {
      if (_LotteryData.ins().cueBoxInfo != null) {
        this.timeConfig = ConfigUtil.Tables.treasure_cue_time.get(_LotteryData.ins().cueBoxInfo.id);
      }
    }
    /**
    * 用于球杆礼包红点判断
    */
    getSaveValue() {
      return parseInt(PlayerLocalStorageManager.ins().getString("Lottery", `cue_gift`)) || 0;
    }
    /**
    * 用于球杆礼包红点判断
    */
    saveValue() {
      PlayerLocalStorageManager.ins().saveString("Lottery", `cue_gift`, "1");
    }
    CheckCueDrawCountRed() {
      if (this.cueBoxInfo == null)
        return false;
      let targetRewardList = [];
      let cumulativeList = ConfigUtil.Tables.treasure_cue_cumulative.getDataList();
      for (let i = 0; i < cumulativeList.length; i++) {
        if (this.timeConfig.cumulative_id.indexOf(cumulativeList[i].id) != -1) {
          targetRewardList.push(cumulativeList[i]);
        }
      }
      for (let i = 0; i < targetRewardList.length; i++) {
        if (this.cueBoxInfo.get_list.indexOf(targetRewardList[i].id) == -1 && this.cueBoxInfo.count >= targetRewardList[i].time) {
          return true;
        }
      }
      return false;
    }
    /**
    * 检测是否可以球杆抽奖
    */
    CueBoxTryDraw(type) {
      if (this.cueBoxInfo == null) {
        console.error("球杆抽奖 数据为空");
        return;
      }
      if (type == 2) {
        if (this.cueBoxInfo.free_times > 0) {
          this.treasure_cue_draw_tos(1);
          return;
        }
      }
      let cfg = ConfigUtil.Tables.treasure_cue_time.get(this.cueBoxInfo.id);
      if (cfg == null) {
        console.error(`treasure_cue_time:${this.cueBoxInfo.id} is null`);
        return;
      }
      var itemIndex = type == 2 ? 0 : 1;
      var arr = cfg.draw_coin;
      var needItemId = arr[itemIndex][0];
      var needItemCount = arr[itemIndex][1];
      let nowHas = ThingUtils.getThingNum(needItemId);
      if (ThingUtils.isEnough(needItemId, needItemCount)) {
        this.treasure_cue_draw_tos(type);
      } else {
        if (this.isShowBoxCueGift == false && _LotteryData.ins().cueBoxInfo.gift_buy_count < cfg.discount_gift_id[1]) {
          this.isShowBoxCueGift = true;
          if (this.timeConfig.discount_gift_id.length > 0) {
            UIManager.ins().openForm(UILotteryCueGiftView, this.timeConfig.discount_gift_id[0], this.timeConfig.discount_gift_id[1], () => {
              var needBuyNum2 = needItemCount - nowHas;
              ShopManager.ins().buyShopItem(cfg.gift, false, needBuyNum2);
            });
          }
        } else {
          var needBuyNum = needItemCount - nowHas;
          ShopManager.ins().buyShopItem(cfg.gift, false, needBuyNum);
        }
      }
    }
    treasure_cue_exchange_info_tos() {
      let msg = new cmd.treasure_cue_exchange_info_tos();
      NetService.send(msg);
    }
    //type 1:自己兑换 2:赠送
    treasure_cue_exchange_tos(id, type, num, give_userid = 0) {
      let msg = new cmd.treasure_cue_exchange_tos();
      msg.id = id;
      msg.type = type;
      msg.exchange_num = num;
      msg.give_userid = Number(give_userid);
      NetService.send(msg);
    }
    /**
    * 球杆抽奖
    * @param type 1=免费单抽,2=单抽,3=十连抽
    */
    treasure_cue_draw_tos(type) {
      let msg = new cmd.treasure_cue_draw_tos();
      msg.type = type;
      NetService.send(msg);
    }
    treasure_cue_reward_tos(id) {
      let msg = new cmd.treasure_cue_reward_tos();
      msg.id = id;
      NetService.send(msg);
    }
    //type 1:自己兑换 2:赠送
    getBoxCueExchangeCount(id, type) {
      let count = 0;
      for (let i = 0; i < this.cueExchangeInfo.length; i++) {
        let temp = this.cueExchangeInfo[i];
        if (temp.id == id) {
          if (type == 1) {
            count = temp.exchange_count;
          } else {
            count = temp.give_count;
          }
        }
      }
      return count;
    }
    /**
    * 球杆抽奖——根据物品id获取奖励配置
    * @param itemId 
    */
    getConfigByItemId(itemId, num) {
      let list = ConfigUtil.Tables.treasure_cue_reward.getDataList();
      for (let i in list) {
        if (list[i].item_id === itemId && list[i].item_num === num) {
          return list[i];
        }
      }
      return null;
    }
  };

