      const itemId = selectedItem.conversion_item[0];
      const thingCfg = ThingData.ins().getThingConfig(itemId);
      if (thingCfg == null)
        return;
      if (thingCfg.maintype == 2 /* clothes */) {
        UIUtils.setNodeCtrlStatus(this.view, 2, "itemType");
        this.img_dress.src = ThingUtils.getThingIconPath(itemId);
      } else if (thingCfg.maintype == 3 /* table */) {
        UIUtils.setNodeCtrlStatus(this.view, 1, "itemType");
      } else if (thingCfg.maintype == 1 /* cue */) {
        UIUtils.setNodeCtrlStatus(this.view, 0, "itemType");
        this.cueRenderer.loadCue(itemId);
        const cueAttr = CueData.ins().getCueAttr(itemId, 0);
        this.txt_ld.text = cueAttr.force.toString();
        this.txt_js.text = cueAttr.spin.toString();
        this.txt_mzx.text = cueAttr.aim.toString();
        this.txt_ml.text = cueAttr.charm.toString();
      } else {
        UIUtils.setNodeCtrlStatus(this.view, 3, "itemType");
        this.img_item.src = ThingUtils.getThingIconPath(itemId);
      }
      this.txt_name.text = LangData.ins().getLang(thingCfg.name);
      this.img_quality.src = UIUtils.getImageUrl("cueQuality", thingCfg.quality.toString());
      UIUtils.setActive(this.txt_num, selectedItem.conversion_item[1] > 1);
      this.txt_num.text = "x" + selectedItem.conversion_item[1].toString();
      let dhCount = LotteryData.ins().getBoxCueExchangeCount(selectedItem.id, 1);
      let zsCount = LotteryData.ins().getBoxCueExchangeCount(selectedItem.id, 2);
      let nowHas = ThingUtils.getThingNum(selectedItem.integrate[0]);
      let need = selectedItem.integrate[1];
      let isHasItem = selectedItem.count === 1 && ThingUtils.isThingExpired(itemId) == false;
      if (zsCount >= selectedItem.gift_count || isHasItem === false || nowHas < need || PlayerData.ins().level < 15) {
        UIUtils.setActive(this.btn_zs, false);
        UIUtils.setActive(this.btn_zs_lock, true);
      } else {
        UIUtils.setActive(this.btn_zs, true);
        UIUtils.setActive(this.btn_zs_lock, false);
      }
      if (isHasItem || nowHas < need || dhCount >= selectedItem.count) {
        UIUtils.setActive(this.btn_dh, false);
        UIUtils.setActive(this.btn_dh_lock, true);
      } else {
        UIUtils.setActive(this.btn_dh, true);
        UIUtils.setActive(this.btn_dh_lock, false);
      }
      let tempStrZs = `${zsCount}/${selectedItem.gift_count}`;
      this.txt_limitZs.text = `限购：` + UIUtils.getColorText(tempStrZs, "#FFE430");
      let tempStrDh = `${dhCount}/${selectedItem.count}`;
      this.txt_limitDh.text = `限购：` + UIUtils.getColorText(tempStrDh, "#FFE430");
      UIUtils.setNodeCtrlStatus(this.view, selectedItem.gift_count > 0 ? 1 : 0, "isCanZs");
      this.img_dh.src = ThingUtils.getThingIconPath(selectedItem.integrate[0]);
      this.txt_dhCost.text = selectedItem.integrate[1].toString();
      this.img_zs.src = ThingUtils.getThingIconPath(selectedItem.integrate[0]);
      this.txt_zsCost.text = selectedItem.integrate[1].toString();
