  // src/script/module/poolGameRoom/view/moregame/utils/MoreGameUtils.ts
  var MoreGameUtils = class {
    // 获取配置表
    static getMoreGameCfgList() {
      return ConfigUtil.Tables.more_game.getDataList();
    }
    // 根据id获取配置
    static getMoreGameCfg(id) {
      return ConfigUtil.Tables.more_game.get(id);
    }
    // 根据入口大小类型，获取配置表数据type_size：入口尺寸类型,0表示小尺寸 1表示大尺寸
    static getMoreGameCfgListByTypeSize(typeSize) {
      return this.getMoreGameCfgList().filter((cfg) => cfg.type_size === typeSize);
    }
    // 通过id获取标签id
    static getLabelIdById(id) {
      const cfg = this.getMoreGameCfg(id);
      if (!cfg) {
        return [];
      }
      return cfg.type_label;
    }
    //判断入口是否在开放时间内，如果end_time配置为2099/1/1(即：cfg.end_time >= 4092672000000)，则认为永久开放
    static isInOpenTime(cfg) {
      const nowSec = TimeData.ins().serverTimeS;
      const FOREVER_END_MS = 4092672e6;
      if (cfg.end_time >= FOREVER_END_MS) {
        return true;
      }
      return nowSec >= cfg.begin_time && nowSec <= cfg.end_time;
    }
    // 获取在开放时间内的配置数据
    static getInOpenTimeCfgList() {
      const nowSec = TimeData.ins().serverTimeS;
      return this.getMoreGameCfgList().filter((cfg) => cfg.begin_time <= nowSec && cfg.end_time >= nowSec);
    }
    // 根据开放时间内的数据根据入口大小的类型获取配置数据
    static getInOpenTimeCfgListByTypeSize(typeSize) {
      return this.getInOpenTimeCfgList().filter((cfg) => cfg.type_size === typeSize);
    }
    // 根据id获取配置的入口资源图
    static getEntryImageUrl(id) {
      const cfg = this.getMoreGameCfg(id);
      if (!cfg) {
        return "";
      }
      return cfg.img;
    }
  };

