  // src/script/module/activityWelfare/view/UIActivityWelfareView.ts
  var UIActivityWelfareView = class extends UIBaseView {
    constructor() {
      super(...arguments);
      /** 与 `enter_control.father_id` 对齐：本工程为 `EFuncID.welfare`（象棋工程为 welfare_activity） */
      this.fatherId = 1023 /* welfare */;
      /** 上一秒 tick 时的服务器时间（秒），用于 `TimeUtils.isSameDay` 检测跨天 */
      this._welfareTickLastServerSec = -1;
    }
    get layer() {
      return 2 /* Second */;
    }
    get path() {
      return "ui/prefab/module/activityWelfare/UIActivityWelfareView.lh";
    }
    onConstruct() {
      this.btn_close = this.elems.getElement("btn_close");
      this.addClickListener(this.btn_close, this.close);
      this.list_mode = this.elems.getList("list_mode");
      this.list_mode.itemCtrl = WelfareActivityItemCtrl;
      this.list_mode.setClickListener(this, this.onClickModeItem);
    }
    onRegisterEvent() {
      this.registerEvent(43 /* LuckyWheelChange */, this.onLuckyWheelChange);
      this.registerEvent(44 /* ShakeTreeChange */, this.onShakeTreeChange);
      this.registerEvent(46 /* GameWelfareChange */, this.onGameWelfareChange);
    }
    onOpen() {
      this._welfareTickLastServerSec = -1;
      LuckyWheelProtoUtils.info_c2s();
      ShakeTreeProtoUtils.info_c2s();
      GameWelfareProtoUtils.info_c2s();
      this.updateModeList();
      Laya.timer.clear(this, this.onWelfareTimeTick);
      Laya.timer.loop(1e3, this, this.onWelfareTimeTick);
      this.onWelfareTimeTick();
    }
    onLuckyWheelChange() {
      this.list_mode.refresh();
    }
    onShakeTreeChange() {
      this.list_mode.refresh();
    }
    onGameWelfareChange() {
      this.updateModeList();
      this.list_mode.refresh();
    }
    onClose() {
      Laya.timer.clear(this, this.onWelfareTimeTick);
      this._welfareTickLastServerSec = -1;
    }
    /**
     * 每秒刷新列表项结束时间。
     * 服务器跨天时整表刷新（与 `TimeUtils.isSameDay` 口径一致）并中断本轮 item 更新。
     * 若有 `continue_day=-1` 且表 `time_end` 已到期则整表刷新。
     * 若任一项在 `FuncEntryData._enterEndTimeDic` 中有截止且已到期（如对局福利协议 end_time）同样整表刷新，避免列表残留。
     */
    onWelfareTimeTick() {
      const serverSec = TimeData.ins().serverTimeS;
      if (this._welfareTickLastServerSec >= 0 && !TimeUtils.isSameDay(this._welfareTickLastServerSec, serverSec)) {
        this.updateModeList();
        this._welfareTickLastServerSec = serverSec;
        return;
      }
      const arr = this.list_mode.array;
      if (arr && arr.length > 0) {
        for (let i = 0; i < arr.length; i++) {
          const cfg = arr[i];
          if (cfg.continue_day !== -1) {
            continue;
          }
          const endSec = TimeUtils.parseTimeToUnixSeconds(cfg.time_end);
          if (endSec <= 0 || serverSec >= endSec) {
            this.updateModeList();
            this._welfareTickLastServerSec = serverSec;
            return;
          }
        }
        for (let k = 0; k < arr.length; k++) {
          const endDic = FuncEntryData.ins().getEnterEndTimeSec(arr[k].id);
          if (endDic > 0 && serverSec >= endDic) {
            this.updateModeList();
            this._welfareTickLastServerSec = serverSec;
            return;
          }
        }
      }
      const ctrls = this.list_mode.getItemCtrlList();
      for (let j = 0; j < ctrls.length; j++) {
        ctrls[j].refreshTimeText(serverSec);
      }
      this._welfareTickLastServerSec = serverSec;
    }
    updateView() {
      this.updateModeList();
    }
    updateModeList() {
      let cfgList = FuncLimitUtils.getChildEntryList(this.fatherId).filter(
        (cfg) => cfg.id !== 102303 /* game_welfare */ || GameWelfareData.ins().shouldShowActivityEntry()
      );
      this.list_mode.array = cfgList;
    }
    onClickModeItem(index, ctrl) {
      if (!ctrl || !ctrl.cfg) {
        return;
      }
      if (!FuncLimitUtils.isFuncAvailableByCfg(ctrl.cfg, true)) {
        return;
      }
      GameNavigator.ins().gotoWithKeep(ctrl.cfg.id);
    }
  };
  var WelfareActivityItemCtrl = class extends ListItemCtrl {
    setComponents(rootNode) {
      this.img_icon = ElemFinder.getLoader(rootNode, "btn_mode/img_icon");
      this.img_red = ElemFinder.getImage(rootNode, "btn_mode/img_red");
      this.txt_time = ElemFinder.getText(rootNode, "btn_mode/txt_time");
    }
    update(cfg) {
      this.cfg = cfg;
      this.img_icon.src = UIUtils.getImageUrl("activityWelfare", cfg.icon);
      const showLuckyWheelRed = cfg.id === 102301 /* turntable */ && LuckyWheelData.ins().hasFreeToday;
      const showShakeTreeRed = cfg.id === 102302 /* rich_tree */ && ShakeTreeData.ins().hasFreeToday;
      const showGameWelfareRed = cfg.id === 102303 /* game_welfare */ && GameWelfareData.ins().hasAnyClaimableBeforeEnd();
      UIUtils.setActive(this.img_red, showLuckyWheelRed || showShakeTreeRed || showGameWelfareRed);
      this.refreshTimeText(TimeData.ins().serverTimeS);
    }
    /**
     * 倒计时文案：`FuncEntryData` 有该功能截止秒数时优先（与 `isEnterControlActivityTimeValid` 一致），
     * 否则再按 `continue_day` / `time_end`。
     */
    refreshTimeText(serverSec) {
      if (!this.cfg || !this.txt_time) {
        return;
      }
      const endDic = FuncEntryData.ins().getEnterEndTimeSec(this.cfg.id);
      if (endDic > 0) {
        const remain = endDic - serverSec;
        if (remain <= 0) {
          this.txt_time.text = "";
          return;
        }
        this.txt_time.text = this.getTimeText(remain);
        return;
      }
      if (this.cfg.continue_day === 0) {
        this.txt_time.text = "永久";
        return;
      }
      if (this.cfg.continue_day === -1) {
        const endSec = TimeUtils.parseTimeToUnixSeconds(this.cfg.time_end);
        const remain = endSec - serverSec;
        if (remain <= 0) {
          this.txt_time.text = "";
          return;
        }
        this.txt_time.text = this.getTimeText(remain);
        return;
      }
      this.txt_time.text = "";
    }
    getTimeText(remain) {
      if (remain < 3600) {
        return TimeUtils.convertTimeFormat(remain, 11 /* ONLIMETIME */);
      } else {
        let timeStr = "";
        let d = Math.floor(remain / (60 * 60 * 24));
        let h = Math.floor((remain - d * 24 * 60 * 60) / (60 * 60));
        timeStr += `<font color='#0CFF00'>${d}</font>天`;
        timeStr += `<font color='#0EE501'>${h}</font>小时`;
        return timeStr;
      }
    }
  };

