  var LuckyWheelConfigUtils = class {
    static getSortedSlots() {
      const list = ConfigUtil.Tables.turntable.getDataList().slice();
      list.sort((a, b) => a.id - b.id);
      return list;
    }
    /** 第 slotIndex（0~7）格对应的配置行 id，用于与 draw_ids / 中奖 id 对齐 */
    static getSlotIdByIndex(slotIndex) {
      const all = this.getSortedSlots();
      const row = all[slotIndex];
      if (row) {
        return row.id;
      }
      return slotIndex + 1;
    }
    /**
     * 服务端中奖格 id → 预制体 `LuckyWheelItemGrid_*` 下标（0~7）。
     * 约定：id 为 **1~8** 时表示转盘第几格（第 1 格 = 下标 0），与配置表主键 id 无关。
     * 其它 id 再按 `turntable` 行 id 查找下标。
     */
    static getIndexBySlotId(slotId) {
      if (slotId >= 1 && slotId <= 8) {
        return slotId - 1;
      }
      const all = this.getSortedSlots();
      const idx = all.findIndex((c) => c.id === slotId);
      if (idx >= 0) {
        return idx;
      }
      return 0;
    }
    /**
     * 单格奖励展示：支持「多行配置（每行 reward1）」或「单行 + reward1 多段」形态。
     * 本工程 `turntable` 无 `free_lucky` 字段，由 `reward1` 推导展示。
     */
    static getDisplayForSlotIndex(slotIndex) {
      const all = this.getSortedSlots();
      if (!all.length) {
        return { itemId: 0, num: 0 };
      }
      if (all.length === 1) {
        const row2 = all[0];
        const rewards = row2.reward1 || [];
        const seg = rewards[slotIndex];
        if (seg && seg.id > 0) {
          return { itemId: seg.id, num: Number(seg.num || 0) };
        }
        const first = rewards[0];
        if (first && first.id > 0) {
          return { itemId: first.id, num: Number(first.num || 0) };
        }
        return { itemId: 0, num: 0 };
      }
      const row = all[slotIndex];
      if (!row) {
        return { itemId: 0, num: 0 };
      }
      const pair = row.reward1 && row.reward1.length > 0 ? row.reward1[0] : null;
      if (pair && pair.id > 0) {
        return { itemId: pair.id, num: Number(pair.num || 0) };
      }
      return { itemId: 0, num: 0 };
    }
  };

