      this.txt_step2_desc = this.elems.getText("txt_step2_desc");
      this.txt_step3_desc = this.elems.getText("txt_step3_desc");
      this.txt_reward_title = this.elems.getText("txt_reward_title");
      this.txt_get = this.elems.getText("txt_get");
