  var AwardTipsQueue = class extends BaseClass {
    constructor() {
      super(...arguments);
      this.awards_list = [];
      /**
       * 需要展示的特殊列表
       */
      this._showSpList = [];
      /**
       * 最终需要展示的道具列表
       */
      this._showAwards = [];
    }
    addAwards(awards, type) {
      this._type = type;
      this.awards_list.push(awards);
      this.processNext();
    }
    clearAwards() {
      this.awards_list = [];
    }
    processNext() {
      if (this._isShowing) {
        return;
      }
      if (this.awards_list.length == 0) {
        return;
      }
      this._isShowing = true;
      this._showSpList.length = 0;
      this._showAwards = this.awards_list.splice(0, 1)[0];
      for (const award of this._showAwards) {
        const thingCfg = ThingData.ins().getThingConfig(award.id);
        if (!thingCfg) {
          continue;
        }
        switch (thingCfg.maintype) {
          case 3 /* table */:
          case 2 /* clothes */:
            this._showSpList.push({
              id: award.id,
              viewclass: UIAwardShowIconView
            });
            break;
          case 1 /* cue */:
            this._showSpList.push({
              id: award.id,
              viewclass: UIAwardShowCueView
            });
            break;
        }
      }
      this.processSpList();
    }
    processSpList() {
      if (this._showSpList.length == 0) {
        this.processFinal();
        return;
      }
      const sp = this._showSpList.splice(0, 1)[0];
      UIManager.ins().openForm(sp.viewclass, sp.id).setCloseCallback(() => {
        this.processSpList();
      });
    }
    processFinal() {
      switch (this._type) {
        case 1 /* COMMON */:
          UIManager.ins().openForm(UIAwardTipsView, this._showAwards).setCloseCallback(() => {
            this._isShowing = false;
            this.processNext();
          });
          break;
        case 2 /* BATTLE_PASS */:
          let allAwards = PermitData.ins().getAllPermitInfo(this._showAwards[0].id);
          const claimedReward = allAwards.find((item2) => item2.id === this._showAwards[0].id);
          if (claimedReward) {
            UIManager.ins().openForm(UIPermitRewardGetView, [claimedReward]);
          }
          this._isShowing = false;
          this.processNext();
          break;
      }
    }
  };

  // src/script/module/main/utils/FuncLimitUtils.ts
  var FuncLimitUtils = class {
    /**
     * 判断功能是否开启
     * @param id 功能id
     * @param prompt 是否弹窗提示 默认 = false
     */
    static isFuncAvailable(id, prompt = false) {
      const cfg = FuncLimitData.ins().getFuncCfg(id);
      return this.isFuncAvailableByCfg(cfg);
    }
    static isFuncAvailableByCfg(cfg, prompt = false) {
      if (!cfg) {
        return true;
      }
      if (cfg.open_lv > 0 && PlayerData.ins().level < cfg.open_lv) {
        if (prompt) {
          TipsManager.ins().showMessageTips(`等级达到${cfg.open_lv}级开启，快去对局提升吧!`);
        }
        return false;
      }
      if (cfg.show == 1) {
        if (prompt) {
          TipsManager.ins().showMessageTips(`活动已关闭`);
        }
        return false;
      }
      let isTimeValid = FuncEntryData.ins().isEnterControlActivityTimeValid(cfg);
      if (!isTimeValid) {
        if (prompt) {
          TipsManager.ins().showMessageTips(`活动已关闭`);
        }
        return false;
      }
      return true;
    }
    /**
     * 读取入口控制表
     */
    static getEntryList(pos) {
      return ConfigUtil.Tables.enter_control.getDataList().filter((cfg) => cfg.place == pos);
    }
    /**
     * 读取指定父功能下的子入口控制表
     */
    static getChildEntryList(fatherId) {
      return ConfigUtil.Tables.enter_control.getDataList().filter(
        (cfg) => cfg.father_id == fatherId && this.isFuncAvailableByCfg(cfg)
      ).sort((a, b) => a.order - b.order);
    }
  };

